INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-1-u2-C1','soc',3,1,'u2',1,'시간을 나타내는 말 — 과거 = 이미 지나간 때(어제 · 작년 · 옛날 · 지난주) · 현재 = 지금 살아가는 때(오늘 · 지금) · 미래 = 앞으로 올 때(내일 · 내년 · 앞으로) · 시간은 과거 → 현재 → 미래로 한 방향으로 흐르고 되돌릴 수 없음',ARRAY['[4사02-01] 시간을 나타내는 말을 알고, 나와 가족·학교에 있었던 중요한 일을 조사해 시간의 흐름에 따라 연표로 정리한다(차시 머리 표기 · 문구 초안)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-1-u2-C2','soc',3,1,'u2',2,'나에게 있었던 중요한 일 — 중요한 일 = 나에게 특별하거나 기억에 남는 일(태어남 · 입학) · 자라 온 과정을 시간 순서대로 떠올림 · 과거의 나와 지금의 나를 견주면 변화가 보임 · 사진 · 앨범 · 가족 이야기가 도움 · 사람마다 겪은 일이 다름',ARRAY['[4사02-01] 시간을 나타내는 말을 알고, 나와 가족·학교에 있었던 중요한 일을 조사해 시간의 흐름에 따라 연표로 정리한다(차시 머리 표기 · 문구 초안)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-1-u2-C3','soc',3,1,'u2',3,'가족 · 학교의 중요한 일 조사하기 — 사진 · 앨범 보기 · 어른께 여쭤보기(면담) · 누리집 기록 살펴보기 · 조사 방법에 맞는 자료 · 옛 학교와 지금 학교를 견주면 달라진 점 · 조사한 일은 시간 순서대로 연표로',ARRAY['[4사02-01] 시간을 나타내는 말을 알고, 나와 가족·학교에 있었던 중요한 일을 조사해 시간의 흐름에 따라 연표로 정리한다(차시 머리 표기 · 문구 초안)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-1-u2-C4','soc',3,1,'u2',4,'연표 — 일이 일어난 때에 따라 차례대로 나타낸 표 · 때(나이 · 연도)와 있었던 일을 함께 · 왼쪽에서 오른쪽으로 갈수록 나중 일 · 순서와 변화가 한눈에 · 나뿐 아니라 가족 · 학교 · 마을의 일도',ARRAY['[4사02-01] 시간을 나타내는 말을 알고, 나와 가족·학교에 있었던 중요한 일을 조사해 시간의 흐름에 따라 연표로 정리한다(차시 머리 표기 · 문구 초안)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-1-u2-C5','soc',3,1,'u2',5,'연표 만드는 차례 — 있었던 일과 자료 모으기 → 시간 순서 정하기 → 시간 띠에 때와 일 적기 → 그림 · 사진 · 설명으로 꾸미기 · 꾸미기보다 순서가 먼저 · 소개할 때 언제 무슨 일이 있었는지 함께',ARRAY['[4사02-01] 시간을 나타내는 말을 알고, 나와 가족·학교에 있었던 중요한 일을 조사해 시간의 흐름에 따라 연표로 정리한다(차시 머리 표기 · 문구 초안)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-1-u2-C6','soc',3,1,'u2',6,'시간의 흐름 정리 · 타임캡슐 — 타임캡슐 = 지금의 물건 · 편지를 담아 두었다가 먼 미래에 꺼내 봄(현재를 미래에 전함) · 시간을 나타내는 말 → 중요한 일 → 조사 → 연표(소단원 정리)',ARRAY['[4사02-01] 시간을 나타내는 말을 알고, 나와 가족·학교에 있었던 중요한 일을 조사해 시간의 흐름에 따라 연표로 정리한다(차시 머리 표기 · 문구 초안)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-1-u2-C7','soc',3,1,'u2',7,'옛 생활 모습을 알려 주는 단서 — 옛날은 직접 갈 수 없지만 그때부터 남아 있는 것으로 앎 · 옛 사진(그때 모습 그대로) · 옛 건축물(살던 집) · 오래된 물건 · 옛 기록 · 미래의 것은 단서가 아님 · 여러 가지를 함께 볼수록 잘 앎',ARRAY['[4사02-02] 옛 사진·오래된 물건·건축물·자료·증언으로 주변에서 만나는 과거의 생활 모습을 탐색한다(차시 머리 표기 · 문구 초안)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-1-u2-C8','soc',3,1,'u2',8,'오래된 물건으로 본 옛 생활 — 물건의 쓰임을 보면 생활 모습 · 맷돌(곡식 갈기) ↔ 믹서기 · 다듬잇돌과 방망이 · 숯다리미(옷 펴기) ↔ 전기다리미 · 가마솥(밥) · 재봉틀(옷) · 오래 간직한 소중한 물건에도 과거가 담김',ARRAY['[4사02-02] 옛 사진·오래된 물건·건축물·자료·증언으로 주변에서 만나는 과거의 생활 모습을 탐색한다(차시 머리 표기 · 문구 초안)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-1-u2-C9','soc',3,1,'u2',9,'옛 자료와 증언 — 옛 신문 · 잡지 · 포스터 = 글과 그림으로 남긴 자료(그때 일과 생활) · 증언 = 그때를 직접 겪은 어른께 여쭤 듣는 이야기 · 자료와 증언을 함께 보면 더 자세하고 정확함',ARRAY['[4사02-02] 옛 사진·오래된 물건·건축물·자료·증언으로 주변에서 만나는 과거의 생활 모습을 탐색한다(차시 머리 표기 · 문구 초안)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-1-u2-C10','soc',3,1,'u2',10,'자료를 분석해 과거 살펴보기 — 살펴볼 자료 고르기 → 자세히 살펴보기(옷차림 · 물건 · 거리 · 글자) → 보이는 것에서 알게 된 것 정리하기 → 친구와 나누기 · 자료에 없는 것은 지어내지 않음 · 같은 자료라도 친구는 다른 것을 찾음',ARRAY['[4사02-02] 옛 사진·오래된 물건·건축물·자료·증언으로 주변에서 만나는 과거의 생활 모습을 탐색한다(차시 머리 표기 · 문구 초안)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-1-u2-C11','soc',3,1,'u2',11,'옛 생활 모습 전시관 꾸미기 — 전시 주제 정하기 → 주제에 맞는 자료 모으기 → 설명 카드(이름과 쓰임) 쓰기 → 보기 좋게 놓고 무엇을 왜 전시했는지 소개하기',ARRAY['[4사02-02] 옛 사진·오래된 물건·건축물·자료·증언으로 주변에서 만나는 과거의 생활 모습을 탐색한다(차시 머리 표기 · 문구 초안)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-1-u2-C12','soc',3,1,'u2',12,'주변에서 만나는 과거 정리 — 옛 생활은 사진 · 건축물 · 물건 · 자료 · 증언으로 앎 · 옛 생활을 알면 오늘을 더 잘 이해하고 소중히 여김 · 박물관은 옛 물건을 모아 전함 · 오늘의 사진 · 물건 · 기록도 먼 훗날 과거를 알려 주는 자료가 됨 · 지역 축제는 옛 생활을 기려 전함',ARRAY['[4사02-02] 옛 사진·오래된 물건·건축물·자료·증언으로 주변에서 만나는 과거의 생활 모습을 탐색한다(차시 머리 표기 · 문구 초안)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-1-u2-C13','soc',3,1,'u2',13,'지역의 옛 모습을 알려 주는 자료 — 우리 지역(고장)도 오랜 시간 동안 달라짐 · 옛 사진 · 지도(거리와 건물) · 옛 신문 · 기록(그때 일과 소식) · 옛이야기와 어른의 증언 · 영상 자료(움직임과 소리)',ARRAY['[4사02-03] 여러 자료와 옛이야기로 지역의 옛 모습을 알아보고, 지역 사람들의 달라진 생활 모습을 조사해 표현한다(차시 머리 표기 · 문구 초안)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-1-u2-C14','soc',3,1,'u2',14,'옛이야기와 땅 이름 — 옛이야기 = 오래전부터 입에서 입으로 전해 온 이야기(전설 · 땅 이름 유래) · 그 지역 사람들의 생활과 바람 · 생각이 담김 · 땅 이름에 옛날 그곳의 모습이나 있었던 일이 담김 · 어른께 듣기 · 책 · 지역 누리집에서 찾음',ARRAY['[4사02-03] 여러 자료와 옛이야기로 지역의 옛 모습을 알아보고, 지역 사람들의 달라진 생활 모습을 조사해 표현한다(차시 머리 표기 · 문구 초안)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-1-u2-C15','soc',3,1,'u2',15,'여러 자료로 지역의 옛 모습 살펴보기 — 자료마다 알려 주는 것이 다름 — 사진(모습) · 신문 · 기록(소식) · 영상(움직임과 소리) · 함께 보고 자세히 비교할수록 정확 · 한 가지만 보고 다 안다고 하지 않음',ARRAY['[4사02-03] 여러 자료와 옛이야기로 지역의 옛 모습을 알아보고, 지역 사람들의 달라진 생활 모습을 조사해 표현한다(차시 머리 표기 · 문구 초안)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-1-u2-C16','soc',3,1,'u2',16,'지역 사람들의 달라진 생활 조사하기 — 조사 계획(무엇을 · 어떻게 · 언제 · 누구와) → 자료 모으기 → 옛날과 오늘 나란히 비교하기 → 조사 보고서(조사한 내용 · 알게 된 점) · 문화 해설사 = 지역의 옛 모습을 찾아 알기 쉽게 알려 주는 사람',ARRAY['[4사02-03] 여러 자료와 옛이야기로 지역의 옛 모습을 알아보고, 지역 사람들의 달라진 생활 모습을 조사해 표현한다(차시 머리 표기 · 문구 초안)']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-1-u2-C17','soc',3,1,'u2',17,'영상으로 달라진 모습 표현하기 — 보여 줄 자료 고르기 → 차례 정하기(옛날 → 오늘) → 설명(자막) 붙이기 → 무엇을 왜 만들었는지 소개하기',ARRAY['[4사02-03] 여러 자료와 옛이야기로 지역의 옛 모습을 알아보고, 지역 사람들의 달라진 생활 모습을 조사해 표현한다(차시 머리 표기 · 문구 초안)']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X01','soc',3,'u2',ARRAY['SO3-1-u2-C1']::text[],'과거 · 현재 · 미래를 나타내는 말을 바꾸어 안다(어제를 앞으로 올 때로, 내일을 지나간 때로)','지나간 때 · 지금 · 앞으로 올 때') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X02','soc',3,'u2',ARRAY['SO3-1-u2-C1','SO3-1-u2-C6']::text[],'시간이 거꾸로 흐르거나 멈춰 있다고 여기거나, 시간의 차례를 미래에서 과거로 놓는다','과거 → 현재 → 미래') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X03','soc',3,'u2',ARRAY['SO3-1-u2-C2','SO3-1-u2-C4','SO3-1-u2-C5']::text[],'일어난 일의 차례를 섞어 늘어놓는다(입학을 태어남보다 먼저)','가장 먼저 일어난 일부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X04','soc',3,'u2',ARRAY['SO3-1-u2-C2']::text[],'시간이 흘러도 나는 변하지 않는다고 여긴다','과거의 나와 지금의 나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X05','soc',3,'u2',ARRAY['SO3-1-u2-C2']::text[],'중요한 일은 누구에게나 똑같다고 여기거나 친구의 다른 경험을 무시한다','사람마다 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X06','soc',3,'u2',ARRAY['SO3-1-u2-C2','SO3-1-u2-C3','SO3-1-u2-C7']::text[],'지난 일을 알려 주는 자료로 미래의 것이나 지난 일과 상관없는 것(일기 예보 · 계획표)을 고른다','지나간 일을 담은 자료') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X07','soc',3,'u2',ARRAY['SO3-1-u2-C3']::text[],'면담을 혼자 상상하거나 사진을 보는 일로 여기거나, 조사 방법과 자료를 엇갈려 짝짓는다','면담은 어른께 여쭤보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X08','soc',3,'u2',ARRAY['SO3-1-u2-C3','SO3-1-u2-C16']::text[],'옛 모습과 지금 모습을 견주지 않거나, 학교 · 집 · 물건은 시간이 흘러도 그대로라고 여긴다','견주면 달라진 점이 보여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X09','soc',3,'u2',ARRAY['SO3-1-u2-C4']::text[],'연표를 날씨표 · 계산표 · 그림일기처럼 다른 것으로 여긴다','때와 일을 차례대로 적은 표') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X10','soc',3,'u2',ARRAY['SO3-1-u2-C4','SO3-1-u2-C5']::text[],'연표에 때와 일 가운데 하나만 적거나 상관없는 것(색깔 · 주소)을 적는다','언제 · 무슨 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X11','soc',3,'u2',ARRAY['SO3-1-u2-C4','SO3-1-u2-C5']::text[],'연표에서 가장 중요한 것을 색깔이나 꾸미기라고 여겨 순서를 마음대로 정한다','연표는 순서가 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X12','soc',3,'u2',ARRAY['SO3-1-u2-C4']::text[],'연표에는 나 한 사람의 일만 적을 수 있다고 여긴다','가족 · 학교 · 마을의 일도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X13','soc',3,'u2',ARRAY['SO3-1-u2-C5']::text[],'연표 만드는 차례를 바꾼다(꾸미기부터 하거나 모으기 없이 적기)','모으기 → 순서 → 적기 → 꾸미기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X14','soc',3,'u2',ARRAY['SO3-1-u2-C4','SO3-1-u2-C5']::text[],'연표 띠에서 나중 일을 왼쪽 맨 앞에 적거나 오른쪽을 먼저 일로 거꾸로 읽는다','왼쪽이 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X15','soc',3,'u2',ARRAY['SO3-1-u2-C6']::text[],'타임캡슐을 지난 때에 여는 것이나 과거로 보내는 것으로 여긴다','지금 담아 앞으로 열어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X16','soc',3,'u2',ARRAY['SO3-1-u2-C7','SO3-1-u2-C12']::text[],'옛날은 직접 갈 수 없으니 알 수 없다거나 모두 상상으로만 안다고 여긴다','남아 있는 것으로 알아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X17','soc',3,'u2',ARRAY['SO3-1-u2-C7','SO3-1-u2-C9','SO3-1-u2-C13','SO3-1-u2-C15']::text[],'한 가지 단서나 자료만 보아도 옛날을 모두 안다고 여긴다','여러 가지를 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X18','soc',3,'u2',ARRAY['SO3-1-u2-C7']::text[],'옛 사진이 미래나 상상 속 모습을 보여 준다고 여기거나 단서가 알려 주는 것을 엇갈려 안다','사진은 그때를 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X19','soc',3,'u2',ARRAY['SO3-1-u2-C8']::text[],'옛 물건과 그 쓰임을 엇갈려 짝짓는다(맷돌로 옷을 폈다)','무엇에 쓰였나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X20','soc',3,'u2',ARRAY['SO3-1-u2-C8']::text[],'옛 물건과 같은 일을 하는 오늘날 물건을 엇갈려 짝짓는다(맷돌 ↔ 전기다리미)','같은 일을 하는 오늘 물건') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X21','soc',3,'u2',ARRAY['SO3-1-u2-C8','SO3-1-u2-C12']::text[],'오래된 물건은 낡아서 아무것도 알려 주지 않거나 쓸모없다고 여긴다','물건은 그때 생활을 알려 줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X22','soc',3,'u2',ARRAY['SO3-1-u2-C9','SO3-1-u2-C13']::text[],'증언을 자료 읽기나 상상으로 여기거나, 그때를 겪지 않은 사람에게 들은 말을 증언으로 여긴다','그때를 겪은 분께 직접') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X23','soc',3,'u2',ARRAY['SO3-1-u2-C9','SO3-1-u2-C14']::text[],'옛 신문 · 포스터 · 옛이야기는 오래되었거나 지어낸 것이라 옛 생활을 아는 데 쓸모없다고 여긴다','그때를 전해 줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X24','soc',3,'u2',ARRAY['SO3-1-u2-C10']::text[],'자료를 대충 보거나 모으기만 하면 저절로 안다고 여긴다','천천히 자세히') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X25','soc',3,'u2',ARRAY['SO3-1-u2-C10','SO3-1-u2-C15']::text[],'보이는 것과 알게 된 것을 가르지 못하거나 자료에 없는 것을 지어낸다','보이는 것에서 알게 된 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X26','soc',3,'u2',ARRAY['SO3-1-u2-C10']::text[],'같은 자료면 누구나 같은 것만 찾으니 친구와 나눌 필요가 없다고 여긴다','친구는 다른 것을 찾아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X27','soc',3,'u2',ARRAY['SO3-1-u2-C11']::text[],'전시 주제 없이 아무거나 · 비싼 것 · 주제와 맞지 않는 것을 모은다','주제에 맞는 자료') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X28','soc',3,'u2',ARRAY['SO3-1-u2-C11']::text[],'설명 카드에 이름과 쓰임 대신 상관없는 것을 적거나 소개 없이 물건만 늘어놓는다','이름과 쓰임 · 무엇을 왜') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X29','soc',3,'u2',ARRAY['SO3-1-u2-C12']::text[],'옛 생활을 알아보는 까닭이나 박물관 · 축제가 옛것을 전하는 까닭을 모른다(옛것은 오늘과 상관없음)','과거를 알면 오늘이 보여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X30','soc',3,'u2',ARRAY['SO3-1-u2-C12']::text[],'오늘의 기록 · 사진 · 물건은 시간이 흘러도 과거를 알려 주는 자료가 될 수 없다고 여긴다','오늘도 언젠가 과거') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X31','soc',3,'u2',ARRAY['SO3-1-u2-C13','SO3-1-u2-C16']::text[],'우리 지역은 옛날부터 지금까지 모습이 그대로라고 여긴다','지역도 달라져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X32','soc',3,'u2',ARRAY['SO3-1-u2-C13','SO3-1-u2-C15']::text[],'자료와 그 자료가 알려 주는 것을 엇갈려 짝짓는다(영상 = 글로 쓴 소식)','사진 · 신문 · 영상') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X33','soc',3,'u2',ARRAY['SO3-1-u2-C14']::text[],'땅 이름은 아무 뜻 없이 붙었다고 여기거나 이름 속 단서를 엉뚱하게 읽는다','이름 속 옛 모습') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X34','soc',3,'u2',ARRAY['SO3-1-u2-C16']::text[],'계획 없이 조사하거나 조사 차례를 바꾼다','계획 → 자료 → 비교 → 보고서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X35','soc',3,'u2',ARRAY['SO3-1-u2-C16']::text[],'조사 보고서에서 알게 된 점을 빼거나 상관없는 것을 적는다','조사한 내용 · 알게 된 점') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X36','soc',3,'u2',ARRAY['SO3-1-u2-C16']::text[],'문화 해설사가 하는 일을 다른 직업과 바꾸어 안다','옛 모습을 알기 쉽게 설명') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X37','soc',3,'u2',ARRAY['SO3-1-u2-C17']::text[],'영상 만드는 차례를 바꾸거나 옛날 → 오늘 차례 없이 섞어 늘어놓는다','옛날 → 오늘') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-1-u2-X38','soc',3,'u2',ARRAY['SO3-1-u2-C17']::text[],'자막과 소개 없이 자료만 보여 주면 된다고 여긴다','설명을 붙여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
