INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L01_challenge#4','soc',3,1,'u2','L01','g3_1_soc_u2_L01_challenge','lesson_challenge','SO3-1-u2-C1',3,'mc','auto','「다음 달에 동생 생일잔치를 해요.」와 같은 때의 일은 무엇일까요?',ARRAY['SO3-1-u2-X01']::text[],false,'{"seq":4,"concept":"SO3-1-u2-C1","difficulty":3,"kind":"mc","stem":"「다음 달에 동생 생일잔치를 해요.」와 같은 때의 일은 무엇일까요?","options":[{"t":"「내년에 4학년이 돼요.」","correct":true},{"t":"「어제 줄넘기를 했어요.」","mis":"SO3-1-u2-X01"},{"t":"「작년에 이사를 왔어요.」","mis":"SO3-1-u2-X01"},{"t":"「지금 책을 읽고 있어요.」","mis":"SO3-1-u2-X01"}],"explanation":["다음 달은","앞으로 올 때","미래끼리"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L01_challenge#5','soc',3,1,'u2','L01','g3_1_soc_u2_L01_challenge','lesson_challenge','SO3-1-u2-C1',3,'error','auto','친구들이 시간을 나타내는 말을 이야기했어요. 잘못 말한 친구는 누구일까요?',ARRAY['SO3-1-u2-X01']::text[],false,'{"seq":5,"concept":"SO3-1-u2-C1","difficulty":3,"kind":"error","stem":"친구들이 시간을 나타내는 말을 이야기했어요. 잘못 말한 친구는 누구일까요?","options":[{"t":"민재 — 「옛날은 앞으로 올 때를 나타내.」","correct":true,"mis_target":"SO3-1-u2-X01"},{"t":"수아 — 「오늘은 지금 살아가는 때야.」","mis":"SO3-1-u2-X01"},{"t":"지호 — 「내일은 앞으로 올 때야.」","mis":"SO3-1-u2-X01"}],"explanation":["옛날은","지나간 때","민재가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L01_challenge#6','soc',3,1,'u2','L01','g3_1_soc_u2_L01_challenge','lesson_challenge','SO3-1-u2-C1',3,'mc','auto','「어제는 비가 왔지만 오늘은 맑다. 내일은 소풍을 간다.」에 나온 때를 차례대로 바르게 말한 것은 무엇일까요?',ARRAY['SO3-1-u2-X01','SO3-1-u2-X02']::text[],false,'{"seq":6,"concept":"SO3-1-u2-C1","difficulty":3,"kind":"mc","stem":"「어제는 비가 왔지만 오늘은 맑다. 내일은 소풍을 간다.」에 나온 때를 차례대로 바르게 말한 것은 무엇일까요?","options":[{"t":"과거 → 현재 → 미래","correct":true},{"t":"현재 → 과거 → 미래","mis":"SO3-1-u2-X01"},{"t":"미래 → 현재 → 과거","mis":"SO3-1-u2-X02"},{"t":"과거 → 미래 → 현재","mis":"SO3-1-u2-X01"}],"explanation":["어제","오늘","내일"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L01_challenge#7','soc',3,1,'u2','L01','g3_1_soc_u2_L01_challenge','lesson_challenge','SO3-1-u2-C1',3,'ox','auto','오늘은 내일이 되면 지나간 때가 돼요.',ARRAY['SO3-1-u2-X02']::text[],false,'{"seq":7,"concept":"SO3-1-u2-C1","difficulty":3,"kind":"ox","stem":"오늘은 내일이 되면 지나간 때가 돼요.","answer":"O","reason_options":[{"t":"시간이 흐르면 지금 이때도 지나간 때가 되기 때문에","correct":true},{"t":"오늘은 언제까지나 현재로 남기 때문에","mis":"SO3-1-u2-X02"}],"mis":"SO3-1-u2-X02","explanation":["내일이 되면","오늘은 어제","O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L01_challenge#8','soc',3,1,'u2','L01','g3_1_soc_u2_L01_challenge','lesson_challenge','SO3-1-u2-C1',4,'essay','teacher','과거 · 현재 · 미래를 나타내는 말을 하나씩 골라 그 말이 들어간 문장을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-1-u2-C1","difficulty":4,"kind":"essay","stem":"과거 · 현재 · 미래를 나타내는 말을 하나씩 골라 그 말이 들어간 문장을 쓰세요.","answer_guide":{"answer":"예: 과거 — 어제 동생과 공원에 갔다. / 현재 — 지금 사회 공부를 하고 있다. / 미래 — 내일 할머니 댁에 간다.","scoring_points":["세 때를 나타내는 말을 골랐는가","때에 맞는 문장을 썼는가","말과 문장의 때가 서로 맞는가"]},"explanation":["어제 · 오늘 · 내일","하나씩","문장으로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L01_challenge#9','soc',3,1,'u2','L01','g3_1_soc_u2_L01_challenge','lesson_challenge','SO3-1-u2-C1',4,'essay','teacher','시간이 흐르는 방향을 쓰고, 지나간 일을 다시 할 수 없는 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-1-u2-C1","difficulty":4,"kind":"essay","stem":"시간이 흐르는 방향을 쓰고, 지나간 일을 다시 할 수 없는 까닭을 쓰세요.","answer_guide":{"answer":"예: 시간은 과거에서 현재로, 다시 미래로 한 방향으로만 흐른다. 지나간 때는 되돌릴 수 없어서 어제 일을 똑같이 다시 할 수는 없다.","scoring_points":["흐르는 방향을 썼는가","되돌릴 수 없다는 것을 썼는가","까닭이 알맞은가"]},"explanation":["어느 쪽으로?","되돌릴 수 있나요?","한 방향"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L01_challenge#10','soc',3,1,'u2','L01','g3_1_soc_u2_L01_challenge','lesson_challenge','SO3-1-u2-C1',4,'essay','teacher','「하린이의 시간 낱말 카드」에 나온 때를 나타내는 말을 과거 · 현재 · 미래로 나누어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-1-u2-C1","difficulty":4,"kind":"essay","stem":"「하린이의 시간 낱말 카드」에 나온 때를 나타내는 말을 과거 · 현재 · 미래로 나누어 쓰세요.","answer_guide":{"answer":"예: 과거 — 어제, 작년 / 현재 — 오늘 / 미래 — 내일","scoring_points":["과거를 바르게 나누었는가","현재를 바르게 나누었는가","미래를 바르게 나누었는가"]},"explanation":["지났나요?","지금인가요?","앞으로인가요?"],"asset":{"type":"passage","lines":["어제 — 할머니 댁에 다녀왔다.","오늘 — 학교에서 공을 찼다.","내일 — 현장 체험학습을 간다.","작년 — 2학년이었다."],"title":"하린이의 시간 낱말 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L02_basic#1','soc',3,1,'u2','L02','g3_1_soc_u2_L02_basic','lesson_basic','SO3-1-u2-C2',1,'mc','auto','태어나서 지금까지 자라 온 과정을 무엇이라고 할까요?',ARRAY['SO3-1-u2-X06','SO3-1-u2-X05']::text[],false,'{"seq":1,"concept":"SO3-1-u2-C2","difficulty":1,"kind":"mc","stem":"태어나서 지금까지 자라 온 과정을 무엇이라고 할까요?","options":[{"t":"성장 과정","correct":true},{"t":"오늘의 날씨","mis":"SO3-1-u2-X06"},{"t":"내일의 계획","mis":"SO3-1-u2-X06"},{"t":"친구의 이름","mis":"SO3-1-u2-X05"}],"explanation":["자라 온","과정","성장 과정"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
