INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L02_basic#3','soc',3,1,'u2','L02','g3_1_soc_u2_L02_basic','lesson_basic','SO3-1-u2-C2',1,'mc','auto','나의 지난 중요한 일을 떠올리는 데 도움이 되는 것은 무엇일까요?',ARRAY['SO3-1-u2-X06']::text[],false,'{"seq":3,"concept":"SO3-1-u2-C2","difficulty":1,"kind":"mc","stem":"나의 지난 중요한 일을 떠올리는 데 도움이 되는 것은 무엇일까요?","options":[{"t":"어릴 적 사진과 앨범","correct":true},{"t":"내일의 일기 예보","mis":"SO3-1-u2-X06"},{"t":"다음 주 시간표","mis":"SO3-1-u2-X06"},{"t":"내년 달력","mis":"SO3-1-u2-X06"}],"explanation":["지난 일이 담긴 것","사진","앨범"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L02_basic#4','soc',3,1,'u2','L02','g3_1_soc_u2_L02_basic','lesson_basic','SO3-1-u2-C2',1,'ox','auto','중요한 일은 일어난 시간 순서대로 떠올리면 한눈에 잘 보여요.',ARRAY['SO3-1-u2-X03']::text[],false,'{"seq":4,"concept":"SO3-1-u2-C2","difficulty":1,"kind":"ox","stem":"중요한 일은 일어난 시간 순서대로 떠올리면 한눈에 잘 보여요.","answer":"O","reason_options":[{"t":"먼저 일어난 일부터 차례대로 놓으면 자라 온 흐름이 보이기 때문에","correct":true},{"t":"중요한 일은 순서와 상관없이 떠올려도 똑같이 보이기 때문에","mis":"SO3-1-u2-X03"}],"mis":"SO3-1-u2-X03","explanation":["먼저 일부터","차례대로","O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L02_basic#5','soc',3,1,'u2','L02','g3_1_soc_u2_L02_basic','lesson_basic','SO3-1-u2-C2',2,'mc','auto','다음 일들을 먼저 일어난 차례대로 바르게 늘어놓은 것은 무엇일까요?',ARRAY['SO3-1-u2-X03']::text[],false,'{"seq":5,"concept":"SO3-1-u2-C2","difficulty":2,"kind":"mc","stem":"다음 일들을 먼저 일어난 차례대로 바르게 늘어놓은 것은 무엇일까요?","options":[{"t":"태어남 → 유치원 → 초등학교 입학","correct":true},{"t":"초등학교 입학 → 유치원 → 태어남","mis":"SO3-1-u2-X03"},{"t":"유치원 → 태어남 → 초등학교 입학","mis":"SO3-1-u2-X03"},{"t":"초등학교 입학 → 태어남 → 유치원","mis":"SO3-1-u2-X03"}],"explanation":["가장 먼저는","태어남","그다음은?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L02_basic#6','soc',3,1,'u2','L02','g3_1_soc_u2_L02_basic','lesson_basic','SO3-1-u2-C2',2,'mc','auto','「나는 작년보다 키가 컸어.」라는 말로 알 수 있는 것은 무엇일까요?',ARRAY['SO3-1-u2-X04','SO3-1-u2-X02']::text[],false,'{"seq":6,"concept":"SO3-1-u2-C2","difficulty":2,"kind":"mc","stem":"「나는 작년보다 키가 컸어.」라는 말로 알 수 있는 것은 무엇일까요?","options":[{"t":"시간이 흐르며 내 모습이 달라졌다","correct":true},{"t":"시간이 흘러도 나는 그대로다","mis":"SO3-1-u2-X04"},{"t":"작년이 올해보다 나중이다","mis":"SO3-1-u2-X02"},{"t":"시간이 멈췄다","mis":"SO3-1-u2-X02"}],"explanation":["작년과 견주면","키가 컸어요.","달라졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L02_basic#7','soc',3,1,'u2','L02','g3_1_soc_u2_L02_basic','lesson_basic','SO3-1-u2-C2',2,'mc','auto','과거의 나와 지금의 나를 견주면 알 수 있는 것은 무엇일까요?',ARRAY['SO3-1-u2-X04','SO3-1-u2-X02']::text[],false,'{"seq":7,"concept":"SO3-1-u2-C2","difficulty":2,"kind":"mc","stem":"과거의 나와 지금의 나를 견주면 알 수 있는 것은 무엇일까요?","options":[{"t":"키와 할 수 있는 일이 달라졌다","correct":true},{"t":"아무것도 변하지 않았다","mis":"SO3-1-u2-X04"},{"t":"과거의 내가 더 크다","mis":"SO3-1-u2-X04"},{"t":"나이가 줄었다","mis":"SO3-1-u2-X02"}],"explanation":["아기 때와 지금","무엇이?","달라졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L02_basic#8','soc',3,1,'u2','L02','g3_1_soc_u2_L02_basic','lesson_basic','SO3-1-u2-C2',2,'mc','auto','「서준이의 자라 온 모습」에서 서준이가 가장 먼저 한 일은 무엇일까요?',ARRAY['SO3-1-u2-X03']::text[],false,'{"seq":8,"concept":"SO3-1-u2-C2","difficulty":2,"kind":"mc","stem":"「서준이의 자라 온 모습」에서 서준이가 가장 먼저 한 일은 무엇일까요?","options":[{"t":"처음으로 걸음마를 했어요","correct":true},{"t":"두발자전거를 타요","mis":"SO3-1-u2-X03"},{"t":"혼자 신발 끈을 묶었어요","mis":"SO3-1-u2-X03"},{"t":"자전거 보조 바퀴를 달고 탔어요","mis":"SO3-1-u2-X03"}],"explanation":["아기 때","가장 먼저","걸음마"],"asset":{"type":"passage","lines":["아기 — 처음으로 걸음마를 했어요.","유치원생 — 자전거 보조 바퀴를 달고 탔어요.","1학년 — 혼자 신발 끈을 묶었어요.","3학년 — 두발자전거를 타요."],"title":"서준이의 자라 온 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L02_basic#9','soc',3,1,'u2','L02','g3_1_soc_u2_L02_basic','lesson_basic','SO3-1-u2-C2',2,'ox','auto','친구와 나에게 있었던 중요한 일은 모두 똑같아야 해요.',ARRAY['SO3-1-u2-X05']::text[],false,'{"seq":9,"concept":"SO3-1-u2-C2","difficulty":2,"kind":"ox","stem":"친구와 나에게 있었던 중요한 일은 모두 똑같아야 해요.","answer":"X","reason_options":[{"t":"사람마다 겪은 일과 자라 온 과정이 서로 다르기 때문에","correct":true},{"t":"모든 사람은 똑같은 일을 똑같은 때에 겪기 때문에","mis":"SO3-1-u2-X05"}],"mis":"SO3-1-u2-X05","explanation":["나와 친구","같은 일?","달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L02_basic#10','soc',3,1,'u2','L02','g3_1_soc_u2_L02_basic','lesson_basic','SO3-1-u2-C2',3,'mc','auto','「서준이의 자라 온 모습」으로 알 수 있는 것은 무엇일까요?',ARRAY['SO3-1-u2-X04','SO3-1-u2-X03','SO3-1-u2-X05']::text[],false,'{"seq":10,"concept":"SO3-1-u2-C2","difficulty":3,"kind":"mc","stem":"「서준이의 자라 온 모습」으로 알 수 있는 것은 무엇일까요?","options":[{"t":"시간이 흐르면서 서준이가 할 수 있는 일이 늘어났어요.","correct":true},{"t":"서준이는 아기 때와 지금이 똑같아요.","mis":"SO3-1-u2-X04"},{"t":"서준이는 3학년 때 처음 걸었어요.","mis":"SO3-1-u2-X03"},{"t":"서준이의 일은 모든 친구에게 똑같이 있었어요.","mis":"SO3-1-u2-X05"}],"explanation":["걸음마에서","두발자전거까지","늘어났어요."],"asset":{"type":"passage","lines":["아기 — 처음으로 걸음마를 했어요.","유치원생 — 자전거 보조 바퀴를 달고 탔어요.","1학년 — 혼자 신발 끈을 묶었어요.","3학년 — 두발자전거를 타요."],"title":"서준이의 자라 온 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L02_challenge#1','soc',3,1,'u2','L02','g3_1_soc_u2_L02_challenge','lesson_challenge','SO3-1-u2-C2',2,'mc','auto','나에게 특별하거나 기억에 남는 일을 무엇이라고 할까요?',ARRAY['SO3-1-u2-X06']::text[],false,'{"seq":1,"concept":"SO3-1-u2-C2","difficulty":2,"kind":"mc","stem":"나에게 특별하거나 기억에 남는 일을 무엇이라고 할까요?","options":[{"t":"중요한 일","correct":true},{"t":"내일 할 일","mis":"SO3-1-u2-X06"},{"t":"날씨 소식","mis":"SO3-1-u2-X06"},{"t":"다른 사람의 계획","mis":"SO3-1-u2-X06"}],"explanation":["특별한","기억에 남는","중요한 일"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L02_challenge#2','soc',3,1,'u2','L02','g3_1_soc_u2_L02_challenge','lesson_challenge','SO3-1-u2-C2',2,'mc','auto','나의 지난 일을 떠올리는 데 도움이 되지 않는 것은 무엇일까요?',ARRAY['SO3-1-u2-X06']::text[],false,'{"seq":2,"concept":"SO3-1-u2-C2","difficulty":2,"kind":"mc","stem":"나의 지난 일을 떠올리는 데 도움이 되지 않는 것은 무엇일까요?","options":[{"t":"내일의 일기 예보","correct":true},{"t":"성장 앨범","mis":"SO3-1-u2-X06"},{"t":"가족이 들려주는 이야기","mis":"SO3-1-u2-X06"},{"t":"어릴 적 사진","mis":"SO3-1-u2-X06"}],"explanation":["지난 일인가요?","내일은","앞으로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L02_challenge#3','soc',3,1,'u2','L02','g3_1_soc_u2_L02_challenge','lesson_challenge','SO3-1-u2-C2',3,'mc','auto','하린이가 「동생이 태어난 일」을 중요한 일로 골랐어요. 이 일을 정리하는 방법으로 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u2-X03','SO3-1-u2-X06','SO3-1-u2-X05']::text[],false,'{"seq":3,"concept":"SO3-1-u2-C2","difficulty":3,"kind":"mc","stem":"하린이가 「동생이 태어난 일」을 중요한 일로 골랐어요. 이 일을 정리하는 방법으로 알맞은 것은 무엇일까요?","options":[{"t":"일어난 때를 떠올려 다른 중요한 일들과 시간 순서대로 놓는다","correct":true},{"t":"좋아하는 일이니 맨 앞에 놓는다","mis":"SO3-1-u2-X03"},{"t":"앞으로 할 일과 섞어 놓는다","mis":"SO3-1-u2-X06"},{"t":"친구의 중요한 일과 똑같이 맞춘다","mis":"SO3-1-u2-X05"}],"explanation":["언제였나요?","다른 일과","차례대로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L02_challenge#4','soc',3,1,'u2','L02','g3_1_soc_u2_L02_challenge','lesson_challenge','SO3-1-u2-C2',3,'mc','auto','「내 동생은 아직 입학을 안 했으니 중요한 일이 하나도 없어.」를 바르게 고친 말은 무엇일까요?',ARRAY['SO3-1-u2-X05','SO3-1-u2-X04']::text[],false,'{"seq":4,"concept":"SO3-1-u2-C2","difficulty":3,"kind":"mc","stem":"「내 동생은 아직 입학을 안 했으니 중요한 일이 하나도 없어.」를 바르게 고친 말은 무엇일까요?","options":[{"t":"「동생에게도 태어난 일처럼 동생만의 중요한 일이 있어.」","correct":true},{"t":"「맞아. 입학해야만 중요한 일이 생겨.」","mis":"SO3-1-u2-X05"},{"t":"「동생은 나와 똑같은 일을 겪을 거야.」","mis":"SO3-1-u2-X05"},{"t":"「동생은 시간이 흘러도 자라지 않아.」","mis":"SO3-1-u2-X04"}],"explanation":["동생도","태어났어요.","사람마다 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
