INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L02_challenge#6','soc',3,1,'u2','L02','g3_1_soc_u2_L02_challenge','lesson_challenge','SO3-1-u2-C2',3,'mc','auto','나의 중요한 일을 떠올리려고 가족에게 여쭤볼 말로 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u2-X06','SO3-1-u2-X05']::text[],false,'{"seq":6,"concept":"SO3-1-u2-C2","difficulty":3,"kind":"mc","stem":"나의 중요한 일을 떠올리려고 가족에게 여쭤볼 말로 알맞은 것은 무엇일까요?","options":[{"t":"「제가 처음 걸음마를 한 게 언제였어요?」","correct":true},{"t":"「내일 날씨는 어때요?」","mis":"SO3-1-u2-X06"},{"t":"「다음 주에 뭐 먹을까요?」","mis":"SO3-1-u2-X06"},{"t":"「제 친구는 몇 살이에요?」","mis":"SO3-1-u2-X05"}],"explanation":["나의","지난 일","언제였나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
