INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L02_challenge#8','soc',3,1,'u2','L02','g3_1_soc_u2_L02_challenge','lesson_challenge','SO3-1-u2-C2',4,'essay','teacher','나에게 있었던 중요한 일 세 가지를 일어난 차례대로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-1-u2-C2","difficulty":4,"kind":"essay","stem":"나에게 있었던 중요한 일 세 가지를 일어난 차례대로 쓰세요.","answer_guide":{"answer":"예: 태어났다. → 유치원에서 처음 발표를 했다. → 초등학교에 입학했다.","scoring_points":["중요한 일 세 가지를 썼는가","먼저 일어난 일부터 차례대로 썼는가","지난 일만 썼는가"]},"explanation":["무슨 일?","언제?","차례대로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L02_challenge#9','soc',3,1,'u2','L02','g3_1_soc_u2_L02_challenge','lesson_challenge','SO3-1-u2-C2',4,'essay','teacher','유치원 때의 나와 지금의 나를 견주어 달라진 점 두 가지를 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-1-u2-C2","difficulty":4,"kind":"essay","stem":"유치원 때의 나와 지금의 나를 견주어 달라진 점 두 가지를 쓰세요.","answer_guide":{"answer":"예: 유치원 때보다 키가 많이 컸다. 유치원 때는 글을 잘 못 읽었는데 지금은 책을 혼자 읽는다.","scoring_points":["두 때를 견주었는가","달라진 점 두 가지를 썼는가","시간이 흐르며 변했다는 것이 드러나는가"]},"explanation":["그때의 나","지금의 나","달라진 점"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L02_challenge#10','soc',3,1,'u2','L02','g3_1_soc_u2_L02_challenge','lesson_challenge','SO3-1-u2-C2',4,'essay','teacher','친구의 중요한 일이 나와 다를 때 어떻게 들으면 좋을지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-1-u2-C2","difficulty":4,"kind":"essay","stem":"친구의 중요한 일이 나와 다를 때 어떻게 들으면 좋을지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 사람마다 자라 온 과정이 다르기 때문에 친구의 이야기를 끝까지 듣고 궁금한 것을 물어본다.","scoring_points":["듣는 태도를 썼는가","사람마다 다르다는 까닭을 썼는가","존중하는 마음이 드러나는가"]},"explanation":["사람마다","다른 일","존중"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
