INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L03_basic#8','soc',3,1,'u2','L03','g3_1_soc_u2_L03_basic','lesson_basic','SO3-1-u2-C3',2,'mc','auto','우리 학교의 옛 사진과 지금 모습을 견주면 알 수 있는 것은 무엇일까요?',ARRAY['SO3-1-u2-X08','SO3-1-u2-X03']::text[],false,'{"seq":8,"concept":"SO3-1-u2-C3","difficulty":2,"kind":"mc","stem":"우리 학교의 옛 사진과 지금 모습을 견주면 알 수 있는 것은 무엇일까요?","options":[{"t":"시간이 흐르며 학교도 달라졌다","correct":true},{"t":"학교는 언제나 그대로다","mis":"SO3-1-u2-X08"},{"t":"옛날 학교가 더 나중에 생겼다","mis":"SO3-1-u2-X03"},{"t":"지금 학교가 더 오래되었다","mis":"SO3-1-u2-X03"}],"explanation":["옛 학교","지금 학교","달라졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L03_basic#9','soc',3,1,'u2','L03','g3_1_soc_u2_L03_basic','lesson_basic','SO3-1-u2-C3',2,'mc','auto','조사한 가족 · 학교의 일을 한눈에 보이게 정리하려면 어떻게 하면 좋을까요?',ARRAY['SO3-1-u2-X03','SO3-1-u2-X06']::text[],false,'{"seq":9,"concept":"SO3-1-u2-C3","difficulty":2,"kind":"mc","stem":"조사한 가족 · 학교의 일을 한눈에 보이게 정리하려면 어떻게 하면 좋을까요?","options":[{"t":"일어난 차례대로 연표로 정리한다","correct":true},{"t":"좋아하는 일만 적는다","mis":"SO3-1-u2-X03"},{"t":"순서를 섞어 적는다","mis":"SO3-1-u2-X03"},{"t":"앞으로 할 일만 적는다","mis":"SO3-1-u2-X06"}],"explanation":["한눈에","차례대로","연표"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L03_basic#10','soc',3,1,'u2','L03','g3_1_soc_u2_L03_basic','lesson_basic','SO3-1-u2-C3',3,'mc','auto','하린이가 할머니께 여쭤본 방법과 알게 된 것을 바르게 말한 것은 무엇일까요?',ARRAY['SO3-1-u2-X07','SO3-1-u2-X06','SO3-1-u2-X08']::text[],false,'{"seq":10,"concept":"SO3-1-u2-C3","difficulty":3,"kind":"mc","stem":"하린이가 할머니께 여쭤본 방법과 알게 된 것을 바르게 말한 것은 무엇일까요?","options":[{"t":"면담으로, 하린이가 태어난 해에 가족이 지금 집으로 이사 온 것을 알았다","correct":true},{"t":"사진 보기로, 가족이 내일 이사 간다는 것을 알았다","mis":"SO3-1-u2-X07"},{"t":"누리집으로, 아빠가 바닷가 마을에서 태어날 것을 알았다","mis":"SO3-1-u2-X06"},{"t":"면담으로, 우리 가족은 한 번도 이사하지 않았다는 것을 알았다","mis":"SO3-1-u2-X08"}],"explanation":["여쭤봤어요.","면담","이사 온 해"],"asset":{"type":"speech","turns":[{"who":"하린","text":"할머니, 우리 가족에게 있었던 중요한 일을 여쭤봐도 될까요?"},{"who":"할머니","text":"그럼. 네 아빠가 어릴 때 우리 가족은 바닷가 마을에 살았단다."},{"who":"할머니","text":"네가 태어난 해에 지금 사는 집으로 이사를 왔지."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L03_challenge#1','soc',3,1,'u2','L03','g3_1_soc_u2_L03_challenge','lesson_challenge','SO3-1-u2-C3',2,'mc','auto','학교 누리집 기록이나 옛 사진을 살펴보는 것은 무엇을 알기 위해서일까요?',ARRAY['SO3-1-u2-X06','SO3-1-u2-X08']::text[],false,'{"seq":1,"concept":"SO3-1-u2-C3","difficulty":2,"kind":"mc","stem":"학교 누리집 기록이나 옛 사진을 살펴보는 것은 무엇을 알기 위해서일까요?","options":[{"t":"학교가 어떻게 달라져 왔는지 알기 위해","correct":true},{"t":"내일 급식을 알기 위해","mis":"SO3-1-u2-X06"},{"t":"학교는 변하지 않는다는 것을 보이기 위해","mis":"SO3-1-u2-X08"},{"t":"친구의 키를 알기 위해","mis":"SO3-1-u2-X06"}],"explanation":["옛 모습","지금 모습","달라진 점"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L03_challenge#2','soc',3,1,'u2','L03','g3_1_soc_u2_L03_challenge','lesson_challenge','SO3-1-u2-C3',2,'mc','auto','면담에 대해 바르게 말한 것은 무엇일까요?',ARRAY['SO3-1-u2-X07','SO3-1-u2-X06']::text[],false,'{"seq":2,"concept":"SO3-1-u2-C3","difficulty":2,"kind":"mc","stem":"면담에 대해 바르게 말한 것은 무엇일까요?","options":[{"t":"그때를 아는 사람을 만나 직접 여쭤보는 거예요.","correct":true},{"t":"사진을 혼자 보며 상상하는 거예요.","mis":"SO3-1-u2-X07"},{"t":"내일 일을 미리 정하는 거예요.","mis":"SO3-1-u2-X06"},{"t":"책을 베껴 쓰는 거예요.","mis":"SO3-1-u2-X07"}],"explanation":["사람을 만나","직접","여쭤봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L03_challenge#3','soc',3,1,'u2','L03','g3_1_soc_u2_L03_challenge','lesson_challenge','SO3-1-u2-C3',3,'mc','auto','「학교가 걸어온 길」을 보고 바르게 말한 친구의 말은 무엇일까요?',ARRAY['SO3-1-u2-X08','SO3-1-u2-X03']::text[],false,'{"seq":3,"concept":"SO3-1-u2-C3","difficulty":3,"kind":"mc","stem":"「학교가 걸어온 길」을 보고 바르게 말한 친구의 말은 무엇일까요?","options":[{"t":"「처음에는 교실이 6칸이었는데 시간이 흐르며 건물과 운동장이 달라졌어.」","correct":true},{"t":"「학교는 처음부터 지금과 똑같았어.」","mis":"SO3-1-u2-X08"},{"t":"「도서관을 꾸민 일이 가장 먼저 있었어.」","mis":"SO3-1-u2-X03"},{"t":"「이 기록으로는 학교에 대해 아무것도 알 수 없어.」","mis":"SO3-1-u2-X08"}],"explanation":["①부터","④까지","달라졌어요."],"asset":{"type":"passage","lines":["① 처음 문을 열었을 때 — 교실 6칸, 흙 운동장","② 몇 해 뒤 — 2층 건물을 새로 지음","③ 그 뒤 — 흙 운동장을 새로 고침","④ 올해 — 도서관을 새로 꾸밈"],"title":"우리 학교 누리집 「학교가 걸어온 길」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L03_challenge#4','soc',3,1,'u2','L03','g3_1_soc_u2_L03_challenge','lesson_challenge','SO3-1-u2-C3',3,'mc','auto','할아버지와 면담할 때 여쭤볼 말로 가장 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u2-X06','SO3-1-u2-X07']::text[],false,'{"seq":4,"concept":"SO3-1-u2-C3","difficulty":3,"kind":"mc","stem":"할아버지와 면담할 때 여쭤볼 말로 가장 알맞은 것은 무엇일까요?","options":[{"t":"「아빠가 어렸을 때 우리 가족에게 어떤 중요한 일이 있었어요?」","correct":true},{"t":"「내일 비가 올까요?」","mis":"SO3-1-u2-X06"},{"t":"「제 짝꿍 이름이 뭐예요?」","mis":"SO3-1-u2-X07"},{"t":"「다음 주 급식은 뭐예요?」","mis":"SO3-1-u2-X06"}],"explanation":["가족의","지난 일","여쭤봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L03_challenge#5','soc',3,1,'u2','L03','g3_1_soc_u2_L03_challenge','lesson_challenge','SO3-1-u2-C3',3,'mc','auto','가족의 중요한 일을 조사하려는 지호에게 알맞은 차례는 무엇일까요?',ARRAY['SO3-1-u2-X03','SO3-1-u2-X07','SO3-1-u2-X06']::text[],false,'{"seq":5,"concept":"SO3-1-u2-C3","difficulty":3,"kind":"mc","stem":"가족의 중요한 일을 조사하려는 지호에게 알맞은 차례는 무엇일까요?","options":[{"t":"사진을 보고 어른께 여쭤본다 → 알게 된 일을 시간 순서대로 연표에 정리한다","correct":true},{"t":"연표를 먼저 꾸민다 → 아무 일이나 적는다","mis":"SO3-1-u2-X03"},{"t":"조사하지 않고 상상해 적는다 → 순서를 섞는다","mis":"SO3-1-u2-X07"},{"t":"앞으로 할 일을 정한다 → 계획표에 적는다","mis":"SO3-1-u2-X06"}],"explanation":["먼저 조사","그다음 정리","연표"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L03_challenge#6','soc',3,1,'u2','L03','g3_1_soc_u2_L03_challenge','lesson_challenge','SO3-1-u2-C3',3,'ox','auto','같은 학교라도 옛 사진과 지금 모습을 견주면 달라진 점을 찾을 수 있어요.',ARRAY['SO3-1-u2-X08']::text[],false,'{"seq":6,"concept":"SO3-1-u2-C3","difficulty":3,"kind":"ox","stem":"같은 학교라도 옛 사진과 지금 모습을 견주면 달라진 점을 찾을 수 있어요.","answer":"O","reason_options":[{"t":"시간이 흐르면서 건물과 운동장 같은 학교 모습도 바뀌기 때문에","correct":true},{"t":"학교는 한 번 지으면 언제까지나 그대로이기 때문에","mis":"SO3-1-u2-X08"}],"mis":"SO3-1-u2-X08","explanation":["옛 사진","지금","견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L03_challenge#7','soc',3,1,'u2','L03','g3_1_soc_u2_L03_challenge','lesson_challenge','SO3-1-u2-C3',3,'error','auto','가족의 중요한 일을 조사한 친구들의 말이에요. 잘못 말한 친구는 누구일까요?',ARRAY['SO3-1-u2-X06','SO3-1-u2-X07']::text[],false,'{"seq":7,"concept":"SO3-1-u2-C3","difficulty":3,"kind":"error","stem":"가족의 중요한 일을 조사한 친구들의 말이에요. 잘못 말한 친구는 누구일까요?","options":[{"t":"도윤 — 「누리집에서 내일 날씨를 찾아 가족의 옛일을 알았어.」","correct":true,"mis_target":"SO3-1-u2-X06"},{"t":"예린 — 「할머니와 면담해 이사 온 해를 알았어.」","mis":"SO3-1-u2-X07"},{"t":"수아 — 「가족 앨범으로 부모님이 처음 만난 때를 찾았어.」","mis":"SO3-1-u2-X06"}],"explanation":["내일 날씨는","옛일이 아니에요.","도윤이가 잘못"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L03_challenge#8','soc',3,1,'u2','L03','g3_1_soc_u2_L03_challenge','lesson_challenge','SO3-1-u2-C3',4,'essay','teacher','우리 가족이나 학교의 중요한 일을 알아보는 방법 두 가지를 쓰고, 각 방법으로 무엇을 알 수 있는지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-1-u2-C3","difficulty":4,"kind":"essay","stem":"우리 가족이나 학교의 중요한 일을 알아보는 방법 두 가지를 쓰고, 각 방법으로 무엇을 알 수 있는지 쓰세요.","answer_guide":{"answer":"예: 면담 — 할머니께 여쭤보아 우리 가족이 이사 온 때를 알 수 있다. / 누리집 살펴보기 — 학교가 처음 문을 연 때와 새 건물을 지은 일을 알 수 있다.","scoring_points":["방법 두 가지를 썼는가","방법마다 알 수 있는 것을 썼는가","방법과 알 수 있는 것이 어울리는가"]},"explanation":["면담","사진 · 누리집","알 수 있는 것"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L03_challenge#9','soc',3,1,'u2','L03','g3_1_soc_u2_L03_challenge','lesson_challenge','SO3-1-u2-C3',4,'essay','teacher','할머니와 면담할 때 여쭤볼 질문 두 가지를 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-1-u2-C3","difficulty":4,"kind":"essay","stem":"할머니와 면담할 때 여쭤볼 질문 두 가지를 쓰세요.","answer_guide":{"answer":"예: 엄마가 어렸을 때 우리 가족은 어디에 살았어요? / 할머니가 기억하시는 우리 가족의 가장 기쁜 일은 무엇이에요?","scoring_points":["질문 두 가지를 썼는가","가족의 지난 일을 묻는가","공손한 말로 썼는가"]},"explanation":["가족의","지난 일","공손하게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L03_challenge#10','soc',3,1,'u2','L03','g3_1_soc_u2_L03_challenge','lesson_challenge','SO3-1-u2-C3',4,'essay','teacher','「학교가 걸어온 길」로 알 수 있는 학교의 달라진 모습을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-1-u2-C3","difficulty":4,"kind":"essay","stem":"「학교가 걸어온 길」로 알 수 있는 학교의 달라진 모습을 두 가지 쓰세요.","answer_guide":{"answer":"예: 처음에는 교실이 6칸뿐이었는데 2층 건물을 새로 지었다. 흙 운동장이었는데 새로 고쳤다.","scoring_points":["달라진 점 두 가지를 썼는가","처음과 나중을 견주었는가","기록에 있는 내용인가"]},"explanation":["처음","그 뒤","달라진 점"],"asset":{"type":"passage","lines":["① 처음 문을 열었을 때 — 교실 6칸, 흙 운동장","② 몇 해 뒤 — 2층 건물을 새로 지음","③ 그 뒤 — 흙 운동장을 새로 고침","④ 올해 — 도서관을 새로 꾸밈"],"title":"우리 학교 누리집 「학교가 걸어온 길」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
