INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L04_basic#10','soc',3,1,'u2','L04','g3_1_soc_u2_L04_basic','lesson_basic','SO3-1-u2-C4',3,'mc','auto','「민재가 만든 연표」의 잘못을 바르게 말한 것은 무엇일까요?',ARRAY['SO3-1-u2-X11','SO3-1-u2-X10','SO3-1-u2-X12']::text[],false,'{"seq":10,"concept":"SO3-1-u2-C4","difficulty":3,"kind":"mc","stem":"「민재가 만든 연표」의 잘못을 바르게 말한 것은 무엇일까요?","options":[{"t":"일이 일어난 시간 순서대로 놓이지 않았어요.","correct":true},{"t":"색깔을 칠하지 않았어요.","mis":"SO3-1-u2-X11"},{"t":"때를 적지 않았어요.","mis":"SO3-1-u2-X10"},{"t":"나의 일만 적어서 잘못이에요.","mis":"SO3-1-u2-X12"}],"explanation":["8살이 맨 앞","0살이 둘째","순서가 섞였어요."],"asset":{"type":"passage","lines":["8살 — 초등학교에 입학했어요","0살 — 태어났어요","10살 — 3학년이 되었어요","5살 — 유치원에 다녔어요"],"title":"민재가 만든 연표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L04_challenge#1','soc',3,1,'u2','L04','g3_1_soc_u2_L04_challenge','lesson_challenge','SO3-1-u2-C4',2,'mc','auto','연표를 바르게 만든 친구의 말은 무엇일까요?',ARRAY['SO3-1-u2-X11','SO3-1-u2-X14','SO3-1-u2-X10']::text[],false,'{"seq":1,"concept":"SO3-1-u2-C4","difficulty":2,"kind":"mc","stem":"연표를 바르게 만든 친구의 말은 무엇일까요?","options":[{"t":"「먼저 일어난 일을 앞에 적었어.」","correct":true},{"t":"「마음에 드는 일을 맨 앞에 적었어.」","mis":"SO3-1-u2-X11"},{"t":"「나중 일을 맨 앞에 적었어.」","mis":"SO3-1-u2-X14"},{"t":"「때는 빼고 일만 적었어.」","mis":"SO3-1-u2-X10"}],"explanation":["먼저 일이","앞","시간 순서"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
