INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L04_challenge#6','soc',3,1,'u2','L04','g3_1_soc_u2_L04_challenge','lesson_challenge','SO3-1-u2-C4',3,'ox','auto','연표에서 가장 중요한 것은 예쁜 색깔이에요.',ARRAY['SO3-1-u2-X11']::text[],false,'{"seq":6,"concept":"SO3-1-u2-C4","difficulty":3,"kind":"ox","stem":"연표에서 가장 중요한 것은 예쁜 색깔이에요.","answer":"X","reason_options":[{"t":"연표는 일이 일어난 시간 순서와 변화를 보여 주는 표이기 때문에","correct":true},{"t":"색이 예뻐야 순서가 저절로 맞기 때문에","mis":"SO3-1-u2-X11"}],"mis":"SO3-1-u2-X11","explanation":["연표는","순서","X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L04_challenge#7','soc',3,1,'u2','L04','g3_1_soc_u2_L04_challenge','lesson_challenge','SO3-1-u2-C4',3,'error','auto','연표에 대해 친구들이 말했어요. 잘못 말한 친구는 누구일까요?',ARRAY['SO3-1-u2-X12','SO3-1-u2-X10','SO3-1-u2-X09']::text[],false,'{"seq":7,"concept":"SO3-1-u2-C4","difficulty":3,"kind":"error","stem":"연표에 대해 친구들이 말했어요. 잘못 말한 친구는 누구일까요?","options":[{"t":"은솔 — 「연표는 나의 일만 적을 수 있어.」","correct":true,"mis_target":"SO3-1-u2-X12"},{"t":"지호 — 「연표에는 때와 있었던 일을 함께 적어.」","mis":"SO3-1-u2-X10"},{"t":"예린 — 「연표를 보면 순서와 변화가 보여.」","mis":"SO3-1-u2-X09"}],"explanation":["가족 · 학교의 일도","연표로","은솔이가 잘못"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L04_challenge#8','soc',3,1,'u2','L04','g3_1_soc_u2_L04_challenge','lesson_challenge','SO3-1-u2-C4',4,'essay','teacher','나에게 있었던 일 네 가지를 골라 때와 함께 연표로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-1-u2-C4","difficulty":4,"kind":"essay","stem":"나에게 있었던 일 네 가지를 골라 때와 함께 연표로 쓰세요.","answer_guide":{"answer":"예: 0살 — 태어났다 / 3살 — 동생이 생겼다 / 8살 — 초등학교에 입학했다 / 10살 — 3학년이 되었다","scoring_points":["때와 일을 함께 썼는가","시간 순서대로 썼는가","네 가지를 썼는가"]},"explanation":["언제","무슨 일","차례대로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
