INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L05_challenge#4','soc',3,1,'u2','L05','g3_1_soc_u2_L05_challenge','lesson_challenge','SO3-1-u2-C5',3,'mc','auto','친구의 연표에서 잘한 점을 바르게 말한 것은 무엇일까요?',ARRAY['SO3-1-u2-X11','SO3-1-u2-X13','SO3-1-u2-X14']::text[],false,'{"seq":4,"concept":"SO3-1-u2-C5","difficulty":3,"kind":"mc","stem":"친구의 연표에서 잘한 점을 바르게 말한 것은 무엇일까요?","options":[{"t":"「때와 일을 함께 적고 그림을 더해 한눈에 잘 보여.」","correct":true},{"t":"「순서는 뒤죽박죽이지만 색이 예뻐서 잘 만들었어.」","mis":"SO3-1-u2-X11"},{"t":"「꾸미기를 먼저 해서 일을 적을 자리가 없어.」","mis":"SO3-1-u2-X13"},{"t":"「나중 일을 맨 앞에 놓아서 잘했어.」","mis":"SO3-1-u2-X14"}],"explanation":["때와 일","순서","그림"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L05_challenge#5','soc',3,1,'u2','L05','g3_1_soc_u2_L05_challenge','lesson_challenge','SO3-1-u2-C5',3,'error','auto','연표를 만든 친구들의 말이에요. 잘못 만든 친구는 누구일까요?',ARRAY['SO3-1-u2-X14','SO3-1-u2-X03','SO3-1-u2-X13']::text[],false,'{"seq":5,"concept":"SO3-1-u2-C5","difficulty":3,"kind":"error","stem":"연표를 만든 친구들의 말이에요. 잘못 만든 친구는 누구일까요?","options":[{"t":"도윤 — 「나중 일을 맨 앞에, 먼저 일을 맨 뒤에 적었어.」","correct":true,"mis_target":"SO3-1-u2-X14"},{"t":"하린 — 「시간 순서대로 적었어.」","mis":"SO3-1-u2-X03"},{"t":"수아 — 「그림을 더해 보기 좋게 꾸몄어.」","mis":"SO3-1-u2-X13"}],"explanation":["먼저 일이","앞","도윤이가 거꾸로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L05_challenge#6','soc',3,1,'u2','L05','g3_1_soc_u2_L05_challenge','lesson_challenge','SO3-1-u2-C5',3,'mc','auto','하린이는 일을 모은 뒤 바로 꾸미기를 시작했어요. 하린이에게 해 줄 말로 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u2-X13','SO3-1-u2-X11']::text[],false,'{"seq":6,"concept":"SO3-1-u2-C5","difficulty":3,"kind":"mc","stem":"하린이는 일을 모은 뒤 바로 꾸미기를 시작했어요. 하린이에게 해 줄 말로 알맞은 것은 무엇일까요?","options":[{"t":"「먼저 일의 시간 순서를 정하고 띠에 적은 다음 꾸며 봐.」","correct":true},{"t":"「꾸미기를 먼저 하는 게 맞아.」","mis":"SO3-1-u2-X13"},{"t":"「순서는 정하지 않아도 돼.」","mis":"SO3-1-u2-X11"},{"t":"「일은 모으지 않아도 돼.」","mis":"SO3-1-u2-X13"}],"explanation":["모으기 다음","순서 · 적기","꾸미기는 끝"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L05_challenge#7','soc',3,1,'u2','L05','g3_1_soc_u2_L05_challenge','lesson_challenge','SO3-1-u2-C5',3,'ox','auto','연표를 소개할 때 「언제, 무슨 일이 있었는지」를 함께 말하면 친구가 잘 알아들어요.',ARRAY['SO3-1-u2-X11']::text[],false,'{"seq":7,"concept":"SO3-1-u2-C5","difficulty":3,"kind":"ox","stem":"연표를 소개할 때 「언제, 무슨 일이 있었는지」를 함께 말하면 친구가 잘 알아들어요.","answer":"O","reason_options":[{"t":"연표에 담긴 때와 일을 함께 알려 주기 때문에","correct":true},{"t":"연표 소개에는 꾸민 색깔만 말하면 되기 때문에","mis":"SO3-1-u2-X11"}],"mis":"SO3-1-u2-X11","explanation":["때와 일","함께","O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L05_challenge#8','soc',3,1,'u2','L05','g3_1_soc_u2_L05_challenge','lesson_challenge','SO3-1-u2-C5',4,'essay','teacher','연표를 만드는 네 단계를 차례대로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-1-u2-C5","difficulty":4,"kind":"essay","stem":"연표를 만드는 네 단계를 차례대로 쓰세요.","answer_guide":{"answer":"예: ① 있었던 일과 자료를 모은다. ② 시간 순서를 정한다. ③ 시간 띠 위에 때와 일을 차례로 적는다. ④ 그림 · 사진 · 설명을 더해 꾸민다.","scoring_points":["네 단계를 썼는가","차례가 바른가","단계마다 하는 일이 알맞은가"]},"explanation":["모으기","순서 · 적기","꾸미기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L05_challenge#9','soc',3,1,'u2','L05','g3_1_soc_u2_L05_challenge','lesson_challenge','SO3-1-u2-C5',4,'essay','teacher','내 연표를 친구에게 소개하는 말을 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-1-u2-C5","difficulty":4,"kind":"essay","stem":"내 연표를 친구에게 소개하는 말을 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 저는 0살에 태어나서 8살에 초등학교에 입학했어요. 10살인 지금은 3학년이 되어 친구들과 즐겁게 지내요.","scoring_points":["두 문장으로 썼는가","때와 일을 함께 말했는가","시간 순서대로 말했는가"]},"explanation":["언제","무슨 일","차례대로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L05_challenge#10','soc',3,1,'u2','L05','g3_1_soc_u2_L05_challenge','lesson_challenge','SO3-1-u2-C5',4,'essay','teacher','연표를 꾸밀 때 그림이나 사진을 더하면 좋은 까닭을 쓰고, 꾸미기보다 먼저 지켜야 할 것을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-1-u2-C5","difficulty":4,"kind":"essay","stem":"연표를 꾸밀 때 그림이나 사진을 더하면 좋은 까닭을 쓰고, 꾸미기보다 먼저 지켜야 할 것을 쓰세요.","answer_guide":{"answer":"예: 그림이나 사진이 있으면 어떤 일이었는지 한눈에 잘 보인다. 하지만 꾸미기 전에 일을 시간 순서대로 바르게 적는 것이 먼저다.","scoring_points":["꾸미면 좋은 까닭을 썼는가","순서가 먼저라는 것을 썼는가","내용이 알맞은가"]},"explanation":["그림 · 사진","한눈에","순서가 먼저"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
