INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L06_basic#8','soc',3,1,'u2','L06','g3_1_soc_u2_L06_basic','lesson_basic','SO3-1-u2-C6',2,'ox','auto','타임캡슐에 넣은 오늘의 사진도 먼 훗날에는 지난 때를 알려 주는 것이 돼요.',ARRAY['SO3-1-u2-X02']::text[],false,'{"seq":8,"concept":"SO3-1-u2-C6","difficulty":2,"kind":"ox","stem":"타임캡슐에 넣은 오늘의 사진도 먼 훗날에는 지난 때를 알려 주는 것이 돼요.","answer":"O","reason_options":[{"t":"시간이 흐르면 오늘도 과거가 되기 때문에","correct":true},{"t":"오늘은 아무리 시간이 흘러도 언제나 현재이기 때문에","mis":"SO3-1-u2-X02"}],"mis":"SO3-1-u2-X02","explanation":["시간이 흐르면","오늘은","과거"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
