INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L06_challenge#5','soc',3,1,'u2','L06','g3_1_soc_u2_L06_challenge','lesson_challenge','SO3-1-u2-C6',3,'error','auto','소단원에서 배운 것을 친구들이 말했어요. 잘못 말한 친구는 누구일까요?',ARRAY['SO3-1-u2-X02','SO3-1-u2-X07','SO3-1-u2-X09']::text[],false,'{"seq":5,"concept":"SO3-1-u2-C6","difficulty":3,"kind":"error","stem":"소단원에서 배운 것을 친구들이 말했어요. 잘못 말한 친구는 누구일까요?","options":[{"t":"민재 — 「시간은 미래에서 과거로 흘러.」","correct":true,"mis_target":"SO3-1-u2-X02"},{"t":"은솔 — 「가족의 옛일은 면담으로 알 수 있어.」","mis":"SO3-1-u2-X07"},{"t":"지호 — 「연표는 순서와 변화를 보여 줘.」","mis":"SO3-1-u2-X09"}],"explanation":["시간은","과거에서 미래로","민재가 잘못"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L06_challenge#6','soc',3,1,'u2','L06','g3_1_soc_u2_L06_challenge','lesson_challenge','SO3-1-u2-C5',3,'mc','auto','하린이는 가족 연표를 만들려고 해요. 가장 알맞은 계획은 무엇일까요?',ARRAY['SO3-1-u2-X13','SO3-1-u2-X11','SO3-1-u2-X06']::text[],false,'{"seq":6,"concept":"SO3-1-u2-C5","difficulty":3,"kind":"mc","stem":"하린이는 가족 연표를 만들려고 해요. 가장 알맞은 계획은 무엇일까요?","options":[{"t":"가족 사진을 모으고 할머니께 여쭤본 뒤 일어난 차례대로 띠에 적고 꾸민다","correct":true},{"t":"사진 없이 상상으로 적고 바로 꾸민다","mis":"SO3-1-u2-X13"},{"t":"좋아하는 일만 골라 마음대로 늘어놓는다","mis":"SO3-1-u2-X11"},{"t":"앞으로 가족이 할 일만 적는다","mis":"SO3-1-u2-X06"}],"explanation":["모으고","차례대로 적고","꾸며요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L06_challenge#7','soc',3,1,'u2','L06','g3_1_soc_u2_L06_challenge','lesson_challenge','SO3-1-u2-C6',3,'ox','auto','타임캡슐을 열어 보는 때에는 오늘이 과거가 되어 있어요.',ARRAY['SO3-1-u2-X15']::text[],false,'{"seq":7,"concept":"SO3-1-u2-C6","difficulty":3,"kind":"ox","stem":"타임캡슐을 열어 보는 때에는 오늘이 과거가 되어 있어요.","answer":"O","reason_options":[{"t":"타임캡슐은 먼 미래에 열어 보는데 그때에는 오늘이 이미 지나간 때이기 때문에","correct":true},{"t":"타임캡슐을 열면 오늘로 다시 돌아오기 때문에","mis":"SO3-1-u2-X15"}],"mis":"SO3-1-u2-X15","explanation":["먼 미래에 열면","오늘은","지나간 때"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L06_challenge#8','soc',3,1,'u2','L06','g3_1_soc_u2_L06_challenge','lesson_challenge','SO3-1-u2-C6',4,'essay','teacher','우리 반 타임캡슐에 넣고 싶은 물건 두 가지와 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-1-u2-C6","difficulty":4,"kind":"essay","stem":"우리 반 타임캡슐에 넣고 싶은 물건 두 가지와 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 반 친구들과 찍은 사진 — 먼 훗날 지금 우리 모습을 떠올릴 수 있다. / 나에게 쓰는 편지 — 지금의 꿈과 생각을 미래의 나에게 전할 수 있다.","scoring_points":["물건 두 가지를 썼는가","지금의 것을 골랐는가","까닭을 썼는가"]},"explanation":["지금의 것","미래에","전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L06_challenge#9','soc',3,1,'u2','L06','g3_1_soc_u2_L06_challenge','lesson_challenge','SO3-1-u2-C4',4,'essay','teacher','「시간의 흐름」에서 배운 연표를 쓰면 좋은 때를 한 가지 들고, 연표에 담을 것을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-1-u2-C4","difficulty":4,"kind":"essay","stem":"「시간의 흐름」에서 배운 연표를 쓰면 좋은 때를 한 가지 들고, 연표에 담을 것을 쓰세요.","answer_guide":{"answer":"예: 우리 학교가 걸어온 길을 알아볼 때 연표를 쓰면 좋다. 학교가 처음 문을 연 때, 새 건물을 지은 때처럼 때와 있었던 일을 시간 순서대로 담는다.","scoring_points":["연표를 쓸 때를 들었는가","때와 일을 담는다고 썼는가","시간 순서를 지켰는가"]},"explanation":["언제 쓰나요?","무엇을 담나요?","때와 일"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L06_challenge#10','soc',3,1,'u2','L06','g3_1_soc_u2_L06_challenge','lesson_challenge','SO3-1-u2-C1',4,'essay','teacher','과거 · 현재 · 미래의 나를 한 문장씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-1-u2-C1","difficulty":4,"kind":"essay","stem":"과거 · 현재 · 미래의 나를 한 문장씩 쓰세요.","answer_guide":{"answer":"예: 과거의 나는 유치원에서 처음 줄넘기를 배웠다. / 현재의 나는 3학년으로 친구들과 사회 공부를 한다. / 미래의 나는 4학년이 되어 더 긴 책을 읽을 것이다.","scoring_points":["세 때의 나를 썼는가","때에 맞는 말을 썼는가","문장이 자연스러운가"]},"explanation":["지난 나","지금 나","앞으로의 나"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L07_basic#1','soc',3,1,'u2','L07','g3_1_soc_u2_L07_basic','lesson_basic','SO3-1-u2-C7',1,'mc','auto','옛날 사람들의 생활 모습을 알려 주는 것이 아닌 것은 무엇일까요?',ARRAY['SO3-1-u2-X18','SO3-1-u2-X21','SO3-1-u2-X16']::text[],false,'{"seq":1,"concept":"SO3-1-u2-C7","difficulty":1,"kind":"mc","stem":"옛날 사람들의 생활 모습을 알려 주는 것이 아닌 것은 무엇일까요?","options":[{"t":"내일의 날씨","correct":true},{"t":"옛날 사진","mis":"SO3-1-u2-X18"},{"t":"오래된 물건","mis":"SO3-1-u2-X21"},{"t":"옛 건축물","mis":"SO3-1-u2-X16"}],"explanation":["옛날을","알려 주나요?","내일은 앞으로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L07_basic#2','soc',3,1,'u2','L07','g3_1_soc_u2_L07_basic','lesson_basic','SO3-1-u2-C7',1,'mc','auto','옛날의 모습을 사진기로 찍어 그대로 남긴 것을 무엇이라고 할까요?',ARRAY['SO3-1-u2-X06']::text[],false,'{"seq":2,"concept":"SO3-1-u2-C7","difficulty":1,"kind":"mc","stem":"옛날의 모습을 사진기로 찍어 그대로 남긴 것을 무엇이라고 할까요?","options":[{"t":"옛 사진","correct":true},{"t":"오늘 일기","mis":"SO3-1-u2-X06"},{"t":"계산표","mis":"SO3-1-u2-X06"},{"t":"지도책","mis":"SO3-1-u2-X06"}],"explanation":["사진기로","그대로","옛 사진"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L07_basic#3','soc',3,1,'u2','L07','g3_1_soc_u2_L07_basic','lesson_basic','SO3-1-u2-C7',1,'mc','auto','한옥처럼 옛날에 지은 집을 살펴보면 무엇을 알 수 있을까요?',ARRAY['SO3-1-u2-X06']::text[],false,'{"seq":3,"concept":"SO3-1-u2-C7","difficulty":1,"kind":"mc","stem":"한옥처럼 옛날에 지은 집을 살펴보면 무엇을 알 수 있을까요?","options":[{"t":"옛날 사람들이 살던 모습","correct":true},{"t":"내일 할 일","mis":"SO3-1-u2-X06"},{"t":"오늘의 날씨","mis":"SO3-1-u2-X06"},{"t":"우주의 크기","mis":"SO3-1-u2-X06"}],"explanation":["옛날 집","사는 모습","알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L07_basic#4','soc',3,1,'u2','L07','g3_1_soc_u2_L07_basic','lesson_basic','SO3-1-u2-C7',1,'ox','auto','옛날은 이미 지나가서 우리가 직접 가 볼 수 없어요.',ARRAY['SO3-1-u2-X16']::text[],false,'{"seq":4,"concept":"SO3-1-u2-C7","difficulty":1,"kind":"ox","stem":"옛날은 이미 지나가서 우리가 직접 가 볼 수 없어요.","answer":"O","reason_options":[{"t":"시간은 한 방향으로만 흘러 지나간 때로 되돌아갈 수 없기 때문에","correct":true},{"t":"마음만 먹으면 옛날로 직접 갈 수 있기 때문에","mis":"SO3-1-u2-X16"}],"mis":"SO3-1-u2-X16","explanation":["지나간 때","되돌아갈 수 없어요.","O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L07_basic#5','soc',3,1,'u2','L07','g3_1_soc_u2_L07_basic','lesson_basic','SO3-1-u2-C7',2,'mc','auto','우리가 직접 보지 못한 옛날을 알 수 있는 까닭은 무엇일까요?',ARRAY['SO3-1-u2-X16']::text[],false,'{"seq":5,"concept":"SO3-1-u2-C7","difficulty":2,"kind":"mc","stem":"우리가 직접 보지 못한 옛날을 알 수 있는 까닭은 무엇일까요?","options":[{"t":"옛날의 것들이 오늘날까지 남아 있기 때문에","correct":true},{"t":"모두 상상으로 지어내기 때문에","mis":"SO3-1-u2-X16"},{"t":"옛날로 직접 갈 수 있기 때문에","mis":"SO3-1-u2-X16"},{"t":"옛날은 알 수 없기 때문에","mis":"SO3-1-u2-X16"}],"explanation":["사진 · 물건 · 집","지금까지","남아 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L07_basic#6','soc',3,1,'u2','L07','g3_1_soc_u2_L07_basic','lesson_basic','SO3-1-u2-C7',2,'mc','auto','할머니 댁에서 빛바랜 흑백 사진을 찾았어요. 이 사진이 보여 주는 것은 무엇일까요?',ARRAY['SO3-1-u2-X18']::text[],false,'{"seq":6,"concept":"SO3-1-u2-C7","difficulty":2,"kind":"mc","stem":"할머니 댁에서 빛바랜 흑백 사진을 찾았어요. 이 사진이 보여 주는 것은 무엇일까요?","options":[{"t":"사진을 찍던 그때의 모습","correct":true},{"t":"미래의 모습","mis":"SO3-1-u2-X18"},{"t":"상상 속 모습","mis":"SO3-1-u2-X18"},{"t":"오늘 아침 모습","mis":"SO3-1-u2-X18"}],"explanation":["사진은","찍은 때를","그대로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L07_basic#7','soc',3,1,'u2','L07','g3_1_soc_u2_L07_basic','lesson_basic','SO3-1-u2-C7',2,'mc','auto','박물관에서 오래된 그릇을 보았어요. 이 그릇으로 알 수 있는 것은 무엇일까요?',ARRAY['SO3-1-u2-X06']::text[],false,'{"seq":7,"concept":"SO3-1-u2-C7","difficulty":2,"kind":"mc","stem":"박물관에서 오래된 그릇을 보았어요. 이 그릇으로 알 수 있는 것은 무엇일까요?","options":[{"t":"옛날 사람들이 음식을 담아 먹던 생활 모습","correct":true},{"t":"내 친구의 이름","mis":"SO3-1-u2-X06"},{"t":"우주의 끝","mis":"SO3-1-u2-X06"},{"t":"앞으로 생길 그릇 가게","mis":"SO3-1-u2-X06"}],"explanation":["그릇은","음식을 담아요.","옛 생활"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L07_basic#8','soc',3,1,'u2','L07','g3_1_soc_u2_L07_basic','lesson_basic','SO3-1-u2-C7',2,'match','auto','옛 생활을 알려 주는 것과 알 수 있는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-1-u2-C7","difficulty":2,"kind":"match","stem":"옛 생활을 알려 주는 것과 알 수 있는 것을 알맞게 이으세요.","pairs":[{"l":"옛 사진","r":"그때 사람들의 옷차림과 거리 모습"},{"l":"옛 건축물","r":"옛날 사람들이 살던 집"},{"l":"오래된 물건","r":"무엇을 쓰며 살았는지"}],"mis":"SO3-1-u2-X18","explanation":["사진은 모습","건축물은 집","물건은 쓰임"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L07_basic#9','soc',3,1,'u2','L07','g3_1_soc_u2_L07_basic','lesson_basic','SO3-1-u2-C7',2,'ox','auto','옛날 생활 모습을 알려면 사진 · 물건 · 건축물을 함께 살펴보는 것이 좋아요.',ARRAY['SO3-1-u2-X17']::text[],false,'{"seq":9,"concept":"SO3-1-u2-C7","difficulty":2,"kind":"ox","stem":"옛날 생활 모습을 알려면 사진 · 물건 · 건축물을 함께 살펴보는 것이 좋아요.","answer":"O","reason_options":[{"t":"여러 가지를 함께 보면 한 가지만 볼 때보다 더 잘 알 수 있기 때문에","correct":true},{"t":"한 가지만 보아도 옛날을 모두 알 수 있기 때문에","mis":"SO3-1-u2-X17"}],"mis":"SO3-1-u2-X17","explanation":["하나보다","여럿","O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L07_basic#10','soc',3,1,'u2','L07','g3_1_soc_u2_L07_basic','lesson_basic','SO3-1-u2-C7',3,'mc','auto','「할머니 댁에서 찾은 옛 사진」으로 알 수 있는 것은 무엇일까요?',ARRAY['SO3-1-u2-X18','SO3-1-u2-X17']::text[],false,'{"seq":10,"concept":"SO3-1-u2-C7","difficulty":3,"kind":"mc","stem":"「할머니 댁에서 찾은 옛 사진」으로 알 수 있는 것은 무엇일까요?","options":[{"t":"옛날에는 흙길 옆 초가집에 살며 한복을 입고 지냈다","correct":true},{"t":"옛날에는 높은 아파트가 많았다","mis":"SO3-1-u2-X18"},{"t":"이 사진은 앞으로 생길 마을 모습이다","mis":"SO3-1-u2-X18"},{"t":"사진 한 장만 보면 옛날 생활을 모두 알 수 있다","mis":"SO3-1-u2-X17"}],"explanation":["흙길 · 초가집","한복","옛 생활"],"asset":{"type":"passage","lines":["빛이 바랜 흑백 사진","— 흙길 양쪽에 초가집이 낮게 늘어서 있다.","— 사람들이 한복을 입고 지게를 지고 간다.","— 길가에서 아이들이 굴렁쇠를 굴린다."],"title":"할머니 댁에서 찾은 옛 사진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L07_challenge#1','soc',3,1,'u2','L07','g3_1_soc_u2_L07_challenge','lesson_challenge','SO3-1-u2-C7',2,'mc','auto','옛날 생활 모습을 알 수 있는 것을 바르게 모은 것은 무엇일까요?',ARRAY['SO3-1-u2-X06','SO3-1-u2-X16']::text[],false,'{"seq":1,"concept":"SO3-1-u2-C7","difficulty":2,"kind":"mc","stem":"옛날 생활 모습을 알 수 있는 것을 바르게 모은 것은 무엇일까요?","options":[{"t":"옛 사진 · 옛 건축물 · 오래된 물건","correct":true},{"t":"옛 사진 · 내일 날씨 · 다음 주 계획","mis":"SO3-1-u2-X06"},{"t":"오늘 급식 · 새 운동화 · 내년 달력","mis":"SO3-1-u2-X06"},{"t":"상상한 그림 · 꿈 · 내일 일기","mis":"SO3-1-u2-X16"}],"explanation":["옛날부터","남은 것","셋 다"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L07_challenge#2','soc',3,1,'u2','L07','g3_1_soc_u2_L07_challenge','lesson_challenge','SO3-1-u2-C7',2,'mc','auto','옛날 집과 오늘날 건물을 견주어 보면 알 수 있는 것은 무엇일까요?',ARRAY['SO3-1-u2-X08','SO3-1-u2-X16','SO3-1-u2-X18']::text[],false,'{"seq":2,"concept":"SO3-1-u2-C7","difficulty":2,"kind":"mc","stem":"옛날 집과 오늘날 건물을 견주어 보면 알 수 있는 것은 무엇일까요?","options":[{"t":"사는 모습이 시간이 흐르며 달라졌다","correct":true},{"t":"옛날과 오늘은 사는 모습이 똑같다","mis":"SO3-1-u2-X08"},{"t":"옛날 집은 아무것도 알려 주지 않는다","mis":"SO3-1-u2-X16"},{"t":"오늘 건물이 옛날 것이다","mis":"SO3-1-u2-X18"}],"explanation":["옛날 집","오늘 건물","달라졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L07_challenge#3','soc',3,1,'u2','L07','g3_1_soc_u2_L07_challenge','lesson_challenge','SO3-1-u2-C7',3,'mc','auto','「할머니 댁에서 찾은 옛 사진」에서 옛날 아이들의 놀이를 알려 주는 부분은 무엇일까요?',ARRAY['SO3-1-u2-X18']::text[],false,'{"seq":3,"concept":"SO3-1-u2-C7","difficulty":3,"kind":"mc","stem":"「할머니 댁에서 찾은 옛 사진」에서 옛날 아이들의 놀이를 알려 주는 부분은 무엇일까요?","options":[{"t":"길가에서 아이들이 굴렁쇠를 굴린다","correct":true},{"t":"사람들이 한복을 입고 지게를 지고 간다","mis":"SO3-1-u2-X18"},{"t":"흙길 양쪽에 초가집이 늘어서 있다","mis":"SO3-1-u2-X18"},{"t":"빛이 바랜 흑백 사진","mis":"SO3-1-u2-X18"}],"explanation":["아이들","굴렁쇠","놀이"],"asset":{"type":"passage","lines":["빛이 바랜 흑백 사진","— 흙길 양쪽에 초가집이 낮게 늘어서 있다.","— 사람들이 한복을 입고 지게를 지고 간다.","— 길가에서 아이들이 굴렁쇠를 굴린다."],"title":"할머니 댁에서 찾은 옛 사진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L07_challenge#4','soc',3,1,'u2','L07','g3_1_soc_u2_L07_challenge','lesson_challenge','SO3-1-u2-C7',3,'error','auto','옛날 생활 모습을 알아본 친구들의 말이에요. 잘못 말한 친구는 누구일까요?',ARRAY['SO3-1-u2-X06','SO3-1-u2-X18','SO3-1-u2-X16']::text[],false,'{"seq":4,"concept":"SO3-1-u2-C7","difficulty":3,"kind":"error","stem":"옛날 생활 모습을 알아본 친구들의 말이에요. 잘못 말한 친구는 누구일까요?","options":[{"t":"지호 — 「옛날을 알려고 내일 날씨를 알아봤어.」","correct":true,"mis_target":"SO3-1-u2-X06"},{"t":"하린 — 「옛 사진을 살펴봤어.」","mis":"SO3-1-u2-X18"},{"t":"서준 — 「옛 건축물을 찾아봤어.」","mis":"SO3-1-u2-X16"}],"explanation":["내일 날씨는","옛날이 아니에요.","지호가 잘못"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L07_challenge#5','soc',3,1,'u2','L07','g3_1_soc_u2_L07_challenge','lesson_challenge','SO3-1-u2-C7',3,'mc','auto','서준이는 옛 사진 한 장만 보고 「옛날 생활은 이제 다 알았어.」라고 했어요. 알맞게 고쳐 준 말은 무엇일까요?',ARRAY['SO3-1-u2-X17','SO3-1-u2-X16','SO3-1-u2-X18']::text[],false,'{"seq":5,"concept":"SO3-1-u2-C7","difficulty":3,"kind":"mc","stem":"서준이는 옛 사진 한 장만 보고 「옛날 생활은 이제 다 알았어.」라고 했어요. 알맞게 고쳐 준 말은 무엇일까요?","options":[{"t":"「사진 · 물건 · 건축물을 함께 살펴보면 더 잘 알 수 있어.」","correct":true},{"t":"「맞아. 사진 한 장이면 충분해.」","mis":"SO3-1-u2-X17"},{"t":"「옛날은 원래 알 수 없어.」","mis":"SO3-1-u2-X16"},{"t":"「사진은 미래 모습이라 쓸모없어.」","mis":"SO3-1-u2-X18"}],"explanation":["한 장으로","다 알까요?","함께 보기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L07_challenge#6','soc',3,1,'u2','L07','g3_1_soc_u2_L07_challenge','lesson_challenge','SO3-1-u2-C7',3,'ox','auto','옛날 생활 모습은 아무도 직접 볼 수 없으니 모두 상상으로만 알아요.',ARRAY['SO3-1-u2-X16']::text[],false,'{"seq":6,"concept":"SO3-1-u2-C7","difficulty":3,"kind":"ox","stem":"옛날 생활 모습은 아무도 직접 볼 수 없으니 모두 상상으로만 알아요.","answer":"X","reason_options":[{"t":"옛날부터 남아 있는 사진 · 물건 · 건축물 · 기록을 보고 알 수 있기 때문에","correct":true},{"t":"옛날의 것은 하나도 남아 있지 않기 때문에","mis":"SO3-1-u2-X16"}],"mis":"SO3-1-u2-X16","explanation":["남아 있는 것","살펴보면","X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L07_challenge#7','soc',3,1,'u2','L07','g3_1_soc_u2_L07_challenge','lesson_challenge','SO3-1-u2-C7',3,'mc','auto','옛 기록에 「겨울이면 마을 사람들이 모여 김장을 했다.」라고 적혀 있어요. 알 수 있는 것은 무엇일까요?',ARRAY['SO3-1-u2-X06','SO3-1-u2-X16']::text[],false,'{"seq":7,"concept":"SO3-1-u2-C7","difficulty":3,"kind":"mc","stem":"옛 기록에 「겨울이면 마을 사람들이 모여 김장을 했다.」라고 적혀 있어요. 알 수 있는 것은 무엇일까요?","options":[{"t":"옛날 마을 사람들이 함께 겨울 음식을 준비하던 생활","correct":true},{"t":"앞으로 김장을 하지 않는다는 것","mis":"SO3-1-u2-X06"},{"t":"옛 기록은 모두 상상이라는 것","mis":"SO3-1-u2-X16"},{"t":"오늘 우리 집 저녁 메뉴","mis":"SO3-1-u2-X06"}],"explanation":["겨울","함께 모여","김장"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L07_challenge#8','soc',3,1,'u2','L07','g3_1_soc_u2_L07_challenge','lesson_challenge','SO3-1-u2-C7',4,'essay','teacher','옛날 생활 모습을 알려 주는 것 세 가지를 쓰고, 각각 무엇을 알려 주는지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-1-u2-C7","difficulty":4,"kind":"essay","stem":"옛날 생활 모습을 알려 주는 것 세 가지를 쓰고, 각각 무엇을 알려 주는지 쓰세요.","answer_guide":{"answer":"예: 옛 사진 — 그때 사람들의 옷차림과 거리 모습 / 옛 건축물 — 옛날 사람들이 살던 집 / 오래된 물건 — 옛날 사람들이 무엇을 쓰며 살았는지","scoring_points":["세 가지를 썼는가","각각 알려 주는 것을 썼는가","짝이 알맞은가"]},"explanation":["사진","건축물","물건"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L07_challenge#9','soc',3,1,'u2','L07','g3_1_soc_u2_L07_challenge','lesson_challenge','SO3-1-u2-C7',4,'essay','teacher','우리가 직접 가 보지 못한 옛날을 알 수 있는 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-1-u2-C7","difficulty":4,"kind":"essay","stem":"우리가 직접 가 보지 못한 옛날을 알 수 있는 까닭을 쓰세요.","answer_guide":{"answer":"예: 옛날에 찍은 사진, 쓰던 물건, 지은 집과 기록처럼 그때부터 지금까지 남아 있는 것들이 있어서 그것을 살펴보면 옛날 생활 모습을 알 수 있다.","scoring_points":["남아 있는 것을 들었는가","살펴보면 알 수 있다고 썼는가","내용이 알맞은가"]},"explanation":["갈 수는 없어요.","남아 있는 것","살펴봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L07_challenge#10','soc',3,1,'u2','L07','g3_1_soc_u2_L07_challenge','lesson_challenge','SO3-1-u2-C7',4,'essay','teacher','「할머니 댁에서 찾은 옛 사진」을 보고 옛날과 오늘날 생활이 달라진 점 두 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-1-u2-C7","difficulty":4,"kind":"essay","stem":"「할머니 댁에서 찾은 옛 사진」을 보고 옛날과 오늘날 생활이 달라진 점 두 가지를 쓰세요.","answer_guide":{"answer":"예: 옛날에는 흙길이었는데 오늘날에는 포장된 길이 많다. 옛날에는 지게로 짐을 날랐는데 오늘날에는 차로 짐을 나른다.","scoring_points":["달라진 점 두 가지를 썼는가","사진에서 근거를 찾았는가","옛날과 오늘을 견주었는가"]},"explanation":["흙길","지게","오늘날은?"],"asset":{"type":"passage","lines":["빛이 바랜 흑백 사진","— 흙길 양쪽에 초가집이 낮게 늘어서 있다.","— 사람들이 한복을 입고 지게를 지고 간다.","— 길가에서 아이들이 굴렁쇠를 굴린다."],"title":"할머니 댁에서 찾은 옛 사진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
