INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L08_basic#2','soc',3,1,'u2','L08','g3_1_soc_u2_L08_basic','lesson_basic','SO3-1-u2-C8',1,'mc','auto','숯불을 넣어 달군 뒤 옷의 구김을 펴던 옛날 물건은 무엇일까요?',ARRAY['SO3-1-u2-X19']::text[],false,'{"seq":2,"concept":"SO3-1-u2-C8","difficulty":1,"kind":"mc","stem":"숯불을 넣어 달군 뒤 옷의 구김을 펴던 옛날 물건은 무엇일까요?","options":[{"t":"숯다리미","correct":true},{"t":"맷돌","mis":"SO3-1-u2-X19"},{"t":"가마솥","mis":"SO3-1-u2-X19"},{"t":"두레박","mis":"SO3-1-u2-X19"}],"explanation":["숯불","옷 펴기","숯다리미"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L08_basic#3','soc',3,1,'u2','L08','g3_1_soc_u2_L08_basic','lesson_basic','SO3-1-u2-C8',1,'mc','auto','오래된 물건의 쓰임을 알면 무엇을 알 수 있을까요?',ARRAY['SO3-1-u2-X06','SO3-1-u2-X21']::text[],false,'{"seq":3,"concept":"SO3-1-u2-C8","difficulty":1,"kind":"mc","stem":"오래된 물건의 쓰임을 알면 무엇을 알 수 있을까요?","options":[{"t":"옛날 사람들의 생활 모습","correct":true},{"t":"내일 시간표","mis":"SO3-1-u2-X06"},{"t":"오늘 급식","mis":"SO3-1-u2-X06"},{"t":"아무것도 알 수 없다","mis":"SO3-1-u2-X21"}],"explanation":["무엇에 썼나요?","쓰임","생활 모습"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L08_basic#4','soc',3,1,'u2','L08','g3_1_soc_u2_L08_basic','lesson_basic','SO3-1-u2-C8',1,'ox','auto','곡식을 갈던 맷돌의 일을 오늘날에는 믹서기가 해요.',ARRAY['SO3-1-u2-X20']::text[],false,'{"seq":4,"concept":"SO3-1-u2-C8","difficulty":1,"kind":"ox","stem":"곡식을 갈던 맷돌의 일을 오늘날에는 믹서기가 해요.","answer":"O","reason_options":[{"t":"맷돌과 믹서기는 모두 무언가를 가는 일을 하기 때문에","correct":true},{"t":"믹서기는 옷의 구김을 펴는 물건이기 때문에","mis":"SO3-1-u2-X20"}],"mis":"SO3-1-u2-X20","explanation":["맷돌은 갈아요.","믹서기도","O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L08_basic#5','soc',3,1,'u2','L08','g3_1_soc_u2_L08_basic','lesson_basic','SO3-1-u2-C8',2,'match','auto','옛 물건과 같은 일을 하는 오늘날 물건을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-1-u2-C8","difficulty":2,"kind":"match","stem":"옛 물건과 같은 일을 하는 오늘날 물건을 알맞게 이으세요.","pairs":[{"l":"맷돌","r":"믹서기"},{"l":"다듬잇돌과 방망이","r":"전기다리미"},{"l":"가마솥","r":"전기밥솥"}],"mis":"SO3-1-u2-X20","explanation":["갈기","옷 펴기","밥 짓기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L08_basic#6','soc',3,1,'u2','L08','g3_1_soc_u2_L08_basic','lesson_basic','SO3-1-u2-C8',2,'mc','auto','재봉틀은 옛날에 무엇을 할 때 쓰던 물건일까요?',ARRAY['SO3-1-u2-X19']::text[],false,'{"seq":6,"concept":"SO3-1-u2-C8","difficulty":2,"kind":"mc","stem":"재봉틀은 옛날에 무엇을 할 때 쓰던 물건일까요?","options":[{"t":"옷을 지을 때","correct":true},{"t":"밥을 지을 때","mis":"SO3-1-u2-X19"},{"t":"곡식을 갈 때","mis":"SO3-1-u2-X19"},{"t":"물을 길을 때","mis":"SO3-1-u2-X19"}],"explanation":["바늘과 실","천을 꿰매요.","옷"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L08_basic#7','soc',3,1,'u2','L08','g3_1_soc_u2_L08_basic','lesson_basic','SO3-1-u2-C8',2,'mc','auto','「오래된 물건 카드」에서 밥을 짓던 물건은 무엇일까요?',ARRAY['SO3-1-u2-X19']::text[],false,'{"seq":7,"concept":"SO3-1-u2-C8","difficulty":2,"kind":"mc","stem":"「오래된 물건 카드」에서 밥을 짓던 물건은 무엇일까요?","options":[{"t":"㉣ 가마솥","correct":true},{"t":"㉠ 맷돌","mis":"SO3-1-u2-X19"},{"t":"㉡ 다듬잇돌과 방망이","mis":"SO3-1-u2-X19"},{"t":"㉢ 숯다리미","mis":"SO3-1-u2-X19"}],"explanation":["아궁이 위","큰 솥","가마솥"],"asset":{"type":"passage","lines":["㉠ 맷돌 — 둥근 돌 두 개를 포개고 손잡이를 돌린다.","㉡ 다듬잇돌과 방망이 — 옷감을 올려놓고 두드린다.","㉢ 숯다리미 — 안에 숯불을 담아 달군다.","㉣ 가마솥 — 아궁이 위에 걸어 둔다."],"title":"오래된 물건 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L08_basic#8','soc',3,1,'u2','L08','g3_1_soc_u2_L08_basic','lesson_basic','SO3-1-u2-C8',2,'mc','auto','할아버지께서 오래도록 아끼며 간직해 온 낡은 시계는 어떤 물건일까요?',ARRAY['SO3-1-u2-X21']::text[],false,'{"seq":8,"concept":"SO3-1-u2-C8","difficulty":2,"kind":"mc","stem":"할아버지께서 오래도록 아끼며 간직해 온 낡은 시계는 어떤 물건일까요?","options":[{"t":"과거가 담긴 소중한 물건","correct":true},{"t":"쓸모없는 물건","mis":"SO3-1-u2-X21"},{"t":"새로 산 물건","mis":"SO3-1-u2-X21"},{"t":"빌린 물건","mis":"SO3-1-u2-X21"}],"explanation":["오래 간직한","아끼는","소중한 물건"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L08_basic#9','soc',3,1,'u2','L08','g3_1_soc_u2_L08_basic','lesson_basic','SO3-1-u2-C8',2,'ox','auto','오래된 물건은 낡아서 아무것도 알려 주지 않아요.',ARRAY['SO3-1-u2-X21']::text[],false,'{"seq":9,"concept":"SO3-1-u2-C8","difficulty":2,"kind":"ox","stem":"오래된 물건은 낡아서 아무것도 알려 주지 않아요.","answer":"X","reason_options":[{"t":"물건의 쓰임과 모습을 보면 옛날 생활 모습을 알 수 있기 때문에","correct":true},{"t":"오래된 물건은 오늘날 쓰지 않으니 옛날도 알려 줄 수 없기 때문에","mis":"SO3-1-u2-X21"}],"mis":"SO3-1-u2-X21","explanation":["쓰임을 보면","옛 생활","X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L08_basic#10','soc',3,1,'u2','L08','g3_1_soc_u2_L08_basic','lesson_basic','SO3-1-u2-C8',3,'mc','auto','「오래된 물건 카드」 가운데 옷을 손질하던 물건끼리 모은 것은 무엇일까요?',ARRAY['SO3-1-u2-X19']::text[],false,'{"seq":10,"concept":"SO3-1-u2-C8","difficulty":3,"kind":"mc","stem":"「오래된 물건 카드」 가운데 옷을 손질하던 물건끼리 모은 것은 무엇일까요?","options":[{"t":"㉡ · ㉢","correct":true},{"t":"㉠ · ㉣","mis":"SO3-1-u2-X19"},{"t":"㉠ · ㉡","mis":"SO3-1-u2-X19"},{"t":"㉢ · ㉣","mis":"SO3-1-u2-X19"}],"explanation":["두드리기","달구어 펴기","㉡ · ㉢"],"asset":{"type":"passage","lines":["㉠ 맷돌 — 둥근 돌 두 개를 포개고 손잡이를 돌린다.","㉡ 다듬잇돌과 방망이 — 옷감을 올려놓고 두드린다.","㉢ 숯다리미 — 안에 숯불을 담아 달군다.","㉣ 가마솥 — 아궁이 위에 걸어 둔다."],"title":"오래된 물건 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L08_challenge#1','soc',3,1,'u2','L08','g3_1_soc_u2_L08_challenge','lesson_challenge','SO3-1-u2-C8',2,'mc','auto','다듬잇돌과 방망이로 옷을 두드려 펴던 일을 오늘날에는 무엇이 할까요?',ARRAY['SO3-1-u2-X20']::text[],false,'{"seq":1,"concept":"SO3-1-u2-C8","difficulty":2,"kind":"mc","stem":"다듬잇돌과 방망이로 옷을 두드려 펴던 일을 오늘날에는 무엇이 할까요?","options":[{"t":"전기다리미","correct":true},{"t":"믹서기","mis":"SO3-1-u2-X20"},{"t":"냉장고","mis":"SO3-1-u2-X20"},{"t":"자전거","mis":"SO3-1-u2-X20"}],"explanation":["옷 펴기","오늘날","전기다리미"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L08_challenge#2','soc',3,1,'u2','L08','g3_1_soc_u2_L08_challenge','lesson_challenge','SO3-1-u2-C8',2,'mc','auto','옛 물건과 오늘날 물건을 견주면 무엇을 알 수 있을까요?',ARRAY['SO3-1-u2-X08','SO3-1-u2-X21','SO3-1-u2-X20']::text[],false,'{"seq":2,"concept":"SO3-1-u2-C8","difficulty":2,"kind":"mc","stem":"옛 물건과 오늘날 물건을 견주면 무엇을 알 수 있을까요?","options":[{"t":"같은 일을 하더라도 쓰는 물건이 달라졌다","correct":true},{"t":"옛날과 오늘은 쓰는 물건이 똑같다","mis":"SO3-1-u2-X08"},{"t":"옛 물건은 아무 일도 하지 않았다","mis":"SO3-1-u2-X21"},{"t":"오늘 물건이 더 옛날 것이다","mis":"SO3-1-u2-X20"}],"explanation":["같은 일","다른 물건","달라졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L08_challenge#3','soc',3,1,'u2','L08','g3_1_soc_u2_L08_challenge','lesson_challenge','SO3-1-u2-C8',3,'mc','auto','옛 물건과 그 쓰임이 바르게 짝지어진 것은 무엇일까요?',ARRAY['SO3-1-u2-X19']::text[],false,'{"seq":3,"concept":"SO3-1-u2-C8","difficulty":3,"kind":"mc","stem":"옛 물건과 그 쓰임이 바르게 짝지어진 것은 무엇일까요?","options":[{"t":"가마솥 — 아궁이에 걸고 밥을 지었다","correct":true},{"t":"맷돌 — 옷의 구김을 폈다","mis":"SO3-1-u2-X19"},{"t":"숯다리미 — 곡식을 갈았다","mis":"SO3-1-u2-X19"},{"t":"재봉틀 — 물을 데웠다","mis":"SO3-1-u2-X19"}],"explanation":["가마솥은","밥","아궁이"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L08_challenge#4','soc',3,1,'u2','L08','g3_1_soc_u2_L08_challenge','lesson_challenge','SO3-1-u2-C8',3,'mc','auto','맷돌로 콩을 갈아 두부를 만들던 일로 알 수 있는 것은 무엇일까요?',ARRAY['SO3-1-u2-X20','SO3-1-u2-X19','SO3-1-u2-X21']::text[],false,'{"seq":4,"concept":"SO3-1-u2-C8","difficulty":3,"kind":"mc","stem":"맷돌로 콩을 갈아 두부를 만들던 일로 알 수 있는 것은 무엇일까요?","options":[{"t":"옛날에는 손으로 힘을 들여 음식을 준비했다","correct":true},{"t":"옛날에도 전기로 콩을 갈았다","mis":"SO3-1-u2-X20"},{"t":"옛날 사람들은 두부를 먹지 않았다","mis":"SO3-1-u2-X19"},{"t":"맷돌은 아무것도 알려 주지 않는다","mis":"SO3-1-u2-X21"}],"explanation":["손잡이를","돌려서","힘을 들였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L08_challenge#5','soc',3,1,'u2','L08','g3_1_soc_u2_L08_challenge','lesson_challenge','SO3-1-u2-C8',3,'error','auto','오래된 물건에 대해 친구들이 말했어요. 잘못 말한 친구는 누구일까요?',ARRAY['SO3-1-u2-X21','SO3-1-u2-X19']::text[],false,'{"seq":5,"concept":"SO3-1-u2-C8","difficulty":3,"kind":"error","stem":"오래된 물건에 대해 친구들이 말했어요. 잘못 말한 친구는 누구일까요?","options":[{"t":"예린 — 「오래된 물건은 아무것도 알려 주지 않아.」","correct":true,"mis_target":"SO3-1-u2-X21"},{"t":"서준 — 「쓰임을 보면 옛 생활을 알 수 있어.」","mis":"SO3-1-u2-X19"},{"t":"수아 — 「소중히 간직한 물건에도 과거가 담겨 있어.」","mis":"SO3-1-u2-X21"}],"explanation":["물건은","옛 생활을","알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L08_challenge#6','soc',3,1,'u2','L08','g3_1_soc_u2_L08_challenge','lesson_challenge','SO3-1-u2-C8',3,'mc','auto','「오래된 물건 카드」의 ㉠과 같은 일을 하는 오늘날 물건은 무엇일까요?',ARRAY['SO3-1-u2-X20']::text[],false,'{"seq":6,"concept":"SO3-1-u2-C8","difficulty":3,"kind":"mc","stem":"「오래된 물건 카드」의 ㉠과 같은 일을 하는 오늘날 물건은 무엇일까요?","options":[{"t":"믹서기","correct":true},{"t":"전기다리미","mis":"SO3-1-u2-X20"},{"t":"전기밥솥","mis":"SO3-1-u2-X20"},{"t":"세탁기","mis":"SO3-1-u2-X20"}],"explanation":["㉠은 맷돌","갈기","믹서기"],"asset":{"type":"passage","lines":["㉠ 맷돌 — 둥근 돌 두 개를 포개고 손잡이를 돌린다.","㉡ 다듬잇돌과 방망이 — 옷감을 올려놓고 두드린다.","㉢ 숯다리미 — 안에 숯불을 담아 달군다.","㉣ 가마솥 — 아궁이 위에 걸어 둔다."],"title":"오래된 물건 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L08_challenge#7','soc',3,1,'u2','L08','g3_1_soc_u2_L08_challenge','lesson_challenge','SO3-1-u2-C8',3,'ox','auto','숯다리미를 쓰던 때보다 전기다리미를 쓰는 오늘날이 옷 손질하기가 더 편해요.',ARRAY['SO3-1-u2-X20']::text[],false,'{"seq":7,"concept":"SO3-1-u2-C8","difficulty":3,"kind":"ox","stem":"숯다리미를 쓰던 때보다 전기다리미를 쓰는 오늘날이 옷 손질하기가 더 편해요.","answer":"O","reason_options":[{"t":"같은 일을 오늘날에는 전기로 더 쉽고 빠르게 하기 때문에","correct":true},{"t":"두 물건은 하는 일이 서로 달라 견줄 수 없기 때문에","mis":"SO3-1-u2-X20"}],"mis":"SO3-1-u2-X20","explanation":["같은 일","전기로","더 편해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L08_challenge#8','soc',3,1,'u2','L08','g3_1_soc_u2_L08_challenge','lesson_challenge','SO3-1-u2-C8',4,'essay','teacher','옛 물건 하나를 골라 쓰임을 쓰고, 그 일을 오늘날에는 어떤 물건이 하는지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-1-u2-C8","difficulty":4,"kind":"essay","stem":"옛 물건 하나를 골라 쓰임을 쓰고, 그 일을 오늘날에는 어떤 물건이 하는지 쓰세요.","answer_guide":{"answer":"예: 맷돌 — 곡식이나 콩을 갈 때 썼다. 오늘날에는 믹서기가 이 일을 한다.","scoring_points":["옛 물건을 골랐는가","쓰임을 바르게 썼는가","같은 일을 하는 오늘 물건을 썼는가"]},"explanation":["옛 물건","쓰임","오늘 물건"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L08_challenge#9','soc',3,1,'u2','L08','g3_1_soc_u2_L08_challenge','lesson_challenge','SO3-1-u2-C8',4,'essay','teacher','우리 집에서 오래 간직해 온 물건을 하나 떠올려 그 물건에 담긴 과거 이야기를 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-1-u2-C8","difficulty":4,"kind":"essay","stem":"우리 집에서 오래 간직해 온 물건을 하나 떠올려 그 물건에 담긴 과거 이야기를 쓰세요.","answer_guide":{"answer":"예: 할머니의 낡은 반짇고리 — 할머니께서 젊었을 때 가족의 옷을 꿰매던 물건이라 할머니가 바느질하던 옛 생활을 알 수 있다.","scoring_points":["물건을 골랐는가","물건에 담긴 이야기를 썼는가","과거 생활과 이었는가"]},"explanation":["오래 간직한","누가 썼나요?","그때 생활"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L08_challenge#10','soc',3,1,'u2','L08','g3_1_soc_u2_L08_challenge','lesson_challenge','SO3-1-u2-C8',4,'essay','teacher','옛 물건과 오늘날 물건을 견주어 달라진 점을 쓰고, 그것으로 알 수 있는 생활의 변화를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-1-u2-C8","difficulty":4,"kind":"essay","stem":"옛 물건과 오늘날 물건을 견주어 달라진 점을 쓰고, 그것으로 알 수 있는 생활의 변화를 쓰세요.","answer_guide":{"answer":"예: 옛날에는 다듬잇돌과 방망이로 옷을 두드려 폈는데 오늘날에는 전기다리미를 쓴다. 옛날보다 집안일이 쉽고 빨라졌다.","scoring_points":["두 물건을 견주었는가","달라진 점을 썼는가","생활의 변화를 썼는가"]},"explanation":["옛 물건","오늘 물건","생활의 변화"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
