INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L09_basic#10','soc',3,1,'u2','L09','g3_1_soc_u2_L09_basic','lesson_basic','SO3-1-u2-C9',3,'mc','auto','「옛 신문」의 버들마을 소식으로 알 수 있는 것은 무엇일까요?',ARRAY['SO3-1-u2-X25','SO3-1-u2-X06','SO3-1-u2-X17']::text[],false,'{"seq":10,"concept":"SO3-1-u2-C9","difficulty":3,"kind":"mc","stem":"「옛 신문」의 버들마을 소식으로 알 수 있는 것은 무엇일까요?","options":[{"t":"옛날 장날에는 소달구지가 오가고 여러 마을 사람이 모여 물건을 사고팔았다","correct":true},{"t":"옛날 버들마을에는 장이 서지 않았다","mis":"SO3-1-u2-X25"},{"t":"이 신문은 앞으로 일어날 일을 적었다","mis":"SO3-1-u2-X06"},{"t":"신문만 보면 버들마을 생활을 모두 안다","mis":"SO3-1-u2-X17"}],"explanation":["장날","소달구지","사고팔았어요."],"asset":{"type":"passage","lines":["버들마을 소식","「장날마다 소달구지가 줄지어 들어와」","쌀 · 콩 · 짚신을 사고팔러 이웃 마을 사람들도 모였다.","「마을 우물가에 새 두레박을 달아」"],"title":"옛 신문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
