INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L09_challenge#2','soc',3,1,'u2','L09','g3_1_soc_u2_L09_challenge','lesson_challenge','SO3-1-u2-C9',2,'mc','auto','옛 생활 모습을 더 자세히 알려면 어떻게 하면 좋을까요?',ARRAY['SO3-1-u2-X17','SO3-1-u2-X16']::text[],false,'{"seq":2,"concept":"SO3-1-u2-C9","difficulty":2,"kind":"mc","stem":"옛 생활 모습을 더 자세히 알려면 어떻게 하면 좋을까요?","options":[{"t":"자료와 증언을 함께 살펴본다","correct":true},{"t":"한 가지 자료만 본다","mis":"SO3-1-u2-X17"},{"t":"상상만 한다","mis":"SO3-1-u2-X16"},{"t":"아무것도 안 본다","mis":"SO3-1-u2-X16"}],"explanation":["하나보다","함께","더 자세히"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L09_challenge#3','soc',3,1,'u2','L09','g3_1_soc_u2_L09_challenge','lesson_challenge','SO3-1-u2-C9',3,'mc','auto','「옛 신문」과 함께 살펴보면 버들마을 장날을 더 생생하게 알 수 있는 것은 무엇일까요?',ARRAY['SO3-1-u2-X06']::text[],false,'{"seq":3,"concept":"SO3-1-u2-C9","difficulty":3,"kind":"mc","stem":"「옛 신문」과 함께 살펴보면 버들마을 장날을 더 생생하게 알 수 있는 것은 무엇일까요?","options":[{"t":"그때 장에 다니신 할아버지의 증언","correct":true},{"t":"내일 날씨 예보","mis":"SO3-1-u2-X06"},{"t":"새로 산 장난감 설명서","mis":"SO3-1-u2-X06"},{"t":"오늘 산 과자 봉지","mis":"SO3-1-u2-X06"}],"explanation":["그때를","겪은 분","증언"],"asset":{"type":"passage","lines":["버들마을 소식","「장날마다 소달구지가 줄지어 들어와」","쌀 · 콩 · 짚신을 사고팔러 이웃 마을 사람들도 모였다.","「마을 우물가에 새 두레박을 달아」"],"title":"옛 신문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L09_challenge#4','soc',3,1,'u2','L09','g3_1_soc_u2_L09_challenge','lesson_challenge','SO3-1-u2-C9',3,'mc','auto','증언을 들을 때 바른 태도는 무엇일까요?',ARRAY['SO3-1-u2-X22','SO3-1-u2-X23']::text[],false,'{"seq":4,"concept":"SO3-1-u2-C9","difficulty":3,"kind":"mc","stem":"증언을 들을 때 바른 태도는 무엇일까요?","options":[{"t":"궁금한 것을 미리 정해 공손히 여쭙고 들은 내용을 적는다","correct":true},{"t":"아무에게나 묻고 적지 않는다","mis":"SO3-1-u2-X22"},{"t":"말씀 도중에 내 생각만 말한다","mis":"SO3-1-u2-X22"},{"t":"오래된 이야기는 쓸모없다며 듣지 않는다","mis":"SO3-1-u2-X23"}],"explanation":["미리 정하고","공손히","적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L09_challenge#5','soc',3,1,'u2','L09','g3_1_soc_u2_L09_challenge','lesson_challenge','SO3-1-u2-C9',3,'error','auto','자료와 증언에 대해 친구들이 말했어요. 잘못 말한 친구는 누구일까요?',ARRAY['SO3-1-u2-X23','SO3-1-u2-X17']::text[],false,'{"seq":5,"concept":"SO3-1-u2-C9","difficulty":3,"kind":"error","stem":"자료와 증언에 대해 친구들이 말했어요. 잘못 말한 친구는 누구일까요?","options":[{"t":"도윤 — 「자료와 증언은 쓸모가 없어.」","correct":true,"mis_target":"SO3-1-u2-X23"},{"t":"하린 — 「옛 신문도 자료가 돼.」","mis":"SO3-1-u2-X23"},{"t":"지호 — 「여러 가지를 함께 보면 더 잘 알아.」","mis":"SO3-1-u2-X17"}],"explanation":["자료와 증언은","도움이 돼요.","도윤이가 잘못"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L09_challenge#6','soc',3,1,'u2','L09','g3_1_soc_u2_L09_challenge','lesson_challenge','SO3-1-u2-C9',3,'mc','auto','할머니의 증언과 함께 보면 좋은 자료는 무엇일까요?',ARRAY['SO3-1-u2-X06']::text[],false,'{"seq":6,"concept":"SO3-1-u2-C9","difficulty":3,"kind":"mc","stem":"할머니의 증언과 함께 보면 좋은 자료는 무엇일까요?","options":[{"t":"마을 우물가에서 물을 긷는 모습이 담긴 옛 사진","correct":true},{"t":"내년 달력","mis":"SO3-1-u2-X06"},{"t":"오늘 산 생수병","mis":"SO3-1-u2-X06"},{"t":"앞으로 지을 수영장 그림","mis":"SO3-1-u2-X06"}],"explanation":["증언 속","우물","옛 사진"],"asset":{"type":"speech","turns":[{"who":"예린","text":"할머니, 어릴 때 물은 어디서 길어 오셨어요?"},{"who":"할머니","text":"마을 우물에서 두레박으로 길어 물동이에 이고 왔단다."},{"who":"할머니","text":"겨울엔 냇가에서 손을 호호 불며 빨래를 했지."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L09_challenge#7','soc',3,1,'u2','L09','g3_1_soc_u2_L09_challenge','lesson_challenge','SO3-1-u2-C9',3,'ox','auto','옛 신문 한 장만 읽으면 그때 생활을 빠짐없이 다 알 수 있어요.',ARRAY['SO3-1-u2-X17']::text[],false,'{"seq":7,"concept":"SO3-1-u2-C9","difficulty":3,"kind":"ox","stem":"옛 신문 한 장만 읽으면 그때 생활을 빠짐없이 다 알 수 있어요.","answer":"X","reason_options":[{"t":"자료마다 담긴 것이 달라 다른 자료와 증언을 함께 보아야 더 잘 알 수 있기 때문에","correct":true},{"t":"신문에는 그때 있었던 모든 일이 다 적혀 있기 때문에","mis":"SO3-1-u2-X17"}],"mis":"SO3-1-u2-X17","explanation":["한 장으로","다?","X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L09_challenge#8','soc',3,1,'u2','L09','g3_1_soc_u2_L09_challenge','lesson_challenge','SO3-1-u2-C9',4,'essay','teacher','할머니나 할아버지께 옛 생활을 여쭤볼 질문 두 가지를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-1-u2-C9","difficulty":4,"kind":"essay","stem":"할머니나 할아버지께 옛 생활을 여쭤볼 질문 두 가지를 쓰세요.","answer_guide":{"answer":"예: 어릴 때는 어떤 놀이를 하며 노셨어요? / 학교에 다닐 때 점심은 어떻게 드셨어요?","scoring_points":["질문 두 가지를 썼는가","옛 생활을 묻는가","공손한 말로 썼는가"]},"explanation":["놀이","학교","공손하게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L09_challenge#9','soc',3,1,'u2','L09','g3_1_soc_u2_L09_challenge','lesson_challenge','SO3-1-u2-C9',4,'essay','teacher','옛 신문 같은 자료와 어른의 증언이 각각 무엇을 알려 주는지 쓰고, 둘을 함께 보면 좋은 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-1-u2-C9","difficulty":4,"kind":"essay","stem":"옛 신문 같은 자료와 어른의 증언이 각각 무엇을 알려 주는지 쓰고, 둘을 함께 보면 좋은 까닭을 쓰세요.","answer_guide":{"answer":"예: 옛 신문은 그때 있었던 일을 글과 사진으로 알려 주고, 증언은 겪은 분이 생생한 생활을 들려준다. 둘을 함께 보면 옛 생활을 더 자세하고 정확하게 알 수 있다.","scoring_points":["자료가 알려 주는 것을 썼는가","증언이 알려 주는 것을 썼는가","함께 보면 좋은 까닭을 썼는가"]},"explanation":["자료","증언","함께"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L09_challenge#10','soc',3,1,'u2','L09','g3_1_soc_u2_L09_challenge','lesson_challenge','SO3-1-u2-C9',4,'essay','teacher','할머니의 증언으로 알게 된 옛 생활과 오늘날 생활을 견주어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-1-u2-C9","difficulty":4,"kind":"essay","stem":"할머니의 증언으로 알게 된 옛 생활과 오늘날 생활을 견주어 쓰세요.","answer_guide":{"answer":"예: 옛날에는 우물에서 물을 길어 이고 왔지만 오늘날에는 수도꼭지만 틀면 물이 나온다. 옛날에는 냇가에서 손빨래를 했지만 오늘날에는 세탁기로 빨래를 한다.","scoring_points":["증언 속 옛 생활을 썼는가","오늘날 생활을 썼는가","둘을 견주었는가"]},"explanation":["우물 · 냇가","오늘은?","견주기"],"asset":{"type":"speech","turns":[{"who":"예린","text":"할머니, 어릴 때 물은 어디서 길어 오셨어요?"},{"who":"할머니","text":"마을 우물에서 두레박으로 길어 물동이에 이고 왔단다."},{"who":"할머니","text":"겨울엔 냇가에서 손을 호호 불며 빨래를 했지."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
