INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L10_basic#10','soc',3,1,'u2','L10','g3_1_soc_u2_L10_basic','lesson_basic','SO3-1-u2-C10',3,'mc','auto','「도윤이의 자료 분석 공책」에서 「알게 된 것 ②」에 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u2-X25','SO3-1-u2-X24']::text[],false,'{"seq":10,"concept":"SO3-1-u2-C10","difficulty":3,"kind":"mc","stem":"「도윤이의 자료 분석 공책」에서 「알게 된 것 ②」에 알맞은 것은 무엇일까요?","options":[{"t":"옛날 거리는 흙길이었고 낮은 초가집이 많았구나.","correct":true},{"t":"사람들이 한복을 입었다.","mis":"SO3-1-u2-X25"},{"t":"옛날에는 높은 건물이 많았구나.","mis":"SO3-1-u2-X25"},{"t":"자료는 안 봐도 되겠구나.","mis":"SO3-1-u2-X24"}],"explanation":["보이는 것 ②","흙길 · 초가집","알게 된 것"],"asset":{"type":"passage","lines":["보이는 것 ① 사람들이 한복을 입었다.","알게 된 것 ① 옛날에는 한복을 자주 입었구나.","보이는 것 ② 흙길과 낮은 초가집이 있다.","알게 된 것 ② (아직 쓰지 않음)"],"title":"도윤이의 자료 분석 공책"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L10_challenge#1','soc',3,1,'u2','L10','g3_1_soc_u2_L10_challenge','lesson_challenge','SO3-1-u2-C10',2,'mc','auto','자료를 자세히 살펴볼 때 바른 모습은 무엇일까요?',ARRAY['SO3-1-u2-X24','SO3-1-u2-X26']::text[],false,'{"seq":1,"concept":"SO3-1-u2-C10","difficulty":2,"kind":"mc","stem":"자료를 자세히 살펴볼 때 바른 모습은 무엇일까요?","options":[{"t":"작은 부분까지 돋보기로 보듯 천천히 본다","correct":true},{"t":"제목만 보고 덮는다","mis":"SO3-1-u2-X24"},{"t":"그림을 보지 않고 넘긴다","mis":"SO3-1-u2-X24"},{"t":"친구 것을 베낀다","mis":"SO3-1-u2-X26"}],"explanation":["돋보기처럼","천천히","자세히"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L10_challenge#2','soc',3,1,'u2','L10','g3_1_soc_u2_L10_challenge','lesson_challenge','SO3-1-u2-C10',2,'mc','auto','「보이는 것」과 「알게 된 것」을 바르게 짝지은 것은 무엇일까요?',ARRAY['SO3-1-u2-X25','SO3-1-u2-X06']::text[],false,'{"seq":2,"concept":"SO3-1-u2-C10","difficulty":2,"kind":"mc","stem":"「보이는 것」과 「알게 된 것」을 바르게 짝지은 것은 무엇일까요?","options":[{"t":"보이는 것: 흙길과 낮은 집 → 알게 된 것: 옛날 거리 모습이구나","correct":true},{"t":"보이는 것: 옛날 사람들은 행복했구나 → 알게 된 것: 한복","mis":"SO3-1-u2-X25"},{"t":"보이는 것: 내일 날씨 → 알게 된 것: 비가 오겠구나","mis":"SO3-1-u2-X06"},{"t":"보이는 것: 한복 → 알게 된 것: 사진 속 사람은 모두 형제구나","mis":"SO3-1-u2-X25"}],"explanation":["보이는 것은","눈에 보여요.","알게 된 것은 거기서"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L10_challenge#3','soc',3,1,'u2','L10','g3_1_soc_u2_L10_challenge','lesson_challenge','SO3-1-u2-C10',3,'mc','auto','「도윤이의 자료 분석 공책」에서 「보이는 것 ①」로 알게 된 것은 무엇일까요?',ARRAY['SO3-1-u2-X25']::text[],false,'{"seq":3,"concept":"SO3-1-u2-C10","difficulty":3,"kind":"mc","stem":"「도윤이의 자료 분석 공책」에서 「보이는 것 ①」로 알게 된 것은 무엇일까요?","options":[{"t":"옛날에는 한복을 자주 입었구나.","correct":true},{"t":"옛날 거리는 흙길이었구나.","mis":"SO3-1-u2-X25"},{"t":"옛날 사람들은 모두 키가 컸구나.","mis":"SO3-1-u2-X25"},{"t":"옛날에는 옷이 없었구나.","mis":"SO3-1-u2-X25"}],"explanation":["보이는 것 ①","한복","알게 된 것 ①"],"asset":{"type":"passage","lines":["보이는 것 ① 사람들이 한복을 입었다.","알게 된 것 ① 옛날에는 한복을 자주 입었구나.","보이는 것 ② 흙길과 낮은 초가집이 있다.","알게 된 것 ② (아직 쓰지 않음)"],"title":"도윤이의 자료 분석 공책"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L10_challenge#4','soc',3,1,'u2','L10','g3_1_soc_u2_L10_challenge','lesson_challenge','SO3-1-u2-C10',3,'error','auto','자료를 분석한 친구들의 말이에요. 잘못 행동한 친구는 누구일까요?',ARRAY['SO3-1-u2-X24','SO3-1-u2-X26']::text[],false,'{"seq":4,"concept":"SO3-1-u2-C10","difficulty":3,"kind":"error","stem":"자료를 분석한 친구들의 말이에요. 잘못 행동한 친구는 누구일까요?","options":[{"t":"민재 — 「자료는 안 보고 생각나는 대로 적었어.」","correct":true,"mis_target":"SO3-1-u2-X24"},{"t":"은솔 — 「자세히 살펴봤어.」","mis":"SO3-1-u2-X24"},{"t":"서준 — 「알게 된 것을 정리해 친구와 나눴어.」","mis":"SO3-1-u2-X26"}],"explanation":["자료는","살펴봐야","민재가 잘못"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L10_challenge#5','soc',3,1,'u2','L10','g3_1_soc_u2_L10_challenge','lesson_challenge','SO3-1-u2-C10',3,'mc','auto','옛 사진에서 「사람들이 지게를 지고 간다」를 보았어요. 알게 된 것으로 가장 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u2-X25','SO3-1-u2-X06','SO3-1-u2-X16']::text[],false,'{"seq":5,"concept":"SO3-1-u2-C10","difficulty":3,"kind":"mc","stem":"옛 사진에서 「사람들이 지게를 지고 간다」를 보았어요. 알게 된 것으로 가장 알맞은 것은 무엇일까요?","options":[{"t":"옛날에는 짐을 지게에 지고 날랐구나.","correct":true},{"t":"옛날에는 트럭이 아주 많았구나.","mis":"SO3-1-u2-X25"},{"t":"지게는 앞으로 생길 물건이구나.","mis":"SO3-1-u2-X06"},{"t":"사진만 보아서는 아무것도 알 수 없구나.","mis":"SO3-1-u2-X16"}],"explanation":["지게","짐","날랐구나"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L10_challenge#6','soc',3,1,'u2','L10','g3_1_soc_u2_L10_challenge','lesson_challenge','SO3-1-u2-C10',3,'mc','auto','하린이는 옛 신문을 혼자 읽고 바로 덮었어요. 더 해야 할 일로 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u2-X24','SO3-1-u2-X25']::text[],false,'{"seq":6,"concept":"SO3-1-u2-C10","difficulty":3,"kind":"mc","stem":"하린이는 옛 신문을 혼자 읽고 바로 덮었어요. 더 해야 할 일로 알맞은 것은 무엇일까요?","options":[{"t":"알게 된 것을 정리하고 친구와 나눈다","correct":true},{"t":"다른 자료도 모두 덮는다","mis":"SO3-1-u2-X24"},{"t":"아무것도 하지 않는다","mis":"SO3-1-u2-X24"},{"t":"자료에 없는 이야기를 지어 적는다","mis":"SO3-1-u2-X25"}],"explanation":["읽은 뒤","정리","나누기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L10_challenge#7','soc',3,1,'u2','L10','g3_1_soc_u2_L10_challenge','lesson_challenge','SO3-1-u2-C10',3,'ox','auto','자료에 나오지 않는 내용도 그럴듯하면 알게 된 것으로 적어도 돼요.',ARRAY['SO3-1-u2-X25']::text[],false,'{"seq":7,"concept":"SO3-1-u2-C10","difficulty":3,"kind":"ox","stem":"자료에 나오지 않는 내용도 그럴듯하면 알게 된 것으로 적어도 돼요.","answer":"X","reason_options":[{"t":"알게 된 것은 자료에서 보이는 것을 바탕으로 찾아야 하기 때문에","correct":true},{"t":"분석은 마음대로 짐작해 적는 일이기 때문에","mis":"SO3-1-u2-X25"}],"mis":"SO3-1-u2-X25","explanation":["자료에","있나요?","X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L10_challenge#8','soc',3,1,'u2','L10','g3_1_soc_u2_L10_challenge','lesson_challenge','SO3-1-u2-C10',4,'essay','teacher','자료를 분석하는 네 단계를 차례대로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-1-u2-C10","difficulty":4,"kind":"essay","stem":"자료를 분석하는 네 단계를 차례대로 쓰세요.","answer_guide":{"answer":"예: ① 살펴볼 자료를 고른다. ② 자료를 자세히 살펴본다. ③ 보이는 것에서 알 수 있는 것을 정리한다. ④ 알게 된 것을 친구와 나눈다.","scoring_points":["네 단계를 썼는가","차례가 바른가","단계마다 하는 일이 알맞은가"]},"explanation":["고르기","살피기 · 정리","나누기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L10_challenge#9','soc',3,1,'u2','L10','g3_1_soc_u2_L10_challenge','lesson_challenge','SO3-1-u2-C10',4,'essay','teacher','「도윤이의 자료 분석 공책」처럼 옛 사진 하나를 떠올려 「보이는 것」과 「알게 된 것」을 한 쌍 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-1-u2-C10","difficulty":4,"kind":"essay","stem":"「도윤이의 자료 분석 공책」처럼 옛 사진 하나를 떠올려 「보이는 것」과 「알게 된 것」을 한 쌍 쓰세요.","answer_guide":{"answer":"예: 보이는 것 — 아이들이 길에서 굴렁쇠를 굴리고 있다. / 알게 된 것 — 옛날 아이들은 길에서 굴렁쇠를 굴리며 놀았구나.","scoring_points":["보이는 것을 썼는가","알게 된 것을 썼는가","둘이 서로 이어지는가"]},"explanation":["보이는 것","그래서","알게 된 것"],"asset":{"type":"passage","lines":["보이는 것 ① 사람들이 한복을 입었다.","알게 된 것 ① 옛날에는 한복을 자주 입었구나.","보이는 것 ② 흙길과 낮은 초가집이 있다.","알게 된 것 ② (아직 쓰지 않음)"],"title":"도윤이의 자료 분석 공책"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L10_challenge#10','soc',3,1,'u2','L10','g3_1_soc_u2_L10_challenge','lesson_challenge','SO3-1-u2-C10',4,'essay','teacher','자료를 분석한 뒤 친구와 나누면 좋은 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-1-u2-C10","difficulty":4,"kind":"essay","stem":"자료를 분석한 뒤 친구와 나누면 좋은 까닭을 쓰세요.","answer_guide":{"answer":"예: 같은 자료라도 친구는 내가 못 본 것을 찾을 수 있어서, 서로 나누면 옛 생활을 더 많이 알 수 있다.","scoring_points":["친구가 다른 것을 찾는다고 썼는가","더 많이 알게 된다고 썼는가","내용이 알맞은가"]},"explanation":["같은 자료","다른 눈","더 많이"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
