INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L11_challenge#5','soc',3,1,'u2','L11','g3_1_soc_u2_L11_challenge','lesson_challenge','SO3-1-u2-C11',3,'error','auto','전시관을 꾸민 친구들의 말이에요. 잘못 말한 친구는 누구일까요?',ARRAY['SO3-1-u2-X27','SO3-1-u2-X28']::text[],false,'{"seq":5,"concept":"SO3-1-u2-C11","difficulty":3,"kind":"error","stem":"전시관을 꾸민 친구들의 말이에요. 잘못 말한 친구는 누구일까요?","options":[{"t":"서준 — 「주제는 상관없이 비싼 물건부터 모았어.」","correct":true,"mis_target":"SO3-1-u2-X27"},{"t":"예린 — 「물건마다 이름과 쓰임을 적었어.」","mis":"SO3-1-u2-X28"},{"t":"하린 — 「무엇을 왜 전시했는지 소개했어.」","mis":"SO3-1-u2-X28"}],"explanation":["비싼 것보다","주제에 맞는 것","서준이가 잘못"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L11_challenge#6','soc',3,1,'u2','L11','g3_1_soc_u2_L11_challenge','lesson_challenge','SO3-1-u2-C11',3,'mc','auto','가마솥 설명 카드로 가장 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u2-X28','SO3-1-u2-X19']::text[],false,'{"seq":6,"concept":"SO3-1-u2-C11","difficulty":3,"kind":"mc","stem":"가마솥 설명 카드로 가장 알맞은 것은 무엇일까요?","options":[{"t":"「가마솥: 아궁이에 걸고 밥을 짓던 큰 솥」","correct":true},{"t":"「가마솥: 아주 무거움」","mis":"SO3-1-u2-X28"},{"t":"「가마솥: 우리 모둠이 좋아함」","mis":"SO3-1-u2-X28"},{"t":"「가마솥: 곡식을 가는 도구」","mis":"SO3-1-u2-X19"}],"explanation":["이름","쓰임","밥 짓기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L11_challenge#7','soc',3,1,'u2','L11','g3_1_soc_u2_L11_challenge','lesson_challenge','SO3-1-u2-C11',3,'ox','auto','같은 물건이라도 설명 카드가 있으면 보는 사람이 옛 생활을 더 쉽게 알 수 있어요.',ARRAY['SO3-1-u2-X28']::text[],false,'{"seq":7,"concept":"SO3-1-u2-C11","difficulty":3,"kind":"ox","stem":"같은 물건이라도 설명 카드가 있으면 보는 사람이 옛 생활을 더 쉽게 알 수 있어요.","answer":"O","reason_options":[{"t":"이름과 쓰임을 알려 주어 물건이 어떻게 쓰였는지 알 수 있기 때문에","correct":true},{"t":"설명 카드는 장식이라 아무 도움이 안 되기 때문에","mis":"SO3-1-u2-X28"}],"mis":"SO3-1-u2-X28","explanation":["카드가","알려 줘요.","O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L11_challenge#8','soc',3,1,'u2','L11','g3_1_soc_u2_L11_challenge','lesson_challenge','SO3-1-u2-C11',4,'essay','teacher','「옛날 놀이」 전시관을 꾸민다면 모을 자료 두 가지와 그 가운데 하나의 설명 카드를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-1-u2-C11","difficulty":4,"kind":"essay","stem":"「옛날 놀이」 전시관을 꾸민다면 모을 자료 두 가지와 그 가운데 하나의 설명 카드를 쓰세요.","answer_guide":{"answer":"예: 자료 — 굴렁쇠, 팽이 / 설명 카드 — 「굴렁쇠: 쇠로 된 둥근 테를 막대로 굴리며 놀던 놀잇감」","scoring_points":["주제에 맞는 자료 두 가지를 썼는가","설명 카드에 이름을 썼는가","설명 카드에 쓰임을 썼는가"]},"explanation":["옛날 놀이","자료","이름과 쓰임"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L11_challenge#9','soc',3,1,'u2','L11','g3_1_soc_u2_L11_challenge','lesson_challenge','SO3-1-u2-C11',4,'essay','teacher','전시관 꾸미기의 네 단계를 차례대로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-1-u2-C11","difficulty":4,"kind":"essay","stem":"전시관 꾸미기의 네 단계를 차례대로 쓰세요.","answer_guide":{"answer":"예: ① 전시 주제를 정한다. ② 주제에 맞는 자료를 모은다. ③ 물건마다 이름과 쓰임을 적은 설명 카드를 쓴다. ④ 보기 좋게 놓고 친구에게 소개한다.","scoring_points":["네 단계를 썼는가","차례가 바른가","설명 카드를 넣었는가"]},"explanation":["주제","자료 · 카드","소개"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L11_challenge#10','soc',3,1,'u2','L11','g3_1_soc_u2_L11_challenge','lesson_challenge','SO3-1-u2-C11',4,'essay','teacher','우리 모둠 전시관을 친구에게 소개하는 말을 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-1-u2-C11","difficulty":4,"kind":"essay","stem":"우리 모둠 전시관을 친구에게 소개하는 말을 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 우리 모둠은 옛날 부엌을 주제로 전시했어요. 이것은 맷돌인데 옛날에 콩이나 곡식을 갈 때 썼어요.","scoring_points":["주제를 말했는가","물건의 이름과 쓰임을 말했는가","두 문장으로 썼는가"]},"explanation":["무엇을","왜","어떻게 썼는지"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
