INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L12_basic#6','soc',3,1,'u2','L12','g3_1_soc_u2_L12_basic','lesson_basic','SO3-1-u2-C12',2,'mc','auto','100년 뒤 사람들이 「오늘 우리 생활」을 알려면 무엇을 보면 될까요?',ARRAY['SO3-1-u2-X30']::text[],false,'{"seq":6,"concept":"SO3-1-u2-C12","difficulty":2,"kind":"mc","stem":"100년 뒤 사람들이 「오늘 우리 생활」을 알려면 무엇을 보면 될까요?","options":[{"t":"오늘의 사진 · 물건 · 기록","correct":true},{"t":"먼 우주","mis":"SO3-1-u2-X30"},{"t":"아무것도 없음","mis":"SO3-1-u2-X30"},{"t":"100년 뒤에 새로 만든 물건","mis":"SO3-1-u2-X30"}],"explanation":["지금 남기는 것","미래의","자료"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
