INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L12_basic#8','soc',3,1,'u2','L12','g3_1_soc_u2_L12_basic','lesson_basic','SO3-1-u2-C10',2,'mc','auto','소단원 정리: 자료를 살펴보는 바른 방법은 무엇일까요?',ARRAY['SO3-1-u2-X24','SO3-1-u2-X25','SO3-1-u2-X26']::text[],false,'{"seq":8,"concept":"SO3-1-u2-C10","difficulty":2,"kind":"mc","stem":"소단원 정리: 자료를 살펴보는 바른 방법은 무엇일까요?","options":[{"t":"자세히 살펴보고 알 수 있는 것을 정리한다","correct":true},{"t":"대충 보고 덮는다","mis":"SO3-1-u2-X24"},{"t":"자료에 없는 것을 지어낸다","mis":"SO3-1-u2-X25"},{"t":"혼자만 보고 숨긴다","mis":"SO3-1-u2-X26"}],"explanation":["자세히","정리","나누기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L12_basic#9','soc',3,1,'u2','L12','g3_1_soc_u2_L12_basic','lesson_basic','SO3-1-u2-C11',2,'mc','auto','소단원 정리: 알아낸 옛 생활을 친구들과 나누는 방법으로 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u2-X27','SO3-1-u2-X28','SO3-1-u2-X29']::text[],false,'{"seq":9,"concept":"SO3-1-u2-C11","difficulty":2,"kind":"mc","stem":"소단원 정리: 알아낸 옛 생활을 친구들과 나누는 방법으로 알맞은 것은 무엇일까요?","options":[{"t":"주제를 정해 전시관을 꾸미고 소개한다","correct":true},{"t":"주제 없이 물건을 마구 쌓아 둔다","mis":"SO3-1-u2-X27"},{"t":"설명 없이 물건만 보여 준다","mis":"SO3-1-u2-X28"},{"t":"알아낸 것을 아무에게도 말하지 않는다","mis":"SO3-1-u2-X29"}],"explanation":["주제","전시관","소개"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L12_basic#10','soc',3,1,'u2','L12','g3_1_soc_u2_L12_basic','lesson_basic','SO3-1-u2-C12',3,'mc','auto','「먼 훗날 상상 전시」를 보고 알 수 있는 것은 무엇일까요?',ARRAY['SO3-1-u2-X30','SO3-1-u2-X29','SO3-1-u2-X16']::text[],false,'{"seq":10,"concept":"SO3-1-u2-C12","difficulty":3,"kind":"mc","stem":"「먼 훗날 상상 전시」를 보고 알 수 있는 것은 무엇일까요?","options":[{"t":"오늘 우리가 쓰는 물건도 먼 훗날에는 그때를 알려 주는 자료가 돼요.","correct":true},{"t":"오늘 물건은 시간이 흘러도 과거가 되지 않아요.","mis":"SO3-1-u2-X30"},{"t":"박물관은 새 물건만 모아요.","mis":"SO3-1-u2-X29"},{"t":"전시를 보아도 그때 생활은 알 수 없어요.","mis":"SO3-1-u2-X16"}],"explanation":["일기장 · 태블릿","100년 뒤","과거의 자료"],"asset":{"type":"passage","lines":["100년 뒤 박물관 「옛날 어린이의 생활」","— 3학년 어린이의 일기장","— 학교에서 쓰던 태블릿 컴퓨터","— 어린이들이 즐겨 신던 운동화"],"title":"먼 훗날 상상 전시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L12_challenge#1','soc',3,1,'u2','L12','g3_1_soc_u2_L12_challenge','lesson_challenge','SO3-1-u2-C12',2,'mc','auto','소단원을 가장 잘 정리한 친구의 말은 무엇일까요?',ARRAY['SO3-1-u2-X16','SO3-1-u2-X23','SO3-1-u2-X17']::text[],false,'{"seq":1,"concept":"SO3-1-u2-C12","difficulty":2,"kind":"mc","stem":"소단원을 가장 잘 정리한 친구의 말은 무엇일까요?","options":[{"t":"「사진 · 물건 · 자료 · 증언으로 옛날을 알 수 있어.」","correct":true},{"t":"「옛날은 알 수 없어.」","mis":"SO3-1-u2-X16"},{"t":"「자료는 쓸모없어.」","mis":"SO3-1-u2-X23"},{"t":"「물건만 보면 돼.」","mis":"SO3-1-u2-X17"}],"explanation":["여러 가지","단서","모두"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L12_challenge#2','soc',3,1,'u2','L12','g3_1_soc_u2_L12_challenge','lesson_challenge','SO3-1-u2-C12',2,'mc','auto','오늘의 사진과 기록을 잘 남겨 두면 좋은 까닭은 무엇일까요?',ARRAY['SO3-1-u2-X30','SO3-1-u2-X18','SO3-1-u2-X29']::text[],false,'{"seq":2,"concept":"SO3-1-u2-C12","difficulty":2,"kind":"mc","stem":"오늘의 사진과 기록을 잘 남겨 두면 좋은 까닭은 무엇일까요?","options":[{"t":"먼 훗날 사람들이 지금 우리 생활을 알 수 있어서","correct":true},{"t":"오늘 기록은 금방 쓸모없어져서","mis":"SO3-1-u2-X30"},{"t":"사진은 미래 모습을 보여 줘서","mis":"SO3-1-u2-X18"},{"t":"박물관은 옛것을 버리는 곳이라서","mis":"SO3-1-u2-X29"}],"explanation":["남겨 두면","먼 훗날","자료"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L12_challenge#3','soc',3,1,'u2','L12','g3_1_soc_u2_L12_challenge','lesson_challenge','SO3-1-u2-C8',3,'mc','auto','옛날 부엌의 맷돌과 오늘날 부엌의 믹서기를 함께 보여 주는 전시를 꾸몄어요. 이 전시로 알 수 있는 것은 무엇일까요?',ARRAY['SO3-1-u2-X08','SO3-1-u2-X19','SO3-1-u2-X20']::text[],false,'{"seq":3,"concept":"SO3-1-u2-C8","difficulty":3,"kind":"mc","stem":"옛날 부엌의 맷돌과 오늘날 부엌의 믹서기를 함께 보여 주는 전시를 꾸몄어요. 이 전시로 알 수 있는 것은 무엇일까요?","options":[{"t":"같은 일을 하는 물건이 시간이 흐르며 달라졌다","correct":true},{"t":"옛날과 오늘의 부엌은 똑같다","mis":"SO3-1-u2-X08"},{"t":"맷돌은 옷을 펴던 물건이다","mis":"SO3-1-u2-X19"},{"t":"믹서기는 옛날 물건이다","mis":"SO3-1-u2-X20"}],"explanation":["맷돌","믹서기","달라졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L12_challenge#4','soc',3,1,'u2','L12','g3_1_soc_u2_L12_challenge','lesson_challenge','SO3-1-u2-C12',3,'mc','auto','「먼 훗날 상상 전시」에 우리 반이 더할 자료로 가장 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u2-X30']::text[],false,'{"seq":4,"concept":"SO3-1-u2-C12","difficulty":3,"kind":"mc","stem":"「먼 훗날 상상 전시」에 우리 반이 더할 자료로 가장 알맞은 것은 무엇일까요?","options":[{"t":"우리 반 어린이들이 함께 찍은 사진과 학급 신문","correct":true},{"t":"아무것도 남기지 않기","mis":"SO3-1-u2-X30"},{"t":"100년 뒤에 만들 새 장난감","mis":"SO3-1-u2-X30"},{"t":"빈 상자","mis":"SO3-1-u2-X30"}],"explanation":["오늘 우리","생활을 담은","사진 · 신문"],"asset":{"type":"passage","lines":["100년 뒤 박물관 「옛날 어린이의 생활」","— 3학년 어린이의 일기장","— 학교에서 쓰던 태블릿 컴퓨터","— 어린이들이 즐겨 신던 운동화"],"title":"먼 훗날 상상 전시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L12_challenge#5','soc',3,1,'u2','L12','g3_1_soc_u2_L12_challenge','lesson_challenge','SO3-1-u2-C12',3,'error','auto','옛 생활 모습을 알아보는 까닭을 친구들이 말했어요. 잘못 말한 친구는 누구일까요?',ARRAY['SO3-1-u2-X29','SO3-1-u2-X30']::text[],false,'{"seq":5,"concept":"SO3-1-u2-C12","difficulty":3,"kind":"error","stem":"옛 생활 모습을 알아보는 까닭을 친구들이 말했어요. 잘못 말한 친구는 누구일까요?","options":[{"t":"민재 — 「옛날 일은 지금 우리와 아무 상관이 없어.」","correct":true,"mis_target":"SO3-1-u2-X29"},{"t":"수아 — 「옛날을 알면 오늘이 더 잘 보여.」","mis":"SO3-1-u2-X29"},{"t":"은솔 — 「오늘도 언젠가 과거가 돼.」","mis":"SO3-1-u2-X30"}],"explanation":["옛날을 알면","오늘이","민재가 잘못"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L12_challenge#6','soc',3,1,'u2','L12','g3_1_soc_u2_L12_challenge','lesson_challenge','SO3-1-u2-C9',3,'mc','auto','증조할머니께서 들려주신 옛 혼례 이야기를 오래 남기려면 어떻게 하면 좋을까요?',ARRAY['SO3-1-u2-X30','SO3-1-u2-X23','SO3-1-u2-X25']::text[],false,'{"seq":6,"concept":"SO3-1-u2-C9","difficulty":3,"kind":"mc","stem":"증조할머니께서 들려주신 옛 혼례 이야기를 오래 남기려면 어떻게 하면 좋을까요?","options":[{"t":"들은 내용을 적고 사진과 함께 기록해 둔다","correct":true},{"t":"듣고 바로 잊어버린다","mis":"SO3-1-u2-X30"},{"t":"이야기는 쓸모없어 남기지 않는다","mis":"SO3-1-u2-X23"},{"t":"내 생각을 섞어 지어낸다","mis":"SO3-1-u2-X25"}],"explanation":["들은 것을","적고","기록"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L12_challenge#7','soc',3,1,'u2','L12','g3_1_soc_u2_L12_challenge','lesson_challenge','SO3-1-u2-C12',3,'ox','auto','옛것을 알면 오늘 우리가 누리는 것을 더 소중히 여기게 돼요.',ARRAY['SO3-1-u2-X29']::text[],false,'{"seq":7,"concept":"SO3-1-u2-C12","difficulty":3,"kind":"ox","stem":"옛것을 알면 오늘 우리가 누리는 것을 더 소중히 여기게 돼요.","answer":"O","reason_options":[{"t":"옛날부터 이어져 온 생활을 알면 오늘의 모습이 어떻게 생겼는지 이해하게 되기 때문에","correct":true},{"t":"옛것은 오늘과 아무 관계가 없기 때문에","mis":"SO3-1-u2-X29"}],"mis":"SO3-1-u2-X29","explanation":["옛것","오늘","소중히"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L12_challenge#8','soc',3,1,'u2','L12','g3_1_soc_u2_L12_challenge','lesson_challenge','SO3-1-u2-C12',4,'essay','teacher','100년 뒤 박물관에 「오늘 우리 생활」을 전할 물건 두 가지를 고르고 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-1-u2-C12","difficulty":4,"kind":"essay","stem":"100년 뒤 박물관에 「오늘 우리 생활」을 전할 물건 두 가지를 고르고 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 내 일기장 — 오늘 어린이가 하루를 어떻게 보냈는지 알려 준다. / 학교에서 쓰는 태블릿 컴퓨터 — 오늘날 어린이가 어떻게 공부했는지 알려 준다.","scoring_points":["물건 두 가지를 골랐는가","오늘의 물건인가","알려 줄 생활을 까닭으로 썼는가"]},"explanation":["오늘의 물건","100년 뒤","무엇을 알려 줄까?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L12_challenge#9','soc',3,1,'u2','L12','g3_1_soc_u2_L12_challenge','lesson_challenge','SO3-1-u2-C12',4,'essay','teacher','「주변에서 만나는 과거의 모습」에서 옛 생활을 알아보는 방법을 세 가지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-1-u2-C12","difficulty":4,"kind":"essay","stem":"「주변에서 만나는 과거의 모습」에서 옛 생활을 알아보는 방법을 세 가지 쓰세요.","answer_guide":{"answer":"예: 옛 사진과 옛 건축물을 살펴본다. 오래된 물건의 쓰임을 알아본다. 옛 자료를 읽고 그때를 겪은 어른의 증언을 듣는다.","scoring_points":["방법 세 가지를 썼는가","방법이 바른가","여러 단서를 들었는가"]},"explanation":["사진 · 건축물","물건","자료 · 증언"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L12_challenge#10','soc',3,1,'u2','L12','g3_1_soc_u2_L12_challenge','lesson_challenge','SO3-1-u2-C12',4,'essay','teacher','우리가 옛 생활 모습을 알아보아야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-1-u2-C12","difficulty":4,"kind":"essay","stem":"우리가 옛 생활 모습을 알아보아야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 옛 생활을 알면 우리가 살아온 과거를 이해할 수 있고, 오늘의 생활이 어떻게 달라져 왔는지 알게 되어 오늘을 더 잘 이해하고 소중히 여길 수 있다.","scoring_points":["과거를 이해한다고 썼는가","오늘과 이었는가","까닭이 알맞은가"]},"explanation":["과거","오늘","소중히"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L13_basic#1','soc',3,1,'u2','L13','g3_1_soc_u2_L13_basic','lesson_basic','SO3-1-u2-C13',1,'mc','auto','우리 지역의 옛 모습을 알려 주는 자료가 아닌 것은 무엇일까요?',ARRAY['SO3-1-u2-X32']::text[],false,'{"seq":1,"concept":"SO3-1-u2-C13","difficulty":1,"kind":"mc","stem":"우리 지역의 옛 모습을 알려 주는 자료가 아닌 것은 무엇일까요?","options":[{"t":"내일의 일기 예보","correct":true},{"t":"옛 사진","mis":"SO3-1-u2-X32"},{"t":"옛 신문","mis":"SO3-1-u2-X32"},{"t":"어른의 증언","mis":"SO3-1-u2-X32"}],"explanation":["옛 모습을","알려 주나요?","내일은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
