INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L13_basic#6','soc',3,1,'u2','L13','g3_1_soc_u2_L13_basic','lesson_basic','SO3-1-u2-C13',2,'mc','auto','할아버지께 「옛날 우리 동네는 어땠어요?」 하고 여쭤 듣는 것은 무엇일까요?',ARRAY['SO3-1-u2-X32','SO3-1-u2-X22']::text[],false,'{"seq":6,"concept":"SO3-1-u2-C13","difficulty":2,"kind":"mc","stem":"할아버지께 「옛날 우리 동네는 어땠어요?」 하고 여쭤 듣는 것은 무엇일까요?","options":[{"t":"증언","correct":true},{"t":"옛 지도","mis":"SO3-1-u2-X32"},{"t":"영상 자료","mis":"SO3-1-u2-X32"},{"t":"그림 그리기","mis":"SO3-1-u2-X22"}],"explanation":["겪은 분께","여쭤 들어요.","증언"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L13_basic#7','soc',3,1,'u2','L13','g3_1_soc_u2_L13_basic','lesson_basic','SO3-1-u2-C13',2,'match','auto','자료와 알려 주는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO3-1-u2-C13","difficulty":2,"kind":"match","stem":"자료와 알려 주는 것을 알맞게 이으세요.","pairs":[{"l":"옛 사진 · 지도","r":"옛 거리와 건물 모습"},{"l":"옛 신문 · 기록","r":"그때 지역에 있었던 일과 소식"},{"l":"영상 자료","r":"움직임과 소리로 본 옛 모습"}],"mis":"SO3-1-u2-X32","explanation":["사진은 모습","신문은 소식","영상은 움직임"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L13_basic#8','soc',3,1,'u2','L13','g3_1_soc_u2_L13_basic','lesson_basic','SO3-1-u2-C13',2,'mc','auto','「버들마을 옛 모습 자료」에서 옛날 사람들이 냇물을 건넌 방법을 알려 주는 자료끼리 모은 것은 무엇일까요?',ARRAY['SO3-1-u2-X32','SO3-1-u2-X16']::text[],false,'{"seq":8,"concept":"SO3-1-u2-C13","difficulty":2,"kind":"mc","stem":"「버들마을 옛 모습 자료」에서 옛날 사람들이 냇물을 건넌 방법을 알려 주는 자료끼리 모은 것은 무엇일까요?","options":[{"t":"① · ④","correct":true},{"t":"② 하나","mis":"SO3-1-u2-X32"},{"t":"② · ③","mis":"SO3-1-u2-X32"},{"t":"하나도 없다","mis":"SO3-1-u2-X16"}],"explanation":["나룻배 사진","할아버지 증언","① · ④"],"asset":{"type":"passage","lines":["① 옛 사진 — 나루터에 나룻배가 줄지어 있다.","② 옛 지도 — 마을 가운데로 냇물이 흐르고 논이 넓다.","③ 옛 신문 — 「버들마을에 첫 다리 놓여」","④ 할아버지 증언 — 「다리가 생기기 전엔 배를 타고 건넜지.」"],"title":"버들마을 옛 모습 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L13_basic#9','soc',3,1,'u2','L13','g3_1_soc_u2_L13_basic','lesson_basic','SO3-1-u2-C13',2,'ox','auto','우리 지역의 옛 모습은 한 가지 자료만 보아도 모두 알 수 있어요.',ARRAY['SO3-1-u2-X17']::text[],false,'{"seq":9,"concept":"SO3-1-u2-C13","difficulty":2,"kind":"ox","stem":"우리 지역의 옛 모습은 한 가지 자료만 보아도 모두 알 수 있어요.","answer":"X","reason_options":[{"t":"사진 · 신문 · 옛이야기 · 증언 · 영상이 알려 주는 것이 서로 달라 함께 보아야 하기 때문에","correct":true},{"t":"자료는 모두 같은 것을 알려 주기 때문에","mis":"SO3-1-u2-X17"}],"mis":"SO3-1-u2-X17","explanation":["자료마다","달라요.","X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
