INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L13_challenge#1','soc',3,1,'u2','L13','g3_1_soc_u2_L13_challenge','lesson_challenge','SO3-1-u2-C13',2,'mc','auto','우리 동네 옛 사진에 초가집이 보여요. 알 수 있는 것은 무엇일까요?',ARRAY['SO3-1-u2-X06','SO3-1-u2-X31','SO3-1-u2-X16']::text[],false,'{"seq":1,"concept":"SO3-1-u2-C13","difficulty":2,"kind":"mc","stem":"우리 동네 옛 사진에 초가집이 보여요. 알 수 있는 것은 무엇일까요?","options":[{"t":"옛날 우리 동네에 초가집이 있었다","correct":true},{"t":"앞으로 초가집이 생긴다","mis":"SO3-1-u2-X06"},{"t":"우리 동네는 옛날과 똑같다","mis":"SO3-1-u2-X31"},{"t":"초가집 사진은 상상이다","mis":"SO3-1-u2-X16"}],"explanation":["사진에","보이는 것","초가집"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
