INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L13_challenge#6','soc',3,1,'u2','L13','g3_1_soc_u2_L13_challenge','lesson_challenge','SO3-1-u2-C13',3,'mc','auto','옛 모습 영상 자료가 사진보다 좋은 점은 무엇일까요?',ARRAY['SO3-1-u2-X32','SO3-1-u2-X06','SO3-1-u2-X17']::text[],false,'{"seq":6,"concept":"SO3-1-u2-C13","difficulty":3,"kind":"mc","stem":"옛 모습 영상 자료가 사진보다 좋은 점은 무엇일까요?","options":[{"t":"움직임과 소리로 그때를 더 생생하게 느낄 수 있다","correct":true},{"t":"글로 소식을 자세히 적어 준다","mis":"SO3-1-u2-X32"},{"t":"앞으로의 모습을 보여 준다","mis":"SO3-1-u2-X06"},{"t":"영상 하나면 다른 자료는 필요 없다","mis":"SO3-1-u2-X17"}],"explanation":["움직임","소리","생생하게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L13_challenge#7','soc',3,1,'u2','L13','g3_1_soc_u2_L13_challenge','lesson_challenge','SO3-1-u2-C13',3,'ox','auto','지역에 오래 사신 어른의 증언도 지역의 옛 모습을 알려 주는 자료예요.',ARRAY['SO3-1-u2-X22']::text[],false,'{"seq":7,"concept":"SO3-1-u2-C13","difficulty":3,"kind":"ox","stem":"지역에 오래 사신 어른의 증언도 지역의 옛 모습을 알려 주는 자료예요.","answer":"O","reason_options":[{"t":"그 지역의 옛 모습을 직접 겪어 잘 알고 계시기 때문에","correct":true},{"t":"어른의 기억은 지역의 옛 모습과 상관이 없기 때문에","mis":"SO3-1-u2-X22"}],"mis":"SO3-1-u2-X22","explanation":["오래 사신 분","직접 겪었어요.","O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L13_challenge#8','soc',3,1,'u2','L13','g3_1_soc_u2_L13_challenge','lesson_challenge','SO3-1-u2-C13',4,'essay','teacher','우리 지역의 옛 모습을 알 수 있는 자료 세 가지를 쓰고, 각각 무엇을 알려 주는지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-1-u2-C13","difficulty":4,"kind":"essay","stem":"우리 지역의 옛 모습을 알 수 있는 자료 세 가지를 쓰고, 각각 무엇을 알려 주는지 쓰세요.","answer_guide":{"answer":"예: 옛 사진 — 옛 거리와 건물 모습 / 옛 신문 — 그때 지역에 있었던 일과 소식 / 영상 자료 — 움직임과 소리로 본 옛 모습","scoring_points":["자료 세 가지를 썼는가","각각 알려 주는 것을 썼는가","짝이 알맞은가"]},"explanation":["사진","신문","영상"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L13_challenge#9','soc',3,1,'u2','L13','g3_1_soc_u2_L13_challenge','lesson_challenge','SO3-1-u2-C13',4,'essay','teacher','「버들마을 옛 모습 자료」로 알 수 있는 옛날과 오늘의 달라진 점을 쓰고, 어떤 자료를 보고 알았는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-1-u2-C13","difficulty":4,"kind":"essay","stem":"「버들마을 옛 모습 자료」로 알 수 있는 옛날과 오늘의 달라진 점을 쓰고, 어떤 자료를 보고 알았는지 쓰세요.","answer_guide":{"answer":"예: 옛날에는 나룻배를 타고 냇물을 건넜지만 다리가 놓인 뒤로는 다리로 건넌다. ①의 옛 사진, ③의 옛 신문, ④의 할아버지 증언을 보고 알았다.","scoring_points":["달라진 점을 썼는가","근거 자료를 밝혔는가","여러 자료를 함께 썼는가"]},"explanation":["배","다리","어느 자료?"],"asset":{"type":"passage","lines":["① 옛 사진 — 나루터에 나룻배가 줄지어 있다.","② 옛 지도 — 마을 가운데로 냇물이 흐르고 논이 넓다.","③ 옛 신문 — 「버들마을에 첫 다리 놓여」","④ 할아버지 증언 — 「다리가 생기기 전엔 배를 타고 건넜지.」"],"title":"버들마을 옛 모습 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L13_challenge#10','soc',3,1,'u2','L13','g3_1_soc_u2_L13_challenge','lesson_challenge','SO3-1-u2-C13',4,'essay','teacher','우리 지역의 옛 모습을 알아보려고 오래 사신 어른께 여쭤볼 질문 두 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-1-u2-C13","difficulty":4,"kind":"essay","stem":"우리 지역의 옛 모습을 알아보려고 오래 사신 어른께 여쭤볼 질문 두 가지를 쓰세요.","answer_guide":{"answer":"예: 옛날 우리 동네에는 어떤 가게가 있었어요? / 어릴 때 동네 아이들은 어디에서 놀았어요?","scoring_points":["질문 두 가지를 썼는가","지역의 옛 모습을 묻는가","공손한 말로 썼는가"]},"explanation":["동네의","옛 모습","공손하게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L14_basic#1','soc',3,1,'u2','L14','g3_1_soc_u2_L14_basic','lesson_basic','SO3-1-u2-C14',1,'mc','auto','옛이야기는 어떻게 전해 내려왔을까요?',ARRAY['SO3-1-u2-X23']::text[],false,'{"seq":1,"concept":"SO3-1-u2-C14","difficulty":1,"kind":"mc","stem":"옛이야기는 어떻게 전해 내려왔을까요?","options":[{"t":"사람들의 입에서 입으로 말로 전해 왔다","correct":true},{"t":"어제 처음 만들어졌다","mis":"SO3-1-u2-X23"},{"t":"휴대 전화로만 전해졌다","mis":"SO3-1-u2-X23"},{"t":"아무도 전하지 않았다","mis":"SO3-1-u2-X23"}],"explanation":["오래전부터","말로","입에서 입으로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
