INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L14_basic#4','soc',3,1,'u2','L14','g3_1_soc_u2_L14_basic','lesson_basic','SO3-1-u2-C14',1,'ox','auto','마을에 오래 사신 어른께 여쭤보면 옛이야기를 들을 수 있어요.',ARRAY['SO3-1-u2-X23']::text[],false,'{"seq":4,"concept":"SO3-1-u2-C14","difficulty":1,"kind":"ox","stem":"마을에 오래 사신 어른께 여쭤보면 옛이야기를 들을 수 있어요.","answer":"O","reason_options":[{"t":"오래 사신 어른은 마을에 전해 오는 이야기를 잘 알고 계시기 때문에","correct":true},{"t":"옛이야기는 어른도 모르는 비밀이기 때문에","mis":"SO3-1-u2-X23"}],"mis":"SO3-1-u2-X23","explanation":["오래 사신 분","잘 아세요.","O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L14_basic#5','soc',3,1,'u2','L14','g3_1_soc_u2_L14_basic','lesson_basic','SO3-1-u2-C14',2,'mc','auto','옛이야기를 찾는 방법이 아닌 것은 무엇일까요?',ARRAY['SO3-1-u2-X23']::text[],false,'{"seq":5,"concept":"SO3-1-u2-C14","difficulty":2,"kind":"mc","stem":"옛이야기를 찾는 방법이 아닌 것은 무엇일까요?","options":[{"t":"내일 날씨 보기","correct":true},{"t":"어른께 듣기","mis":"SO3-1-u2-X23"},{"t":"책에서 찾기","mis":"SO3-1-u2-X23"},{"t":"지역 누리집 보기","mis":"SO3-1-u2-X23"}],"explanation":["옛이야기와","상관없는 것","날씨"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L14_basic#6','soc',3,1,'u2','L14','g3_1_soc_u2_L14_basic','lesson_basic','SO3-1-u2-C14',2,'mc','auto','「우리 고장 땅 이름」에서 「샘골」이라는 이름으로 알 수 있는 옛 모습은 무엇일까요?',ARRAY['SO3-1-u2-X33']::text[],false,'{"seq":6,"concept":"SO3-1-u2-C14","difficulty":2,"kind":"mc","stem":"「우리 고장 땅 이름」에서 「샘골」이라는 이름으로 알 수 있는 옛 모습은 무엇일까요?","options":[{"t":"맑은 샘이 솟던 마을이었다","correct":true},{"t":"옹기를 굽던 마을이었다","mis":"SO3-1-u2-X33"},{"t":"배를 타던 나루가 있었다","mis":"SO3-1-u2-X33"},{"t":"아무 뜻 없이 붙은 이름이다","mis":"SO3-1-u2-X33"}],"explanation":["샘","골","샘이 솟던 마을"],"asset":{"type":"passage","lines":["샘골 — 맑은 샘이 솟던 마을","가마골 — 옹기를 굽던 가마가 있던 마을","나루터마을 — 배를 타고 내리던 나루가 있던 마을","숯골 — ?"],"title":"우리 고장 땅 이름"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L14_basic#7','soc',3,1,'u2','L14','g3_1_soc_u2_L14_basic','lesson_basic','SO3-1-u2-C14',2,'mc','auto','「우리 고장 땅 이름」에서 「숯골」에 들어갈 뜻으로 가장 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u2-X33']::text[],false,'{"seq":7,"concept":"SO3-1-u2-C14","difficulty":2,"kind":"mc","stem":"「우리 고장 땅 이름」에서 「숯골」에 들어갈 뜻으로 가장 알맞은 것은 무엇일까요?","options":[{"t":"숯을 굽던 마을","correct":true},{"t":"샘이 솟던 마을","mis":"SO3-1-u2-X33"},{"t":"배를 타고 내리던 마을","mis":"SO3-1-u2-X33"},{"t":"아무 뜻도 없는 마을","mis":"SO3-1-u2-X33"}],"explanation":["이름 속","숯","숯을 굽던 마을"],"asset":{"type":"passage","lines":["샘골 — 맑은 샘이 솟던 마을","가마골 — 옹기를 굽던 가마가 있던 마을","나루터마을 — 배를 타고 내리던 나루가 있던 마을","숯골 — ?"],"title":"우리 고장 땅 이름"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L14_basic#8','soc',3,1,'u2','L14','g3_1_soc_u2_L14_basic','lesson_basic','SO3-1-u2-C14',2,'mc','auto','「마을 어르신이 들려주신 이야기」에서 마을 이름이 느티골이 된 까닭은 무엇일까요?',ARRAY['SO3-1-u2-X25','SO3-1-u2-X33','SO3-1-u2-X06']::text[],false,'{"seq":8,"concept":"SO3-1-u2-C14","difficulty":2,"kind":"mc","stem":"「마을 어르신이 들려주신 이야기」에서 마을 이름이 느티골이 된 까닭은 무엇일까요?","options":[{"t":"마을 어귀에 큰 느티나무가 있었기 때문에","correct":true},{"t":"느티나무를 모두 베어 냈기 때문에","mis":"SO3-1-u2-X25"},{"t":"아무 까닭 없이 지은 이름이라서","mis":"SO3-1-u2-X33"},{"t":"앞으로 느티나무를 심을 것이라서","mis":"SO3-1-u2-X06"}],"explanation":["어귀에","큰 나무","느티골"],"asset":{"type":"passage","lines":["옛날 마을 어귀에 큰 느티나무가 있었대요.","가뭄이 들면 마을 사람들이 나무 아래 모여","함께 물을 나르고 비가 오기를 빌었대요.","그래서 마을 이름이 느티골이 되었대요."],"title":"마을 어르신이 들려주신 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L14_basic#9','soc',3,1,'u2','L14','g3_1_soc_u2_L14_basic','lesson_basic','SO3-1-u2-C14',2,'ox','auto','옛이야기는 지어낸 이야기라서 옛 생활을 아는 데 쓸모가 없어요.',ARRAY['SO3-1-u2-X23']::text[],false,'{"seq":9,"concept":"SO3-1-u2-C14","difficulty":2,"kind":"ox","stem":"옛이야기는 지어낸 이야기라서 옛 생활을 아는 데 쓸모가 없어요.","answer":"X","reason_options":[{"t":"옛이야기 속에 그때 사람들의 생활 모습과 바람이 담겨 있기 때문에","correct":true},{"t":"옛이야기에는 아무것도 담겨 있지 않기 때문에","mis":"SO3-1-u2-X23"}],"mis":"SO3-1-u2-X23","explanation":["이야기 속","생활과 바람","X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L14_basic#10','soc',3,1,'u2','L14','g3_1_soc_u2_L14_basic','lesson_basic','SO3-1-u2-C14',3,'mc','auto','「마을 어르신이 들려주신 이야기」로 알 수 있는 옛 느티골 사람들의 생활은 무엇일까요?',ARRAY['SO3-1-u2-X25','SO3-1-u2-X23']::text[],false,'{"seq":10,"concept":"SO3-1-u2-C14","difficulty":3,"kind":"mc","stem":"「마을 어르신이 들려주신 이야기」로 알 수 있는 옛 느티골 사람들의 생활은 무엇일까요?","options":[{"t":"가뭄이 들면 함께 모여 물을 나르며 서로 도왔다","correct":true},{"t":"느티골 사람들은 서로 돕지 않았다","mis":"SO3-1-u2-X25"},{"t":"느티골에는 비가 너무 많이 왔다","mis":"SO3-1-u2-X25"},{"t":"이야기는 거짓이라 생활을 알 수 없다","mis":"SO3-1-u2-X23"}],"explanation":["가뭄","함께 모여","서로 도왔어요."],"asset":{"type":"passage","lines":["옛날 마을 어귀에 큰 느티나무가 있었대요.","가뭄이 들면 마을 사람들이 나무 아래 모여","함께 물을 나르고 비가 오기를 빌었대요.","그래서 마을 이름이 느티골이 되었대요."],"title":"마을 어르신이 들려주신 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
