INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L14_challenge#5','soc',3,1,'u2','L14','g3_1_soc_u2_L14_challenge','lesson_challenge','SO3-1-u2-C14',3,'error','auto','옛이야기에 대해 친구들이 말했어요. 잘못 말한 친구는 누구일까요?',ARRAY['SO3-1-u2-X23','SO3-1-u2-X33']::text[],false,'{"seq":5,"concept":"SO3-1-u2-C14","difficulty":3,"kind":"error","stem":"옛이야기에 대해 친구들이 말했어요. 잘못 말한 친구는 누구일까요?","options":[{"t":"은솔 — 「옛이야기는 거짓이라 쓸모없어.」","correct":true,"mis_target":"SO3-1-u2-X23"},{"t":"서준 — 「옛이야기에 옛 생활이 담겨 있어.」","mis":"SO3-1-u2-X23"},{"t":"예린 — 「땅 이름에도 옛 모습이 담겨 있어.」","mis":"SO3-1-u2-X33"}],"explanation":["옛이야기는","도움이 돼요.","은솔이가 잘못"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L14_challenge#6','soc',3,1,'u2','L14','g3_1_soc_u2_L14_challenge','lesson_challenge','SO3-1-u2-C14',3,'mc','auto','옛이야기를 책이나 지역 누리집에서도 찾을 수 있는 까닭은 무엇일까요?',ARRAY['SO3-1-u2-X23','SO3-1-u2-X06','SO3-1-u2-X16']::text[],false,'{"seq":6,"concept":"SO3-1-u2-C14","difficulty":3,"kind":"mc","stem":"옛이야기를 책이나 지역 누리집에서도 찾을 수 있는 까닭은 무엇일까요?","options":[{"t":"말로 전해 오던 이야기를 사람들이 글로 적어 남겨 두었기 때문에","correct":true},{"t":"옛이야기는 처음부터 누리집에서 만들어졌기 때문에","mis":"SO3-1-u2-X23"},{"t":"책에는 미래 이야기만 있기 때문에","mis":"SO3-1-u2-X06"},{"t":"옛이야기는 어디에도 남아 있지 않기 때문에","mis":"SO3-1-u2-X16"}],"explanation":["말로 전하던 것","글로","남겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L14_challenge#7','soc',3,1,'u2','L14','g3_1_soc_u2_L14_challenge','lesson_challenge','SO3-1-u2-C14',3,'ox','auto','땅 이름은 아무렇게나 붙인 것이라 옛 모습과 관계가 없어요.',ARRAY['SO3-1-u2-X33']::text[],false,'{"seq":7,"concept":"SO3-1-u2-C14","difficulty":3,"kind":"ox","stem":"땅 이름은 아무렇게나 붙인 것이라 옛 모습과 관계가 없어요.","answer":"X","reason_options":[{"t":"그곳의 옛 모습이나 있었던 일을 따서 이름을 붙인 경우가 많기 때문에","correct":true},{"t":"땅 이름은 모두 요즘에 새로 지은 것이기 때문에","mis":"SO3-1-u2-X33"}],"mis":"SO3-1-u2-X33","explanation":["샘골 · 가마골","이름 속","X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L14_challenge#8','soc',3,1,'u2','L14','g3_1_soc_u2_L14_challenge','lesson_challenge','SO3-1-u2-C14',4,'essay','teacher','「우리 고장 땅 이름」 가운데 두 가지를 골라 이름에 담긴 옛 모습을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-1-u2-C14","difficulty":4,"kind":"essay","stem":"「우리 고장 땅 이름」 가운데 두 가지를 골라 이름에 담긴 옛 모습을 쓰세요.","answer_guide":{"answer":"예: 샘골 — 옛날에 맑은 샘이 솟아 물을 길어 먹던 마을이다. / 나루터마을 — 옛날에 배를 타고 내리던 나루가 있던 마을이다.","scoring_points":["이름 두 가지를 골랐는가","이름에 담긴 옛 모습을 썼는가","이름 속 단서와 이어지는가"]},"explanation":["이름 속","단서","옛 모습"],"asset":{"type":"passage","lines":["샘골 — 맑은 샘이 솟던 마을","가마골 — 옹기를 굽던 가마가 있던 마을","나루터마을 — 배를 타고 내리던 나루가 있던 마을","숯골 — ?"],"title":"우리 고장 땅 이름"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L14_challenge#9','soc',3,1,'u2','L14','g3_1_soc_u2_L14_challenge','lesson_challenge','SO3-1-u2-C14',4,'essay','teacher','「마을 어르신이 들려주신 이야기」로 알 수 있는 옛 느티골 사람들의 생활과 생각을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-1-u2-C14","difficulty":4,"kind":"essay","stem":"「마을 어르신이 들려주신 이야기」로 알 수 있는 옛 느티골 사람들의 생활과 생각을 쓰세요.","answer_guide":{"answer":"예: 가뭄이 들면 마을 사람들이 느티나무 아래 모여 함께 물을 나르며 서로 도왔다. 비가 오기를 바라는 마음으로 함께 빌었다.","scoring_points":["생활을 썼는가","생각이나 바람을 썼는가","이야기에 있는 내용인가"]},"explanation":["함께 모여","물을 날라요.","비를 빌어요."],"asset":{"type":"passage","lines":["옛날 마을 어귀에 큰 느티나무가 있었대요.","가뭄이 들면 마을 사람들이 나무 아래 모여","함께 물을 나르고 비가 오기를 빌었대요.","그래서 마을 이름이 느티골이 되었대요."],"title":"마을 어르신이 들려주신 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L14_challenge#10','soc',3,1,'u2','L14','g3_1_soc_u2_L14_challenge','lesson_challenge','SO3-1-u2-C14',4,'essay','teacher','우리 지역의 옛이야기를 찾는 방법 두 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-1-u2-C14","difficulty":4,"kind":"essay","stem":"우리 지역의 옛이야기를 찾는 방법 두 가지를 쓰세요.","answer_guide":{"answer":"예: 마을에 오래 사신 어른께 여쭤본다. 도서관에서 우리 지역 옛이야기 책을 찾아본다.","scoring_points":["방법 두 가지를 썼는가","방법이 알맞은가","옛이야기와 이어지는가"]},"explanation":["어른께","책","누리집"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L15_basic#1','soc',3,1,'u2','L15','g3_1_soc_u2_L15_basic','lesson_basic','SO3-1-u2-C15',1,'mc','auto','옛 거리와 건물 모습을 눈으로 그대로 볼 수 있게 해 주는 자료는 무엇일까요?',ARRAY['SO3-1-u2-X32']::text[],false,'{"seq":1,"concept":"SO3-1-u2-C15","difficulty":1,"kind":"mc","stem":"옛 거리와 건물 모습을 눈으로 그대로 볼 수 있게 해 주는 자료는 무엇일까요?","options":[{"t":"사진 자료","correct":true},{"t":"신문 자료","mis":"SO3-1-u2-X32"},{"t":"증언","mis":"SO3-1-u2-X32"},{"t":"옛이야기","mis":"SO3-1-u2-X32"}],"explanation":["눈으로","그대로","사진"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L15_basic#2','soc',3,1,'u2','L15','g3_1_soc_u2_L15_basic','lesson_basic','SO3-1-u2-C15',1,'mc','auto','그때 지역에 있었던 일과 소식을 글로 알려 주는 자료는 무엇일까요?',ARRAY['SO3-1-u2-X32']::text[],false,'{"seq":2,"concept":"SO3-1-u2-C15","difficulty":1,"kind":"mc","stem":"그때 지역에 있었던 일과 소식을 글로 알려 주는 자료는 무엇일까요?","options":[{"t":"신문 자료","correct":true},{"t":"사진 자료","mis":"SO3-1-u2-X32"},{"t":"영상 자료","mis":"SO3-1-u2-X32"},{"t":"땅 이름","mis":"SO3-1-u2-X32"}],"explanation":["글로","소식","신문"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L15_basic#3','soc',3,1,'u2','L15','g3_1_soc_u2_L15_basic','lesson_basic','SO3-1-u2-C15',1,'mc','auto','지역의 옛 모습을 더 정확히 알려면 어떻게 하면 좋을까요?',ARRAY['SO3-1-u2-X17','SO3-1-u2-X16','SO3-1-u2-X24']::text[],false,'{"seq":3,"concept":"SO3-1-u2-C15","difficulty":1,"kind":"mc","stem":"지역의 옛 모습을 더 정확히 알려면 어떻게 하면 좋을까요?","options":[{"t":"여러 자료를 함께 보고 견준다","correct":true},{"t":"한 가지만 본다","mis":"SO3-1-u2-X17"},{"t":"상상만 한다","mis":"SO3-1-u2-X16"},{"t":"자료를 덮는다","mis":"SO3-1-u2-X24"}],"explanation":["여럿을","함께","견주기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L15_basic#4','soc',3,1,'u2','L15','g3_1_soc_u2_L15_basic','lesson_basic','SO3-1-u2-C15',1,'ox','auto','자료마다 알려 주는 것이 서로 달라요.',ARRAY['SO3-1-u2-X32']::text[],false,'{"seq":4,"concept":"SO3-1-u2-C15","difficulty":1,"kind":"ox","stem":"자료마다 알려 주는 것이 서로 달라요.","answer":"O","reason_options":[{"t":"사진은 모습, 신문은 소식, 영상은 움직임과 소리를 알려 주기 때문에","correct":true},{"t":"모든 자료는 똑같은 것만 알려 주기 때문에","mis":"SO3-1-u2-X32"}],"mis":"SO3-1-u2-X32","explanation":["사진","신문 · 영상","달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L15_basic#5','soc',3,1,'u2','L15','g3_1_soc_u2_L15_basic','lesson_basic','SO3-1-u2-C15',2,'mc','auto','「버들마을 옛 장터 자료」에서 그때 장터의 소리를 알려 주는 자료는 무엇일까요?',ARRAY['SO3-1-u2-X32','SO3-1-u2-X17']::text[],false,'{"seq":5,"concept":"SO3-1-u2-C15","difficulty":2,"kind":"mc","stem":"「버들마을 옛 장터 자료」에서 그때 장터의 소리를 알려 주는 자료는 무엇일까요?","options":[{"t":"㉢ 영상","correct":true},{"t":"㉠ 사진","mis":"SO3-1-u2-X32"},{"t":"㉡ 신문","mis":"SO3-1-u2-X32"},{"t":"하나도 없다","mis":"SO3-1-u2-X17"}],"explanation":["소리","영상","㉢"],"asset":{"type":"passage","lines":["㉠ 사진 — 장터에 초가 지붕 가게가 늘어서 있다.","㉡ 신문 — 「장날, 이웃 마을에서 소 팔러 몰려와」","㉢ 영상 — 장꾼들이 흥정하는 소리와 엿장수 가위 소리가 들린다."],"title":"버들마을 옛 장터 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L15_basic#6','soc',3,1,'u2','L15','g3_1_soc_u2_L15_basic','lesson_basic','SO3-1-u2-C15',2,'mc','auto','「버들마을 옛 장터 자료」 ㉡으로 알 수 있는 것은 무엇일까요?',ARRAY['SO3-1-u2-X32','SO3-1-u2-X25']::text[],false,'{"seq":6,"concept":"SO3-1-u2-C15","difficulty":2,"kind":"mc","stem":"「버들마을 옛 장터 자료」 ㉡으로 알 수 있는 것은 무엇일까요?","options":[{"t":"장날에 이웃 마을 사람들이 소를 팔러 왔다","correct":true},{"t":"장터 가게 지붕이 초가였다","mis":"SO3-1-u2-X32"},{"t":"장꾼들이 흥정하는 소리","mis":"SO3-1-u2-X32"},{"t":"장날은 열리지 않았다","mis":"SO3-1-u2-X25"}],"explanation":["㉡은 신문","소식","소 팔러"],"asset":{"type":"passage","lines":["㉠ 사진 — 장터에 초가 지붕 가게가 늘어서 있다.","㉡ 신문 — 「장날, 이웃 마을에서 소 팔러 몰려와」","㉢ 영상 — 장꾼들이 흥정하는 소리와 엿장수 가위 소리가 들린다."],"title":"버들마을 옛 장터 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L15_basic#7','soc',3,1,'u2','L15','g3_1_soc_u2_L15_basic','lesson_basic','SO3-1-u2-C15',2,'mc','auto','옛 사진과 영상을 함께 보면 좋은 점은 무엇일까요?',ARRAY['SO3-1-u2-X17','SO3-1-u2-X32']::text[],false,'{"seq":7,"concept":"SO3-1-u2-C15","difficulty":2,"kind":"mc","stem":"옛 사진과 영상을 함께 보면 좋은 점은 무엇일까요?","options":[{"t":"서로 모자란 것을 채워 옛 모습을 더 자세히 알 수 있다","correct":true},{"t":"자료가 사라진다","mis":"SO3-1-u2-X17"},{"t":"아무 도움이 안 된다","mis":"SO3-1-u2-X17"},{"t":"둘은 같은 것이라 하나만 봐도 된다","mis":"SO3-1-u2-X32"}],"explanation":["사진은 모습","영상은 소리까지","채워 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L15_basic#8','soc',3,1,'u2','L15','g3_1_soc_u2_L15_basic','lesson_basic','SO3-1-u2-C15',2,'mc','auto','신문에서 「옛날 우리 지역에 큰 시장이 있었다」는 소식을 보았어요. 알 수 있는 것은 무엇일까요?',ARRAY['SO3-1-u2-X06','SO3-1-u2-X31']::text[],false,'{"seq":8,"concept":"SO3-1-u2-C15","difficulty":2,"kind":"mc","stem":"신문에서 「옛날 우리 지역에 큰 시장이 있었다」는 소식을 보았어요. 알 수 있는 것은 무엇일까요?","options":[{"t":"그때 지역 사람들이 시장에서 물건을 사고팔며 살았다","correct":true},{"t":"내일의 날씨","mis":"SO3-1-u2-X06"},{"t":"그 시장은 지금도 똑같다","mis":"SO3-1-u2-X31"},{"t":"미래의 도시 모습","mis":"SO3-1-u2-X06"}],"explanation":["시장","사고팔기","생활"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L15_basic#9','soc',3,1,'u2','L15','g3_1_soc_u2_L15_basic','lesson_basic','SO3-1-u2-C15',2,'ox','auto','사진 한 장만 보고 옛 지역의 모든 것을 다 안다고 하면 안 돼요.',ARRAY['SO3-1-u2-X17']::text[],false,'{"seq":9,"concept":"SO3-1-u2-C15","difficulty":2,"kind":"ox","stem":"사진 한 장만 보고 옛 지역의 모든 것을 다 안다고 하면 안 돼요.","answer":"O","reason_options":[{"t":"사진에 담기지 않은 소식이나 소리는 다른 자료로 알아야 하기 때문에","correct":true},{"t":"사진 한 장에 그때의 모든 것이 담겨 있기 때문에","mis":"SO3-1-u2-X17"}],"mis":"SO3-1-u2-X17","explanation":["사진에","없는 것","O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L15_basic#10','soc',3,1,'u2','L15','g3_1_soc_u2_L15_basic','lesson_basic','SO3-1-u2-C15',3,'mc','auto','「버들마을 옛 장터 자료」 세 가지를 모두 보고 정리한 말로 가장 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u2-X17','SO3-1-u2-X25','SO3-1-u2-X32']::text[],false,'{"seq":10,"concept":"SO3-1-u2-C15","difficulty":3,"kind":"mc","stem":"「버들마을 옛 장터 자료」 세 가지를 모두 보고 정리한 말로 가장 알맞은 것은 무엇일까요?","options":[{"t":"초가 지붕 가게가 늘어선 장터에 이웃 마을 사람들이 소를 팔러 오고 흥정하는 소리로 북적였다","correct":true},{"t":"사진만 보니 장터에는 소리가 없었다","mis":"SO3-1-u2-X17"},{"t":"신문을 보니 장터는 열리지 않았다","mis":"SO3-1-u2-X25"},{"t":"영상만 보면 소를 팔러 온 마을까지 알 수 있다","mis":"SO3-1-u2-X32"}],"explanation":["㉠ 모습","㉡ 소식","㉢ 소리"],"asset":{"type":"passage","lines":["㉠ 사진 — 장터에 초가 지붕 가게가 늘어서 있다.","㉡ 신문 — 「장날, 이웃 마을에서 소 팔러 몰려와」","㉢ 영상 — 장꾼들이 흥정하는 소리와 엿장수 가위 소리가 들린다."],"title":"버들마을 옛 장터 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L15_challenge#1','soc',3,1,'u2','L15','g3_1_soc_u2_L15_challenge','lesson_challenge','SO3-1-u2-C15',2,'mc','auto','여러 자료를 살펴볼 때 좋은 태도는 무엇일까요?',ARRAY['SO3-1-u2-X24','SO3-1-u2-X17']::text[],false,'{"seq":1,"concept":"SO3-1-u2-C15","difficulty":2,"kind":"mc","stem":"여러 자료를 살펴볼 때 좋은 태도는 무엇일까요?","options":[{"t":"자세히 보고 서로 비교한다","correct":true},{"t":"대충 본다","mis":"SO3-1-u2-X24"},{"t":"바로 덮는다","mis":"SO3-1-u2-X24"},{"t":"하나만 믿는다","mis":"SO3-1-u2-X17"}],"explanation":["자세히","비교","태도"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L15_challenge#2','soc',3,1,'u2','L15','g3_1_soc_u2_L15_challenge','lesson_challenge','SO3-1-u2-C15',2,'mc','auto','자료와 알려 주는 것이 바르게 짝지어진 것은 무엇일까요?',ARRAY['SO3-1-u2-X32']::text[],false,'{"seq":2,"concept":"SO3-1-u2-C15","difficulty":2,"kind":"mc","stem":"자료와 알려 주는 것이 바르게 짝지어진 것은 무엇일까요?","options":[{"t":"영상 자료 — 움직임과 소리","correct":true},{"t":"신문 자료 — 움직임과 소리","mis":"SO3-1-u2-X32"},{"t":"사진 자료 — 글로 쓴 소식","mis":"SO3-1-u2-X32"},{"t":"영상 자료 — 땅 이름의 뜻","mis":"SO3-1-u2-X32"}],"explanation":["영상은","움직이고","소리"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L15_challenge#3','soc',3,1,'u2','L15','g3_1_soc_u2_L15_challenge','lesson_challenge','SO3-1-u2-C15',3,'error','auto','자료를 다룬 친구들의 말이에요. 잘못 다룬 친구는 누구일까요?',ARRAY['SO3-1-u2-X17','SO3-1-u2-X24']::text[],false,'{"seq":3,"concept":"SO3-1-u2-C15","difficulty":3,"kind":"error","stem":"자료를 다룬 친구들의 말이에요. 잘못 다룬 친구는 누구일까요?","options":[{"t":"지호 — 「사진 한 장만 보고 다 안다고 했어.」","correct":true,"mis_target":"SO3-1-u2-X17"},{"t":"수아 — 「사진과 신문을 함께 봤어.」","mis":"SO3-1-u2-X17"},{"t":"도윤 — 「자세히 보고 비교했어.」","mis":"SO3-1-u2-X24"}],"explanation":["한 장만","다 알까요?","지호가 잘못"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L15_challenge#4','soc',3,1,'u2','L15','g3_1_soc_u2_L15_challenge','lesson_challenge','SO3-1-u2-C15',3,'mc','auto','「버들마을 옛 장터 자료」 ㉠ 사진만으로는 알기 어려운 것은 무엇일까요?',ARRAY['SO3-1-u2-X32']::text[],false,'{"seq":4,"concept":"SO3-1-u2-C15","difficulty":3,"kind":"mc","stem":"「버들마을 옛 장터 자료」 ㉠ 사진만으로는 알기 어려운 것은 무엇일까요?","options":[{"t":"장꾼들이 흥정하는 소리","correct":true},{"t":"장터 가게의 지붕 모양","mis":"SO3-1-u2-X32"},{"t":"가게가 늘어선 모습","mis":"SO3-1-u2-X32"},{"t":"장터가 있었다는 것","mis":"SO3-1-u2-X32"}],"explanation":["사진은","소리가 없어요.","흥정 소리"],"asset":{"type":"passage","lines":["㉠ 사진 — 장터에 초가 지붕 가게가 늘어서 있다.","㉡ 신문 — 「장날, 이웃 마을에서 소 팔러 몰려와」","㉢ 영상 — 장꾼들이 흥정하는 소리와 엿장수 가위 소리가 들린다."],"title":"버들마을 옛 장터 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L15_challenge#5','soc',3,1,'u2','L15','g3_1_soc_u2_L15_challenge','lesson_challenge','SO3-1-u2-C15',3,'mc','auto','옛날 우리 지역 학교의 모습을 알아보려고 해요. 자료를 가장 잘 고른 것은 무엇일까요?',ARRAY['SO3-1-u2-X17','SO3-1-u2-X06','SO3-1-u2-X16']::text[],false,'{"seq":5,"concept":"SO3-1-u2-C15","difficulty":3,"kind":"mc","stem":"옛날 우리 지역 학교의 모습을 알아보려고 해요. 자료를 가장 잘 고른 것은 무엇일까요?","options":[{"t":"옛 교실 사진 · 학교 소식을 실은 옛 신문 · 그때 다니신 어른의 증언","correct":true},{"t":"옛 교실 사진 한 장만","mis":"SO3-1-u2-X17"},{"t":"오늘 찍은 운동장 사진 · 내년 학교 달력","mis":"SO3-1-u2-X06"},{"t":"상상해서 그린 미래 학교 그림","mis":"SO3-1-u2-X16"}],"explanation":["사진","신문","증언"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L15_challenge#6','soc',3,1,'u2','L15','g3_1_soc_u2_L15_challenge','lesson_challenge','SO3-1-u2-C15',3,'mc','auto','사진에서는 거리에 사람이 많아 보이는데, 신문에는 「장날」 소식이 실려 있어요. 두 자료를 함께 보고 알 수 있는 것은 무엇일까요?',ARRAY['SO3-1-u2-X17','SO3-1-u2-X16','SO3-1-u2-X25']::text[],false,'{"seq":6,"concept":"SO3-1-u2-C15","difficulty":3,"kind":"mc","stem":"사진에서는 거리에 사람이 많아 보이는데, 신문에는 「장날」 소식이 실려 있어요. 두 자료를 함께 보고 알 수 있는 것은 무엇일까요?","options":[{"t":"장날이라서 사람들이 거리에 많이 모였다","correct":true},{"t":"사진과 신문은 서로 상관이 없다","mis":"SO3-1-u2-X17"},{"t":"사람이 많은 까닭은 알 수 없다","mis":"SO3-1-u2-X16"},{"t":"그날은 비가 와서 아무도 없었다","mis":"SO3-1-u2-X25"}],"explanation":["사람이 많아요.","장날","함께 보면"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L15_challenge#7','soc',3,1,'u2','L15','g3_1_soc_u2_L15_challenge','lesson_challenge','SO3-1-u2-C15',3,'ox','auto','자료를 견주어 볼 때 서로 다른 내용이 있으면 다른 자료나 증언으로 한 번 더 살펴봐요.',ARRAY['SO3-1-u2-X17']::text[],false,'{"seq":7,"concept":"SO3-1-u2-C15","difficulty":3,"kind":"ox","stem":"자료를 견주어 볼 때 서로 다른 내용이 있으면 다른 자료나 증언으로 한 번 더 살펴봐요.","answer":"O","reason_options":[{"t":"여러 자료를 비교해야 옛 모습을 더 정확히 알 수 있기 때문에","correct":true},{"t":"먼저 본 자료 하나만 맞다고 정하면 되기 때문에","mis":"SO3-1-u2-X17"}],"mis":"SO3-1-u2-X17","explanation":["다른 내용","한 번 더","O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L15_challenge#8','soc',3,1,'u2','L15','g3_1_soc_u2_L15_challenge','lesson_challenge','SO3-1-u2-C15',4,'essay','teacher','사진 · 신문 · 영상 자료가 각각 알려 주는 것을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-1-u2-C15","difficulty":4,"kind":"essay","stem":"사진 · 신문 · 영상 자료가 각각 알려 주는 것을 쓰세요.","answer_guide":{"answer":"예: 사진 — 옛 거리와 건물 모습을 그대로 보여 준다. / 신문 — 그때 지역에 있었던 일과 소식을 글로 알려 준다. / 영상 — 옛 모습을 움직임과 소리로 생생하게 보여 준다.","scoring_points":["사진을 바르게 썼는가","신문을 바르게 썼는가","영상을 바르게 썼는가"]},"explanation":["모습","소식","움직임과 소리"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L15_challenge#9','soc',3,1,'u2','L15','g3_1_soc_u2_L15_challenge','lesson_challenge','SO3-1-u2-C15',4,'essay','teacher','「버들마을 옛 장터 자료」 세 가지를 모두 보고 옛 장터 모습을 두 문장으로 정리하세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-1-u2-C15","difficulty":4,"kind":"essay","stem":"「버들마을 옛 장터 자료」 세 가지를 모두 보고 옛 장터 모습을 두 문장으로 정리하세요.","answer_guide":{"answer":"예: 옛 버들마을 장터에는 초가 지붕 가게가 늘어서 있었다. 장날이면 이웃 마을 사람들이 소를 팔러 오고 흥정하는 소리로 북적였다.","scoring_points":["세 자료를 모두 썼는가","두 문장으로 정리했는가","자료에 있는 내용인가"]},"explanation":["㉠","㉡","㉢"],"asset":{"type":"passage","lines":["㉠ 사진 — 장터에 초가 지붕 가게가 늘어서 있다.","㉡ 신문 — 「장날, 이웃 마을에서 소 팔러 몰려와」","㉢ 영상 — 장꾼들이 흥정하는 소리와 엿장수 가위 소리가 들린다."],"title":"버들마을 옛 장터 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L15_challenge#10','soc',3,1,'u2','L15','g3_1_soc_u2_L15_challenge','lesson_challenge','SO3-1-u2-C15',4,'essay','teacher','지역의 옛 모습을 알아볼 때 여러 자료를 함께 보아야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-1-u2-C15","difficulty":4,"kind":"essay","stem":"지역의 옛 모습을 알아볼 때 여러 자료를 함께 보아야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 자료마다 알려 주는 것이 달라서 한 가지 자료만 보면 모르는 것이 생긴다. 여러 자료를 함께 보고 비교하면 옛 모습을 더 자세하고 정확하게 알 수 있다.","scoring_points":["자료마다 다르다고 썼는가","함께 보면 좋은 점을 썼는가","까닭이 알맞은가"]},"explanation":["자료마다","다른 것","함께 보면"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
