INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L16_basic#4','soc',3,1,'u2','L16','g3_1_soc_u2_L16_basic','lesson_basic','SO3-1-u2-C16',1,'ox','auto','문화 해설사는 지역의 옛 모습을 찾아 사람들에게 알기 쉽게 알려 주는 일을 해요.',ARRAY['SO3-1-u2-X36']::text[],false,'{"seq":4,"concept":"SO3-1-u2-C16","difficulty":1,"kind":"ox","stem":"문화 해설사는 지역의 옛 모습을 찾아 사람들에게 알기 쉽게 알려 주는 일을 해요.","answer":"O","reason_options":[{"t":"지역의 옛 모습과 문화를 설명해 주는 사람이기 때문에","correct":true},{"t":"문화 해설사는 불을 끄는 사람이기 때문에","mis":"SO3-1-u2-X36"}],"mis":"SO3-1-u2-X36","explanation":["해설","설명","O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
