INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L16_basic#7','soc',3,1,'u2','L16','g3_1_soc_u2_L16_basic','lesson_basic','SO3-1-u2-C16',2,'mc','auto','「서준이네 모둠 조사 계획」에서 「무엇을 조사할지」에 해당하는 것은 무엇일까요?',ARRAY['SO3-1-u2-X34']::text[],false,'{"seq":7,"concept":"SO3-1-u2-C16","difficulty":2,"kind":"mc","stem":"「서준이네 모둠 조사 계획」에서 「무엇을 조사할지」에 해당하는 것은 무엇일까요?","options":[{"t":"버들마을 사람들이 하는 일","correct":true},{"t":"옛 사진 · 어른 증언 · 마을 누리집","mis":"SO3-1-u2-X34"},{"t":"이번 주 자료 모으기, 다음 주 비교","mis":"SO3-1-u2-X34"},{"t":"모둠 친구 넷","mis":"SO3-1-u2-X34"}],"explanation":["조사 주제","무엇을","하는 일"],"asset":{"type":"passage","lines":["조사 주제 — 버들마을 사람들이 하는 일","조사 방법 — 옛 사진 · 어른 증언 · 마을 누리집","조사 차례 — 이번 주 자료 모으기, 다음 주 비교","함께할 사람 — 모둠 친구 넷"],"title":"서준이네 모둠 조사 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
