INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L16_basic#9','soc',3,1,'u2','L16','g3_1_soc_u2_L16_basic','lesson_basic','SO3-1-u2-C16',2,'match','auto','조사 계획에 담을 것과 그 예를 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-1-u2-C16","difficulty":2,"kind":"match","stem":"조사 계획에 담을 것과 그 예를 알맞게 이으세요.","pairs":[{"l":"무엇을","r":"집 · 옷 · 하는 일 · 놀이 가운데 정하기"},{"l":"어떻게","r":"사진 · 신문 · 어른 증언으로 찾기"},{"l":"언제 · 누구와","r":"조사할 차례와 함께할 사람 정하기"}],"mis":"SO3-1-u2-X34","explanation":["무엇을","어떻게","언제 · 누구와"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L16_basic#10','soc',3,1,'u2','L16','g3_1_soc_u2_L16_basic','lesson_basic','SO3-1-u2-C16',3,'mc','auto','「서준이네 모둠 조사 보고서」의 「알게 된 점」에 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u2-X35','SO3-1-u2-X31','SO3-1-u2-X25']::text[],false,'{"seq":10,"concept":"SO3-1-u2-C16","difficulty":3,"kind":"mc","stem":"「서준이네 모둠 조사 보고서」의 「알게 된 점」에 알맞은 것은 무엇일까요?","options":[{"t":"버들마을 사람들이 하는 일이 농사에서 여러 가지 일로 달라졌다.","correct":true},{"t":"옛날 사람 대부분이 벼농사를 지었다.","mis":"SO3-1-u2-X35"},{"t":"버들마을은 옛날과 하는 일이 똑같다.","mis":"SO3-1-u2-X31"},{"t":"앞으로는 모두 농사를 지을 것이다.","mis":"SO3-1-u2-X25"}],"explanation":["옛날은 농사","오늘은 여러 일","달라졌어요."],"asset":{"type":"passage","lines":["조사한 내용","옛날 — 마을 사람 대부분이 논에서 벼농사를 지었다.","오늘 — 공장 · 가게 · 사무실에서 일하는 사람이 많다.","알게 된 점 — (아직 쓰지 않음)"],"title":"서준이네 모둠 조사 보고서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
