INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L16_challenge#4','soc',3,1,'u2','L16','g3_1_soc_u2_L16_challenge','lesson_challenge','SO3-1-u2-C16',3,'mc','auto','「서준이네 모둠 조사 계획」대로라면 다음 주에 할 일은 무엇일까요?',ARRAY['SO3-1-u2-X34','SO3-1-u2-X35']::text[],false,'{"seq":4,"concept":"SO3-1-u2-C16","difficulty":3,"kind":"mc","stem":"「서준이네 모둠 조사 계획」대로라면 다음 주에 할 일은 무엇일까요?","options":[{"t":"모은 자료로 옛날과 오늘의 하는 일을 비교한다","correct":true},{"t":"조사 주제를 처음부터 다시 정한다","mis":"SO3-1-u2-X34"},{"t":"자료를 모두 버린다","mis":"SO3-1-u2-X34"},{"t":"보고서를 쓰지 않고 끝낸다","mis":"SO3-1-u2-X35"}],"explanation":["이번 주는 모으기","다음 주는","비교"],"asset":{"type":"passage","lines":["조사 주제 — 버들마을 사람들이 하는 일","조사 방법 — 옛 사진 · 어른 증언 · 마을 누리집","조사 차례 — 이번 주 자료 모으기, 다음 주 비교","함께할 사람 — 모둠 친구 넷"],"title":"서준이네 모둠 조사 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
