INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L16_challenge#7','soc',3,1,'u2','L16','g3_1_soc_u2_L16_challenge','lesson_challenge','SO3-1-u2-C16',3,'ox','auto','조사 보고서에는 조사한 내용만 쓰고 알게 된 점은 쓰지 않아도 돼요.',ARRAY['SO3-1-u2-X35']::text[],false,'{"seq":7,"concept":"SO3-1-u2-C16","difficulty":3,"kind":"ox","stem":"조사 보고서에는 조사한 내용만 쓰고 알게 된 점은 쓰지 않아도 돼요.","answer":"X","reason_options":[{"t":"조사로 무엇을 알게 되었는지 정리해야 조사한 보람이 드러나기 때문에","correct":true},{"t":"알게 된 점은 읽는 사람이 알아서 짐작하면 되기 때문에","mis":"SO3-1-u2-X35"}],"mis":"SO3-1-u2-X35","explanation":["알게 된 점","꼭","X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L16_challenge#8','soc',3,1,'u2','L16','g3_1_soc_u2_L16_challenge','lesson_challenge','SO3-1-u2-C16',4,'essay','teacher','우리 지역의 달라진 모습을 조사하는 계획을 무엇을 · 어떻게 · 언제로 나누어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-1-u2-C16","difficulty":4,"kind":"essay","stem":"우리 지역의 달라진 모습을 조사하는 계획을 무엇을 · 어떻게 · 언제로 나누어 쓰세요.","answer_guide":{"answer":"예: 무엇을 — 옛날과 오늘의 우리 동네 길 / 어떻게 — 옛 사진을 찾고 오래 사신 어른께 여쭤본다 / 언제 — 이번 주에 자료를 모으고 다음 주에 비교한다","scoring_points":["무엇을 썼는가","어떻게를 썼는가","언제를 썼는가"]},"explanation":["무엇을","어떻게","언제"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L16_challenge#9','soc',3,1,'u2','L16','g3_1_soc_u2_L16_challenge','lesson_challenge','SO3-1-u2-C16',4,'essay','teacher','「서준이네 모둠 조사 보고서」의 「알게 된 점」을 한두 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-1-u2-C16","difficulty":4,"kind":"essay","stem":"「서준이네 모둠 조사 보고서」의 「알게 된 점」을 한두 문장으로 쓰세요.","answer_guide":{"answer":"예: 버들마을 사람들이 하는 일이 옛날에는 주로 벼농사였는데 오늘날에는 공장 · 가게 · 사무실 일처럼 여러 가지로 달라졌다.","scoring_points":["옛날과 오늘을 견주었는가","달라진 점을 썼는가","조사한 내용에 바탕을 두었는가"]},"explanation":["옛날","오늘","달라진 점"],"asset":{"type":"passage","lines":["조사한 내용","옛날 — 마을 사람 대부분이 논에서 벼농사를 지었다.","오늘 — 공장 · 가게 · 사무실에서 일하는 사람이 많다.","알게 된 점 — (아직 쓰지 않음)"],"title":"서준이네 모둠 조사 보고서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L16_challenge#10','soc',3,1,'u2','L16','g3_1_soc_u2_L16_challenge','lesson_challenge','SO3-1-u2-C16',4,'essay','teacher','문화 해설사가 되어 우리 지역의 옛 모습을 소개하는 말을 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-1-u2-C16","difficulty":4,"kind":"essay","stem":"문화 해설사가 되어 우리 지역의 옛 모습을 소개하는 말을 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 이곳은 옛날 마을 사람들이 물을 긷던 우물이 있던 자리예요. 수도가 없던 때라 아침마다 사람들이 모여 물을 길으며 이야기를 나누었답니다.","scoring_points":["옛 모습을 소개했는가","알기 쉽게 설명했는가","두 문장으로 썼는가"]},"explanation":["어디?","옛날엔?","알기 쉽게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
