INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L17_basic#4','soc',3,1,'u2','L17','g3_1_soc_u2_L17_basic','lesson_basic','SO3-1-u2-C17',1,'ox','auto','「달라진 우리 지역」 영상은 옛날 모습 다음에 오늘 모습을 보여 주면 변화를 잘 알 수 있어요.',ARRAY['SO3-1-u2-X37']::text[],false,'{"seq":4,"concept":"SO3-1-u2-C17","difficulty":1,"kind":"ox","stem":"「달라진 우리 지역」 영상은 옛날 모습 다음에 오늘 모습을 보여 주면 변화를 잘 알 수 있어요.","answer":"O","reason_options":[{"t":"옛날에서 오늘로 흐르는 차례라서 달라진 점이 잘 보이기 때문에","correct":true},{"t":"차례는 아무렇게나 해도 똑같이 보이기 때문에","mis":"SO3-1-u2-X37"}],"mis":"SO3-1-u2-X37","explanation":["옛날 →","오늘","O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
