INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L17_basic#9','soc',3,1,'u2','L17','g3_1_soc_u2_L17_basic','lesson_basic','SO3-1-u2-C17',2,'ox','auto','자막과 소개 없이 사진만 늘어놓아도 보는 사람이 달라진 점을 모두 알아요.',ARRAY['SO3-1-u2-X38']::text[],false,'{"seq":9,"concept":"SO3-1-u2-C17","difficulty":2,"kind":"ox","stem":"자막과 소개 없이 사진만 늘어놓아도 보는 사람이 달라진 점을 모두 알아요.","answer":"X","reason_options":[{"t":"설명이 있어야 무엇이 어떻게 달라졌는지 잘 전해지기 때문에","correct":true},{"t":"사진만 있으면 설명은 필요 없기 때문에","mis":"SO3-1-u2-X38"}],"mis":"SO3-1-u2-X38","explanation":["설명이","있어야","X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
