INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L17_challenge#3','soc',3,1,'u2','L17','g3_1_soc_u2_L17_challenge','lesson_challenge','SO3-1-u2-C17',3,'mc','auto','「예린이네 모둠 영상 장면 카드」에서 장면 ㉢의 자막이 하는 일은 무엇일까요?',ARRAY['SO3-1-u2-X38']::text[],false,'{"seq":3,"concept":"SO3-1-u2-C17","difficulty":3,"kind":"mc","stem":"「예린이네 모둠 영상 장면 카드」에서 장면 ㉢의 자막이 하는 일은 무엇일까요?","options":[{"t":"옛날과 오늘 사이에 무엇이 달라졌는지 글로 알려 준다","correct":true},{"t":"영상을 끝내는 인사를 한다","mis":"SO3-1-u2-X38"},{"t":"옛날 사진을 보여 준다","mis":"SO3-1-u2-X38"},{"t":"아무 일도 하지 않는다","mis":"SO3-1-u2-X38"}],"explanation":["㉢","자막","달라진 점"],"asset":{"type":"passage","lines":["장면 ㉠ — 오늘날 버들마을 큰 다리 사진","장면 ㉡ — 옛날 나룻배를 타고 건너던 사진","장면 ㉢ — 자막 「배 대신 다리로 건너게 되었어요」","장면 ㉣ — 모둠 친구들의 마무리 인사"],"title":"예린이네 모둠 영상 장면 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L17_challenge#4','soc',3,1,'u2','L17','g3_1_soc_u2_L17_challenge','lesson_challenge','SO3-1-u2-C17',3,'mc','auto','하린이네 모둠은 오늘 사진을 먼저, 옛날 사진을 나중에 보여 주었어요. 더 좋게 고칠 방법은 무엇일까요?',ARRAY['SO3-1-u2-X38','SO3-1-u2-X37']::text[],false,'{"seq":4,"concept":"SO3-1-u2-C17","difficulty":3,"kind":"mc","stem":"하린이네 모둠은 오늘 사진을 먼저, 옛날 사진을 나중에 보여 주었어요. 더 좋게 고칠 방법은 무엇일까요?","options":[{"t":"옛날 사진을 먼저, 오늘 사진을 나중에 보여 주어 변화의 흐름이 보이게 한다","correct":true},{"t":"사진을 모두 빼고 글만 넣는다","mis":"SO3-1-u2-X38"},{"t":"차례를 아무렇게나 섞는다","mis":"SO3-1-u2-X37"},{"t":"오늘 사진만 남긴다","mis":"SO3-1-u2-X37"}],"explanation":["옛날이","먼저","흐름"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L17_challenge#5','soc',3,1,'u2','L17','g3_1_soc_u2_L17_challenge','lesson_challenge','SO3-1-u2-C17',3,'error','auto','영상을 만든 친구들의 말이에요. 잘못 말한 친구는 누구일까요?',ARRAY['SO3-1-u2-X38','SO3-1-u2-X37']::text[],false,'{"seq":5,"concept":"SO3-1-u2-C17","difficulty":3,"kind":"error","stem":"영상을 만든 친구들의 말이에요. 잘못 말한 친구는 누구일까요?","options":[{"t":"지호 — 「자막은 없어도 돼. 사진만 넣으면 다 알아.」","correct":true,"mis_target":"SO3-1-u2-X38"},{"t":"수아 — 「옛날에서 오늘 차례로 놓았어.」","mis":"SO3-1-u2-X37"},{"t":"서준 — 「무엇을 왜 만들었는지 소개했어.」","mis":"SO3-1-u2-X38"}],"explanation":["자막이","도와줘요.","지호가 잘못"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L17_challenge#6','soc',3,1,'u2','L17','g3_1_soc_u2_L17_challenge','lesson_challenge','SO3-1-u2-C17',3,'mc','auto','옛 시장 사진과 오늘 시장 사진에 붙일 자막으로 가장 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u2-X38','SO3-1-u2-X06']::text[],false,'{"seq":6,"concept":"SO3-1-u2-C17","difficulty":3,"kind":"mc","stem":"옛 시장 사진과 오늘 시장 사진에 붙일 자막으로 가장 알맞은 것은 무엇일까요?","options":[{"t":"「흙바닥 장터가 지붕 있는 시장으로 바뀌었어요」","correct":true},{"t":"「사진이에요」","mis":"SO3-1-u2-X38"},{"t":"「재미있어요」","mis":"SO3-1-u2-X38"},{"t":"「오늘 날씨는 맑아요」","mis":"SO3-1-u2-X06"}],"explanation":["무엇이","어떻게","바뀌었나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L17_challenge#7','soc',3,1,'u2','L17','g3_1_soc_u2_L17_challenge','lesson_challenge','SO3-1-u2-C17',3,'ox','auto','영상을 소개할 때는 무엇을 왜 만들었는지 함께 말하면 좋아요.',ARRAY['SO3-1-u2-X38']::text[],false,'{"seq":7,"concept":"SO3-1-u2-C17","difficulty":3,"kind":"ox","stem":"영상을 소개할 때는 무엇을 왜 만들었는지 함께 말하면 좋아요.","answer":"O","reason_options":[{"t":"보는 사람이 영상이 보여 주려는 변화를 잘 이해할 수 있기 때문에","correct":true},{"t":"영상은 보여 주기만 하면 설명이 필요 없기 때문에","mis":"SO3-1-u2-X38"}],"mis":"SO3-1-u2-X38","explanation":["무엇을","왜","O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L17_challenge#8','soc',3,1,'u2','L17','g3_1_soc_u2_L17_challenge','lesson_challenge','SO3-1-u2-C17',4,'essay','teacher','「달라진 우리 지역」 영상을 만드는 차례를 네 단계로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-1-u2-C17","difficulty":4,"kind":"essay","stem":"「달라진 우리 지역」 영상을 만드는 차례를 네 단계로 쓰세요.","answer_guide":{"answer":"예: ① 옛 사진과 오늘 사진처럼 보여 줄 자료를 고른다. ② 옛날 → 오늘 차례를 정한다. ③ 무엇이 달라졌는지 자막을 붙인다. ④ 친구에게 무엇을 왜 만들었는지 소개한다.","scoring_points":["네 단계를 썼는가","차례가 바른가","옛날 → 오늘 차례가 드러나는가"]},"explanation":["자료","차례 · 자막","소개"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L17_challenge#9','soc',3,1,'u2','L17','g3_1_soc_u2_L17_challenge','lesson_challenge','SO3-1-u2-C17',4,'essay','teacher','우리 지역의 달라진 모습 한 가지를 골라 영상에 넣을 자막을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-1-u2-C17","difficulty":4,"kind":"essay","stem":"우리 지역의 달라진 모습 한 가지를 골라 영상에 넣을 자막을 쓰세요.","answer_guide":{"answer":"예: 「옛날에는 흙길이었던 학교 앞 길이 오늘날에는 넓은 찻길과 인도로 바뀌었어요.」","scoring_points":["달라진 모습을 골랐는가","옛날과 오늘이 드러나는가","자막으로 짧고 분명한가"]},"explanation":["옛날","오늘","짧게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_L17_challenge#10','soc',3,1,'u2','L17','g3_1_soc_u2_L17_challenge','lesson_challenge','SO3-1-u2-C17',4,'essay','teacher','「예린이네 모둠 영상」을 친구들에게 소개하는 말을 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-1-u2-C17","difficulty":4,"kind":"essay","stem":"「예린이네 모둠 영상」을 친구들에게 소개하는 말을 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 우리 모둠은 버들마을 사람들이 냇물을 건너는 방법이 어떻게 달라졌는지 영상으로 만들었어요. 옛날에는 나룻배를 탔지만 오늘날에는 큰 다리로 건넌다는 것을 보여 주고 싶었어요.","scoring_points":["무엇을 만들었는지 말했는가","왜 만들었는지 말했는가","두 문장으로 썼는가"]},"explanation":["무엇을","왜","두 문장"],"asset":{"type":"passage","lines":["장면 ㉠ — 오늘날 버들마을 큰 다리 사진","장면 ㉡ — 옛날 나룻배를 타고 건너던 사진","장면 ㉢ — 자막 「배 대신 다리로 건너게 되었어요」","장면 ㉣ — 모둠 친구들의 마무리 인사"],"title":"예린이네 모둠 영상 장면 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
