INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_a#16','soc',3,1,'u2','','g3_1_soc_u2_review_a','unit_review','SO3-1-u2-C17',2,'mc','auto','단원 정리: 「달라진 우리 지역」 영상의 장면 차례로 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u2-X37','SO3-1-u2-X38']::text[],false,'{"seq":16,"concept":"SO3-1-u2-C17","difficulty":2,"kind":"mc","stem":"단원 정리: 「달라진 우리 지역」 영상의 장면 차례로 알맞은 것은 무엇일까요?","options":[{"t":"옛날 모습 → 오늘 모습 → 달라진 점 자막","correct":true},{"t":"오늘 모습 → 자막 → 옛날 모습","mis":"SO3-1-u2-X37"},{"t":"자막만 보여 주기","mis":"SO3-1-u2-X38"},{"t":"아무 차례로 섞기","mis":"SO3-1-u2-X37"}],"explanation":["옛날","오늘","자막"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_a#17','soc',3,1,'u2','','g3_1_soc_u2_review_a','unit_review','SO3-1-u2-C4',3,'mc','auto','「서준이의 갈대마을 옛 모습 탐험 일지」 ⑦처럼 연표로 정리하면 좋은 점은 무엇일까요?',ARRAY['SO3-1-u2-X09','SO3-1-u2-X12','SO3-1-u2-X11']::text[],false,'{"seq":17,"concept":"SO3-1-u2-C4","difficulty":3,"kind":"mc","stem":"「서준이의 갈대마을 옛 모습 탐험 일지」 ⑦처럼 연표로 정리하면 좋은 점은 무엇일까요?","options":[{"t":"마을에 있었던 일의 순서와 변화를 한눈에 알 수 있다","correct":true},{"t":"마을 이름의 뜻을 알 수 있다","mis":"SO3-1-u2-X09"},{"t":"연표는 나의 일만 적을 수 있다","mis":"SO3-1-u2-X12"},{"t":"예쁜 색이 가장 중요하다","mis":"SO3-1-u2-X11"}],"explanation":["연표는","순서와 변화","한눈에"],"asset":{"type":"passage","lines":["① 할머니 앨범에서 갈대마을 옛 사진을 찾았다. 초가집이 보였다.","② 박물관에서 맷돌과 다듬잇돌을 보았다.","③ 할아버지께 옛날 장날 이야기를 여쭤 들었다.","④ 도서관에서 갈대마을 이름 이야기를 읽었다. 갈대가 우거졌대.","⑤ 옛 신문에서 「갈대마을에 첫 버스 다녀」 소식을 찾았다.","⑥ 옛날과 오늘의 마을 길 사진을 나란히 놓고 견주었다.","⑦ 알게 된 것을 연표와 보고서로 정리했다.","⑧ 모둠과 영상을 만들어 자막을 넣고 친구들에게 소개했다."],"title":"서준이의 갈대마을 옛 모습 탐험 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_a#18','soc',3,1,'u2','','g3_1_soc_u2_review_a','unit_review','SO3-1-u2-C9',3,'mc','auto','「서준이의 갈대마을 옛 모습 탐험 일지」 ③과 ⑤를 함께 보면 좋은 까닭은 무엇일까요?',ARRAY['SO3-1-u2-X17','SO3-1-u2-X23','SO3-1-u2-X06']::text[],false,'{"seq":18,"concept":"SO3-1-u2-C9","difficulty":3,"kind":"mc","stem":"「서준이의 갈대마을 옛 모습 탐험 일지」 ③과 ⑤를 함께 보면 좋은 까닭은 무엇일까요?","options":[{"t":"증언과 신문이 서로 다른 것을 알려 주어 옛 모습을 더 자세히 알 수 있어서","correct":true},{"t":"둘 중 하나만 보면 다 알 수 있어서","mis":"SO3-1-u2-X17"},{"t":"증언은 쓸모없어서","mis":"SO3-1-u2-X23"},{"t":"신문은 미래 소식을 알려 줘서","mis":"SO3-1-u2-X06"}],"explanation":["③ 증언","⑤ 신문","함께"],"asset":{"type":"passage","lines":["① 할머니 앨범에서 갈대마을 옛 사진을 찾았다. 초가집이 보였다.","② 박물관에서 맷돌과 다듬잇돌을 보았다.","③ 할아버지께 옛날 장날 이야기를 여쭤 들었다.","④ 도서관에서 갈대마을 이름 이야기를 읽었다. 갈대가 우거졌대.","⑤ 옛 신문에서 「갈대마을에 첫 버스 다녀」 소식을 찾았다.","⑥ 옛날과 오늘의 마을 길 사진을 나란히 놓고 견주었다.","⑦ 알게 된 것을 연표와 보고서로 정리했다.","⑧ 모둠과 영상을 만들어 자막을 넣고 친구들에게 소개했다."],"title":"서준이의 갈대마을 옛 모습 탐험 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_a#19','soc',3,1,'u2','','g3_1_soc_u2_review_a','unit_review','SO3-1-u2-C15',3,'mc','auto','단원 정리: 옛날 갈대마을 장날의 북적이던 소리를 알고 싶어요. 가장 알맞은 자료는 무엇일까요?',ARRAY['SO3-1-u2-X32']::text[],false,'{"seq":19,"concept":"SO3-1-u2-C15","difficulty":3,"kind":"mc","stem":"단원 정리: 옛날 갈대마을 장날의 북적이던 소리를 알고 싶어요. 가장 알맞은 자료는 무엇일까요?","options":[{"t":"장날 모습을 담은 옛 영상","correct":true},{"t":"장터의 옛 사진","mis":"SO3-1-u2-X32"},{"t":"갈대마을 옛 지도","mis":"SO3-1-u2-X32"},{"t":"갈대마을 땅 이름","mis":"SO3-1-u2-X32"}],"explanation":["소리","움직임","영상"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_a#20','soc',3,1,'u2','','g3_1_soc_u2_review_a','unit_review','SO3-1-u2-C16',3,'mc','auto','단원 정리: 「옛날과 오늘의 마을 길」을 조사하려는 모둠의 계획으로 가장 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u2-X34','SO3-1-u2-X08']::text[],false,'{"seq":20,"concept":"SO3-1-u2-C16","difficulty":3,"kind":"mc","stem":"단원 정리: 「옛날과 오늘의 마을 길」을 조사하려는 모둠의 계획으로 가장 알맞은 것은 무엇일까요?","options":[{"t":"옛 길 사진과 오늘 길 사진을 모으고 어른께 여쭤본 뒤 비교해 보고서로 정리한다","correct":true},{"t":"계획 없이 사진 한 장을 찍고 끝낸다","mis":"SO3-1-u2-X34"},{"t":"보고서를 먼저 쓰고 자료는 찾지 않는다","mis":"SO3-1-u2-X34"},{"t":"오늘 길만 보고 옛날 길은 살피지 않는다","mis":"SO3-1-u2-X08"}],"explanation":["자료","비교","보고서"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_a#21','soc',3,1,'u2','','g3_1_soc_u2_review_a','unit_review','SO3-1-u2-C11',3,'mc','auto','단원 정리: 「옛날 옷 손질」 전시관에 어울리는 물건끼리 모은 것은 무엇일까요?',ARRAY['SO3-1-u2-X27']::text[],false,'{"seq":21,"concept":"SO3-1-u2-C11","difficulty":3,"kind":"mc","stem":"단원 정리: 「옛날 옷 손질」 전시관에 어울리는 물건끼리 모은 것은 무엇일까요?","options":[{"t":"다듬잇돌과 방망이 · 숯다리미","correct":true},{"t":"맷돌 · 가마솥","mis":"SO3-1-u2-X27"},{"t":"새 운동화 · 장난감 로봇","mis":"SO3-1-u2-X27"},{"t":"스마트폰 · 태블릿","mis":"SO3-1-u2-X27"}],"explanation":["옷","손질","다듬잇돌 · 숯다리미"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_a#22','soc',3,1,'u2','','g3_1_soc_u2_review_a','unit_review','SO3-1-u2-C12',3,'mc','auto','단원 정리: 오늘 우리 반 학급 신문을 잘 보관해 두면 먼 훗날 어떻게 쓰일까요?',ARRAY['SO3-1-u2-X30','SO3-1-u2-X02']::text[],false,'{"seq":22,"concept":"SO3-1-u2-C12","difficulty":3,"kind":"mc","stem":"단원 정리: 오늘 우리 반 학급 신문을 잘 보관해 두면 먼 훗날 어떻게 쓰일까요?","options":[{"t":"그때 어린이들의 생활을 알려 주는 자료가 된다","correct":true},{"t":"아무 쓸모가 없다","mis":"SO3-1-u2-X30"},{"t":"미래의 소식을 알려 준다","mis":"SO3-1-u2-X30"},{"t":"시간이 거꾸로 흐르게 한다","mis":"SO3-1-u2-X02"}],"explanation":["오늘의 기록","먼 훗날","자료"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_a#23','soc',3,1,'u2','','g3_1_soc_u2_review_a','unit_review','SO3-1-u2-C5',4,'essay','teacher','우리 가족에게 있었던 일 네 가지를 떠올려, 연표 만드는 차례에 맞게 가족 연표를 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO3-1-u2-C5","difficulty":4,"kind":"essay","stem":"우리 가족에게 있었던 일 네 가지를 떠올려, 연표 만드는 차례에 맞게 가족 연표를 쓰세요.","answer_guide":{"answer":"예: (사진을 모으고 순서를 정한 뒤) 엄마 아빠가 결혼함 → 내가 태어남 → 지금 집으로 이사 옴 → 동생이 태어남 — 일마다 때를 함께 적고 그림을 더해 꾸민다.","scoring_points":["네 가지 일을 썼는가","시간 순서대로 썼는가","때와 일을 함께 쓰거나 꾸미기를 마지막에 두었는가"]},"explanation":["모으기","순서 · 적기","꾸미기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_a#24','soc',3,1,'u2','','g3_1_soc_u2_review_a','unit_review','SO3-1-u2-C10',4,'essay','teacher','옛 사진 한 장을 분석하는 방법을 「보이는 것」과 「알게 된 것」이 드러나게 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO3-1-u2-C10","difficulty":4,"kind":"essay","stem":"옛 사진 한 장을 분석하는 방법을 「보이는 것」과 「알게 된 것」이 드러나게 쓰세요.","answer_guide":{"answer":"예: 먼저 사진을 고르고 옷차림 · 물건 · 거리 모습을 자세히 본다. 「사람들이 한복을 입었다」는 보이는 것에서 「옛날에는 한복을 자주 입었구나」를 알게 된 것으로 정리하고 친구와 나눈다.","scoring_points":["자세히 살펴본다고 썼는가","보이는 것과 알게 된 것을 갈라 썼는가","정리하고 나눈다고 썼는가"]},"explanation":["보이는 것","알게 된 것","나누기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_a#25','soc',3,1,'u2','','g3_1_soc_u2_review_a','unit_review','SO3-1-u2-C16',4,'essay','teacher','우리 지역의 달라진 모습 한 가지를 정해 계획 · 비교 · 알게 된 점이 드러나게 짧은 보고서를 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO3-1-u2-C16","difficulty":4,"kind":"essay","stem":"우리 지역의 달라진 모습 한 가지를 정해 계획 · 비교 · 알게 된 점이 드러나게 짧은 보고서를 쓰세요.","answer_guide":{"answer":"예: 계획 — 옛날과 오늘의 장터를 옛 사진과 어른 증언으로 조사한다. / 비교 — 옛날에는 닷새마다 흙바닥 장이 섰는데 오늘날에는 날마다 여는 지붕 있는 시장이 있다. / 알게 된 점 — 사람들이 물건을 사고파는 모습이 더 편리하게 달라졌다.","scoring_points":["계획을 썼는가","옛날과 오늘을 비교했는가","알게 된 점을 썼는가"]},"explanation":["계획","비교","알게 된 점"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_b#1','soc',3,1,'u2','','g3_1_soc_u2_review_b','unit_review','SO3-1-u2-C1',1,'mc','auto','「지난주」가 나타내는 때는 무엇일까요?',ARRAY['SO3-1-u2-X01']::text[],false,'{"seq":1,"concept":"SO3-1-u2-C1","difficulty":1,"kind":"mc","stem":"「지난주」가 나타내는 때는 무엇일까요?","options":[{"t":"과거","correct":true},{"t":"현재","mis":"SO3-1-u2-X01"},{"t":"미래","mis":"SO3-1-u2-X01"},{"t":"내일","mis":"SO3-1-u2-X01"}],"explanation":["지난","지나간 때","과거"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_b#2','soc',3,1,'u2','','g3_1_soc_u2_review_b','unit_review','SO3-1-u2-C4',1,'mc','auto','「서준이의 갈대마을 옛 모습 탐험 일지」 ⑦에서 일을 시간 순서대로 정리한 표는 무엇일까요?',ARRAY['SO3-1-u2-X09']::text[],false,'{"seq":2,"concept":"SO3-1-u2-C4","difficulty":1,"kind":"mc","stem":"「서준이의 갈대마을 옛 모습 탐험 일지」 ⑦에서 일을 시간 순서대로 정리한 표는 무엇일까요?","options":[{"t":"연표","correct":true},{"t":"설명 카드","mis":"SO3-1-u2-X09"},{"t":"자막","mis":"SO3-1-u2-X09"},{"t":"일기 예보","mis":"SO3-1-u2-X09"}],"explanation":["⑦을 봐요.","시간 순서","연표"],"asset":{"type":"passage","lines":["① 할머니 앨범에서 갈대마을 옛 사진을 찾았다. 초가집이 보였다.","② 박물관에서 맷돌과 다듬잇돌을 보았다.","③ 할아버지께 옛날 장날 이야기를 여쭤 들었다.","④ 도서관에서 갈대마을 이름 이야기를 읽었다. 갈대가 우거졌대.","⑤ 옛 신문에서 「갈대마을에 첫 버스 다녀」 소식을 찾았다.","⑥ 옛날과 오늘의 마을 길 사진을 나란히 놓고 견주었다.","⑦ 알게 된 것을 연표와 보고서로 정리했다.","⑧ 모둠과 영상을 만들어 자막을 넣고 친구들에게 소개했다."],"title":"서준이의 갈대마을 옛 모습 탐험 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
