INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_b#16','soc',3,1,'u2','','g3_1_soc_u2_review_b','unit_review','SO3-1-u2-C17',2,'mc','auto','단원 정리: 영상에 넣을 자막으로 알맞은 것은 무엇일까요?',ARRAY['SO3-1-u2-X38','SO3-1-u2-X06']::text[],false,'{"seq":16,"concept":"SO3-1-u2-C17","difficulty":2,"kind":"mc","stem":"단원 정리: 영상에 넣을 자막으로 알맞은 것은 무엇일까요?","options":[{"t":"「나룻배 대신 다리로 건너게 되었어요」","correct":true},{"t":"「몰라요」","mis":"SO3-1-u2-X38"},{"t":"「사진」","mis":"SO3-1-u2-X38"},{"t":"「내일 비 와요」","mis":"SO3-1-u2-X06"}],"explanation":["무엇이","어떻게","달라졌나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_b#17','soc',3,1,'u2','','g3_1_soc_u2_review_b','unit_review','SO3-1-u2-C4',3,'mc','auto','단원 정리: 갈대마을 연표를 만들 때 맨 앞에 와야 할 일은 무엇일까요?',ARRAY['SO3-1-u2-X03','SO3-1-u2-X14']::text[],false,'{"seq":17,"concept":"SO3-1-u2-C4","difficulty":3,"kind":"mc","stem":"단원 정리: 갈대마을 연표를 만들 때 맨 앞에 와야 할 일은 무엇일까요?","options":[{"t":"갈대가 우거진 들판에 사람들이 모여 살기 시작함","correct":true},{"t":"첫 버스가 다니기 시작함","mis":"SO3-1-u2-X03"},{"t":"모둠이 영상을 만들어 소개함","mis":"SO3-1-u2-X03"},{"t":"오늘 마을 길을 사진으로 찍음","mis":"SO3-1-u2-X14"}],"explanation":["가장","먼저 일","맨 앞"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_b#18','soc',3,1,'u2','','g3_1_soc_u2_review_b','unit_review','SO3-1-u2-C13',3,'mc','auto','「서준이의 갈대마을 옛 모습 탐험 일지」 ⑤의 소식으로 알 수 있는 갈대마을의 변화는 무엇일까요?',ARRAY['SO3-1-u2-X31','SO3-1-u2-X16']::text[],false,'{"seq":18,"concept":"SO3-1-u2-C13","difficulty":3,"kind":"mc","stem":"「서준이의 갈대마을 옛 모습 탐험 일지」 ⑤의 소식으로 알 수 있는 갈대마을의 변화는 무엇일까요?","options":[{"t":"버스가 다니게 되면서 마을 사람들이 오가기 편해졌다","correct":true},{"t":"갈대마을은 옛날과 똑같다","mis":"SO3-1-u2-X31"},{"t":"버스는 옛날부터 늘 다녔다","mis":"SO3-1-u2-X31"},{"t":"신문으로는 변화를 알 수 없다","mis":"SO3-1-u2-X16"}],"explanation":["첫 버스","그 전엔?","편해졌어요."],"asset":{"type":"passage","lines":["① 할머니 앨범에서 갈대마을 옛 사진을 찾았다. 초가집이 보였다.","② 박물관에서 맷돌과 다듬잇돌을 보았다.","③ 할아버지께 옛날 장날 이야기를 여쭤 들었다.","④ 도서관에서 갈대마을 이름 이야기를 읽었다. 갈대가 우거졌대.","⑤ 옛 신문에서 「갈대마을에 첫 버스 다녀」 소식을 찾았다.","⑥ 옛날과 오늘의 마을 길 사진을 나란히 놓고 견주었다.","⑦ 알게 된 것을 연표와 보고서로 정리했다.","⑧ 모둠과 영상을 만들어 자막을 넣고 친구들에게 소개했다."],"title":"서준이의 갈대마을 옛 모습 탐험 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_b#19','soc',3,1,'u2','','g3_1_soc_u2_review_b','unit_review','SO3-1-u2-C15',3,'mc','auto','단원 정리: 사진에는 냇가에서 빨래하는 사람이 많은데, 증언에서 「그땐 집에 물이 안 나왔지.」라고 하셨어요. 두 자료로 알 수 있는 것은 무엇일까요?',ARRAY['SO3-1-u2-X17','SO3-1-u2-X25','SO3-1-u2-X16']::text[],false,'{"seq":19,"concept":"SO3-1-u2-C15","difficulty":3,"kind":"mc","stem":"단원 정리: 사진에는 냇가에서 빨래하는 사람이 많은데, 증언에서 「그땐 집에 물이 안 나왔지.」라고 하셨어요. 두 자료로 알 수 있는 것은 무엇일까요?","options":[{"t":"집에 물이 나오지 않아 냇가에 나와 빨래를 했다","correct":true},{"t":"사진과 증언은 서로 상관없다","mis":"SO3-1-u2-X17"},{"t":"그때도 집마다 세탁기가 있었다","mis":"SO3-1-u2-X25"},{"t":"빨래하는 까닭은 알 수 없다","mis":"SO3-1-u2-X16"}],"explanation":["사진 속","증언 속","함께 보면"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_b#20','soc',3,1,'u2','','g3_1_soc_u2_review_b','unit_review','SO3-1-u2-C16',3,'mc','auto','「서준이의 갈대마을 옛 모습 탐험 일지」 ⑥에서 길 사진을 나란히 놓은 까닭은 무엇일까요?',ARRAY['SO3-1-u2-X31','SO3-1-u2-X08','SO3-1-u2-X34']::text[],false,'{"seq":20,"concept":"SO3-1-u2-C16","difficulty":3,"kind":"mc","stem":"「서준이의 갈대마을 옛 모습 탐험 일지」 ⑥에서 길 사진을 나란히 놓은 까닭은 무엇일까요?","options":[{"t":"옛날과 오늘의 길이 어떻게 달라졌는지 알기 위해","correct":true},{"t":"길은 변하지 않았다는 것을 보이려고","mis":"SO3-1-u2-X31"},{"t":"사진을 숨기려고","mis":"SO3-1-u2-X08"},{"t":"계획을 세우려고","mis":"SO3-1-u2-X34"}],"explanation":["나란히","견주면","달라진 점"],"asset":{"type":"passage","lines":["① 할머니 앨범에서 갈대마을 옛 사진을 찾았다. 초가집이 보였다.","② 박물관에서 맷돌과 다듬잇돌을 보았다.","③ 할아버지께 옛날 장날 이야기를 여쭤 들었다.","④ 도서관에서 갈대마을 이름 이야기를 읽었다. 갈대가 우거졌대.","⑤ 옛 신문에서 「갈대마을에 첫 버스 다녀」 소식을 찾았다.","⑥ 옛날과 오늘의 마을 길 사진을 나란히 놓고 견주었다.","⑦ 알게 된 것을 연표와 보고서로 정리했다.","⑧ 모둠과 영상을 만들어 자막을 넣고 친구들에게 소개했다."],"title":"서준이의 갈대마을 옛 모습 탐험 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
