INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_b#22','soc',3,1,'u2','','g3_1_soc_u2_review_b','unit_review','SO3-1-u2-C12',3,'mc','auto','단원 정리: 옛 생활을 알고 나서 오늘을 보면 어떤 점이 좋을까요?',ARRAY['SO3-1-u2-X29','SO3-1-u2-X02']::text[],false,'{"seq":22,"concept":"SO3-1-u2-C12","difficulty":3,"kind":"mc","stem":"단원 정리: 옛 생활을 알고 나서 오늘을 보면 어떤 점이 좋을까요?","options":[{"t":"오늘의 생활이 어떻게 달라져 왔는지 이해하고 소중히 여기게 된다","correct":true},{"t":"오늘과 옛날은 아무 관계가 없다","mis":"SO3-1-u2-X29"},{"t":"오늘을 잊게 된다","mis":"SO3-1-u2-X29"},{"t":"옛날로 돌아가고 싶어진다","mis":"SO3-1-u2-X02"}],"explanation":["옛 생활","오늘","소중히"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_b#23','soc',3,1,'u2','','g3_1_soc_u2_review_b','unit_review','SO3-1-u2-C1',4,'essay','teacher','「서준이의 갈대마을 옛 모습 탐험 일지」에서 과거의 일과 오늘의 일을 하나씩 찾아 쓰고, 둘이 어떻게 이어지는지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO3-1-u2-C1","difficulty":4,"kind":"essay","stem":"「서준이의 갈대마을 옛 모습 탐험 일지」에서 과거의 일과 오늘의 일을 하나씩 찾아 쓰고, 둘이 어떻게 이어지는지 쓰세요.","answer_guide":{"answer":"예: 과거 — 옛날 갈대마을에 첫 버스가 다녔다. / 오늘 — 서준이가 마을 길 사진을 견주어 보았다. 시간은 과거에서 현재로 흘러 옛날 일이 쌓여 오늘의 마을이 되었다.","scoring_points":["과거의 일을 찾았는가","오늘의 일을 찾았는가","시간의 흐름으로 이었는가"]},"explanation":["과거","현재","이어져요."],"asset":{"type":"passage","lines":["① 할머니 앨범에서 갈대마을 옛 사진을 찾았다. 초가집이 보였다.","② 박물관에서 맷돌과 다듬잇돌을 보았다.","③ 할아버지께 옛날 장날 이야기를 여쭤 들었다.","④ 도서관에서 갈대마을 이름 이야기를 읽었다. 갈대가 우거졌대.","⑤ 옛 신문에서 「갈대마을에 첫 버스 다녀」 소식을 찾았다.","⑥ 옛날과 오늘의 마을 길 사진을 나란히 놓고 견주었다.","⑦ 알게 된 것을 연표와 보고서로 정리했다.","⑧ 모둠과 영상을 만들어 자막을 넣고 친구들에게 소개했다."],"title":"서준이의 갈대마을 옛 모습 탐험 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_b#24','soc',3,1,'u2','','g3_1_soc_u2_review_b','unit_review','SO3-1-u2-C15',4,'essay','teacher','「서준이의 갈대마을 옛 모습 탐험 일지」에서 서준이가 여러 자료를 함께 본 것이 좋은 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO3-1-u2-C15","difficulty":4,"kind":"essay","stem":"「서준이의 갈대마을 옛 모습 탐험 일지」에서 서준이가 여러 자료를 함께 본 것이 좋은 까닭을 쓰세요.","answer_guide":{"answer":"예: 사진은 옛 모습을, 증언은 생생한 생활을, 신문은 그때 소식을, 옛이야기는 마을 이름의 까닭을 알려 주어 서로 모자란 것을 채워 주기 때문에 갈대마을 옛 모습을 더 자세하고 정확하게 알 수 있었다.","scoring_points":["자료마다 알려 주는 것을 썼는가","서로 채워 준다고 썼는가","더 정확해진다고 썼는가"]},"explanation":["자료마다","다른 것","함께"],"asset":{"type":"passage","lines":["① 할머니 앨범에서 갈대마을 옛 사진을 찾았다. 초가집이 보였다.","② 박물관에서 맷돌과 다듬잇돌을 보았다.","③ 할아버지께 옛날 장날 이야기를 여쭤 들었다.","④ 도서관에서 갈대마을 이름 이야기를 읽었다. 갈대가 우거졌대.","⑤ 옛 신문에서 「갈대마을에 첫 버스 다녀」 소식을 찾았다.","⑥ 옛날과 오늘의 마을 길 사진을 나란히 놓고 견주었다.","⑦ 알게 된 것을 연표와 보고서로 정리했다.","⑧ 모둠과 영상을 만들어 자막을 넣고 친구들에게 소개했다."],"title":"서준이의 갈대마을 옛 모습 탐험 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_b#25','soc',3,1,'u2','','g3_1_soc_u2_review_b','unit_review','SO3-1-u2-C17',4,'essay','teacher','「달라진 우리 지역」 영상을 만든다면 넣을 장면 세 개를 차례대로 쓰고, 마지막 장면의 자막을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO3-1-u2-C17","difficulty":4,"kind":"essay","stem":"「달라진 우리 지역」 영상을 만든다면 넣을 장면 세 개를 차례대로 쓰고, 마지막 장면의 자막을 쓰세요.","answer_guide":{"answer":"예: ① 옛날 흙길 사진 ② 오늘 넓은 찻길 사진 ③ 두 사진을 나란히 놓은 장면 — 자막 「흙길이 넓은 찻길로 바뀌어 차와 사람이 편하게 다녀요」","scoring_points":["장면 세 개를 썼는가","옛날 → 오늘 차례인가","달라진 점을 담은 자막을 썼는가"]},"explanation":["옛날","오늘","자막"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
