INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_c#8','soc',3,1,'u2','','g3_1_soc_u2_review_c','unit_review','SO3-1-u2-C11',1,'mc','auto','단원 정리: 전시관을 꾸밀 때 가장 먼저 정할 것은 무엇일까요?',ARRAY['SO3-1-u2-X27','SO3-1-u2-X28']::text[],false,'{"seq":8,"concept":"SO3-1-u2-C11","difficulty":1,"kind":"mc","stem":"단원 정리: 전시관을 꾸밀 때 가장 먼저 정할 것은 무엇일까요?","options":[{"t":"전시 주제","correct":true},{"t":"물건값","mis":"SO3-1-u2-X27"},{"t":"간식","mis":"SO3-1-u2-X27"},{"t":"소개 인사","mis":"SO3-1-u2-X28"}],"explanation":["무엇을","보여 줄지","주제"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_c#9','soc',3,1,'u2','','g3_1_soc_u2_review_c','unit_review','SO3-1-u2-C2',2,'mc','auto','단원 정리: 친구와 내가 겪은 중요한 일이 다를 때 바르게 생각한 것은 무엇일까요?',ARRAY['SO3-1-u2-X05']::text[],false,'{"seq":9,"concept":"SO3-1-u2-C2","difficulty":2,"kind":"mc","stem":"단원 정리: 친구와 내가 겪은 중요한 일이 다를 때 바르게 생각한 것은 무엇일까요?","options":[{"t":"사람마다 자라 온 과정이 달라 서로 존중한다","correct":true},{"t":"한 사람이 잘못 겪은 것이다","mis":"SO3-1-u2-X05"},{"t":"모두 똑같이 맞춰야 한다","mis":"SO3-1-u2-X05"},{"t":"다른 친구 이야기는 듣지 않는다","mis":"SO3-1-u2-X05"}],"explanation":["사람마다","달라요.","존중"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
