INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_c#11','soc',3,1,'u2','','g3_1_soc_u2_review_c','unit_review','SO3-1-u2-C8',2,'mc','auto','「서준이의 갈대마을 옛 모습 탐험 일지」 ②의 다듬잇돌과 같은 일을 오늘날 하는 물건은 무엇일까요?',ARRAY['SO3-1-u2-X20']::text[],false,'{"seq":11,"concept":"SO3-1-u2-C8","difficulty":2,"kind":"mc","stem":"「서준이의 갈대마을 옛 모습 탐험 일지」 ②의 다듬잇돌과 같은 일을 오늘날 하는 물건은 무엇일까요?","options":[{"t":"전기다리미","correct":true},{"t":"믹서기","mis":"SO3-1-u2-X20"},{"t":"전기밥솥","mis":"SO3-1-u2-X20"},{"t":"냉장고","mis":"SO3-1-u2-X20"}],"explanation":["다듬잇돌은","옷 펴기","전기다리미"],"asset":{"type":"passage","lines":["① 할머니 앨범에서 갈대마을 옛 사진을 찾았다. 초가집이 보였다.","② 박물관에서 맷돌과 다듬잇돌을 보았다.","③ 할아버지께 옛날 장날 이야기를 여쭤 들었다.","④ 도서관에서 갈대마을 이름 이야기를 읽었다. 갈대가 우거졌대.","⑤ 옛 신문에서 「갈대마을에 첫 버스 다녀」 소식을 찾았다.","⑥ 옛날과 오늘의 마을 길 사진을 나란히 놓고 견주었다.","⑦ 알게 된 것을 연표와 보고서로 정리했다.","⑧ 모둠과 영상을 만들어 자막을 넣고 친구들에게 소개했다."],"title":"서준이의 갈대마을 옛 모습 탐험 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
