INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_c#17','soc',3,1,'u2','','g3_1_soc_u2_review_c','unit_review','SO3-1-u2-C4',3,'error','auto','갈대마을 연표를 만든 친구들의 말이에요. 잘못 말한 친구는 누구일까요?',ARRAY['SO3-1-u2-X14','SO3-1-u2-X10','SO3-1-u2-X12']::text[],false,'{"seq":17,"concept":"SO3-1-u2-C4","difficulty":3,"kind":"error","stem":"갈대마을 연표를 만든 친구들의 말이에요. 잘못 말한 친구는 누구일까요?","options":[{"t":"도윤 — 「가장 나중 일을 맨 왼쪽에 적었어.」","correct":true,"mis_target":"SO3-1-u2-X14"},{"t":"하린 — 「때와 있었던 일을 함께 적었어.」","mis":"SO3-1-u2-X10"},{"t":"수아 — 「마을 일도 연표로 정리할 수 있어.」","mis":"SO3-1-u2-X12"}],"explanation":["왼쪽은","먼저 일","도윤이가 잘못"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_c#18','soc',3,1,'u2','','g3_1_soc_u2_review_c','unit_review','SO3-1-u2-C13',3,'ox','auto','옛 신문에 「첫 버스 다녀」라는 소식이 있다면 그 전에는 버스가 다니지 않았다고 짐작할 수 있어요.',ARRAY['SO3-1-u2-X25']::text[],false,'{"seq":18,"concept":"SO3-1-u2-C13","difficulty":3,"kind":"ox","stem":"옛 신문에 「첫 버스 다녀」라는 소식이 있다면 그 전에는 버스가 다니지 않았다고 짐작할 수 있어요.","answer":"O","reason_options":[{"t":"「첫」은 처음이라는 뜻이라 그 전에는 없었다는 것을 알려 주기 때문에","correct":true},{"t":"신문의 낱말은 옛 모습과 아무 관계가 없기 때문에","mis":"SO3-1-u2-X25"}],"mis":"SO3-1-u2-X25","explanation":["첫","처음","O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_c#19','soc',3,1,'u2','','g3_1_soc_u2_review_c','unit_review','SO3-1-u2-C15',3,'ox','auto','자료를 견줄 때 서로 맞지 않는 내용이 나오면 다른 자료를 더 찾아 확인해요.',ARRAY['SO3-1-u2-X17']::text[],false,'{"seq":19,"concept":"SO3-1-u2-C15","difficulty":3,"kind":"ox","stem":"자료를 견줄 때 서로 맞지 않는 내용이 나오면 다른 자료를 더 찾아 확인해요.","answer":"O","reason_options":[{"t":"여러 자료를 비교해야 옛 모습을 정확히 알 수 있기 때문에","correct":true},{"t":"처음 본 자료만 믿으면 되기 때문에","mis":"SO3-1-u2-X17"}],"mis":"SO3-1-u2-X17","explanation":["맞지 않으면","더 찾아요.","O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_c#20','soc',3,1,'u2','','g3_1_soc_u2_review_c','unit_review','SO3-1-u2-C16',3,'error','auto','조사 보고서를 쓴 친구들의 말이에요. 잘못 말한 친구는 누구일까요?',ARRAY['SO3-1-u2-X35','SO3-1-u2-X08']::text[],false,'{"seq":20,"concept":"SO3-1-u2-C16","difficulty":3,"kind":"error","stem":"조사 보고서를 쓴 친구들의 말이에요. 잘못 말한 친구는 누구일까요?","options":[{"t":"은솔 — 「조사한 내용만 쓰고 알게 된 점은 뺐어.」","correct":true,"mis_target":"SO3-1-u2-X35"},{"t":"도윤 — 「알게 된 점을 마지막에 정리했어.」","mis":"SO3-1-u2-X35"},{"t":"하린 — 「옛날과 오늘을 비교한 내용을 썼어.」","mis":"SO3-1-u2-X08"}],"explanation":["알게 된 점","꼭","은솔이가 잘못"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_c#21','soc',3,1,'u2','','g3_1_soc_u2_review_c','unit_review','SO3-1-u2-C11',3,'error','auto','전시관을 꾸민 친구들의 말이에요. 잘못한 친구는 누구일까요?',ARRAY['SO3-1-u2-X27','SO3-1-u2-X28']::text[],false,'{"seq":21,"concept":"SO3-1-u2-C11","difficulty":3,"kind":"error","stem":"전시관을 꾸민 친구들의 말이에요. 잘못한 친구는 누구일까요?","options":[{"t":"지호 — 「주제는 옛날 부엌인데 새 운동화도 같이 놓았어.」","correct":true,"mis_target":"SO3-1-u2-X27"},{"t":"수아 — 「물건마다 설명 카드를 붙였어.」","mis":"SO3-1-u2-X28"},{"t":"예린 — 「무엇을 왜 전시했는지 소개했어.」","mis":"SO3-1-u2-X28"}],"explanation":["주제에","맞나요?","지호가 잘못"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_c#22','soc',3,1,'u2','','g3_1_soc_u2_review_c','unit_review','SO3-1-u2-C12',3,'error','auto','단원을 정리한 친구들의 말이에요. 잘못 말한 친구는 누구일까요?',ARRAY['SO3-1-u2-X30','SO3-1-u2-X29','SO3-1-u2-X17']::text[],false,'{"seq":22,"concept":"SO3-1-u2-C12","difficulty":3,"kind":"error","stem":"단원을 정리한 친구들의 말이에요. 잘못 말한 친구는 누구일까요?","options":[{"t":"서준 — 「오늘 우리 모습은 시간이 흘러도 과거가 되지 않아.」","correct":true,"mis_target":"SO3-1-u2-X30"},{"t":"은솔 — 「옛것을 알면 오늘이 더 잘 보여.」","mis":"SO3-1-u2-X29"},{"t":"도윤 — 「여러 자료로 옛 모습을 알 수 있어.」","mis":"SO3-1-u2-X17"}],"explanation":["오늘도","언젠가 과거","서준이가 잘못"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_c#23','soc',3,1,'u2','','g3_1_soc_u2_review_c','unit_review','SO3-1-u2-C4',4,'essay','teacher','우리 학교가 걸어온 길을 연표로 만든다면 담고 싶은 일 세 가지를 시간 순서로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO3-1-u2-C4","difficulty":4,"kind":"essay","stem":"우리 학교가 걸어온 길을 연표로 만든다면 담고 싶은 일 세 가지를 시간 순서로 쓰세요.","answer_guide":{"answer":"예: 학교가 처음 문을 엶 → 새 건물을 지음 → 올해 도서관을 새로 꾸밈","scoring_points":["세 가지를 썼는가","시간 순서대로 썼는가","학교의 일을 썼는가"]},"explanation":["처음","그 뒤","올해"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_c#24','soc',3,1,'u2','','g3_1_soc_u2_review_c','unit_review','SO3-1-u2-C8',4,'essay','teacher','옛날 부엌 물건과 오늘날 부엌 물건을 하나씩 짝지어 쓰고, 그 짝으로 알 수 있는 생활의 변화를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO3-1-u2-C8","difficulty":4,"kind":"essay","stem":"옛날 부엌 물건과 오늘날 부엌 물건을 하나씩 짝지어 쓰고, 그 짝으로 알 수 있는 생활의 변화를 쓰세요.","answer_guide":{"answer":"예: 가마솥 — 전기밥솥. 옛날에는 아궁이에 불을 때서 밥을 지었지만 오늘날에는 전기로 쉽고 빠르게 밥을 짓는다.","scoring_points":["같은 일을 하는 짝을 썼는가","생활의 변화를 썼는가","옛날과 오늘을 견주었는가"]},"explanation":["옛 물건","오늘 물건","변화"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_c#25','soc',3,1,'u2','','g3_1_soc_u2_review_c','unit_review','SO3-1-u2-C12',4,'essay','teacher','오늘 우리 생활을 먼 훗날에 전할 물건 두 가지를 고르고, 그것이 미래에 어떤 자료가 될지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO3-1-u2-C12","difficulty":4,"kind":"essay","stem":"오늘 우리 생활을 먼 훗날에 전할 물건 두 가지를 고르고, 그것이 미래에 어떤 자료가 될지 쓰세요.","answer_guide":{"answer":"예: 우리 반 단체 사진 — 미래 사람들이 지금 어린이들의 옷차림과 교실 모습을 알 수 있다. / 내 일기 — 지금 어린이가 하루를 어떻게 보냈는지 알려 주는 자료가 된다.","scoring_points":["오늘의 물건 두 가지를 골랐는가","미래에 알려 줄 것을 썼는가","오늘도 과거가 된다는 생각이 드러나는가"]},"explanation":["오늘의 것","먼 훗날","자료"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_d#1','soc',3,1,'u2','','g3_1_soc_u2_review_d','unit_review','SO3-1-u2-C1',1,'mc','auto','단원 정리: 시간이 흐르는 방향을 바르게 나타낸 것은 무엇일까요?',ARRAY['SO3-1-u2-X02']::text[],false,'{"seq":1,"concept":"SO3-1-u2-C1","difficulty":1,"kind":"mc","stem":"단원 정리: 시간이 흐르는 방향을 바르게 나타낸 것은 무엇일까요?","options":[{"t":"과거 → 현재 → 미래","correct":true},{"t":"미래 → 과거 → 현재","mis":"SO3-1-u2-X02"},{"t":"현재 → 과거 → 미래","mis":"SO3-1-u2-X02"},{"t":"미래 → 현재 → 과거","mis":"SO3-1-u2-X02"}],"explanation":["지난 때","지금","앞으로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_d#2','soc',3,1,'u2','','g3_1_soc_u2_review_d','unit_review','SO3-1-u2-C4',1,'mc','auto','단원 정리: 연표에서 가장 중요한 것은 무엇일까요?',ARRAY['SO3-1-u2-X11']::text[],false,'{"seq":2,"concept":"SO3-1-u2-C4","difficulty":1,"kind":"mc","stem":"단원 정리: 연표에서 가장 중요한 것은 무엇일까요?","options":[{"t":"일이 일어난 시간 순서","correct":true},{"t":"예쁜 색깔","mis":"SO3-1-u2-X11"},{"t":"글자 크기","mis":"SO3-1-u2-X11"},{"t":"종이 모양","mis":"SO3-1-u2-X11"}],"explanation":["연표는","순서","시간 순서"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_d#3','soc',3,1,'u2','','g3_1_soc_u2_review_d','unit_review','SO3-1-u2-C9',1,'mc','auto','단원 정리: 그때를 직접 겪은 분께 듣는 옛이야기를 무엇이라고 할까요?',ARRAY['SO3-1-u2-X22']::text[],false,'{"seq":3,"concept":"SO3-1-u2-C9","difficulty":1,"kind":"mc","stem":"단원 정리: 그때를 직접 겪은 분께 듣는 옛이야기를 무엇이라고 할까요?","options":[{"t":"증언","correct":true},{"t":"포스터","mis":"SO3-1-u2-X22"},{"t":"지도","mis":"SO3-1-u2-X22"},{"t":"자막","mis":"SO3-1-u2-X22"}],"explanation":["겪은 분","직접 들어요.","증언"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_d#4','soc',3,1,'u2','','g3_1_soc_u2_review_d','unit_review','SO3-1-u2-C7',1,'mc','auto','「서준이의 갈대마을 옛 모습 탐험 일지」 ①에서 서준이가 옛 모습을 알아본 자료는 무엇일까요?',ARRAY['SO3-1-u2-X32']::text[],false,'{"seq":4,"concept":"SO3-1-u2-C7","difficulty":1,"kind":"mc","stem":"「서준이의 갈대마을 옛 모습 탐험 일지」 ①에서 서준이가 옛 모습을 알아본 자료는 무엇일까요?","options":[{"t":"옛 사진","correct":true},{"t":"옛 신문","mis":"SO3-1-u2-X32"},{"t":"증언","mis":"SO3-1-u2-X32"},{"t":"영상","mis":"SO3-1-u2-X32"}],"explanation":["①을 봐요.","앨범","옛 사진"],"asset":{"type":"passage","lines":["① 할머니 앨범에서 갈대마을 옛 사진을 찾았다. 초가집이 보였다.","② 박물관에서 맷돌과 다듬잇돌을 보았다.","③ 할아버지께 옛날 장날 이야기를 여쭤 들었다.","④ 도서관에서 갈대마을 이름 이야기를 읽었다. 갈대가 우거졌대.","⑤ 옛 신문에서 「갈대마을에 첫 버스 다녀」 소식을 찾았다.","⑥ 옛날과 오늘의 마을 길 사진을 나란히 놓고 견주었다.","⑦ 알게 된 것을 연표와 보고서로 정리했다.","⑧ 모둠과 영상을 만들어 자막을 넣고 친구들에게 소개했다."],"title":"서준이의 갈대마을 옛 모습 탐험 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
