INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_d#15','soc',3,1,'u2','','g3_1_soc_u2_review_d','unit_review','SO3-1-u2-C12',2,'mc','auto','단원 정리: 지역 축제에 옛 모습을 기리는 행사가 많은 까닭은 무엇일까요?',ARRAY['SO3-1-u2-X29','SO3-1-u2-X02']::text[],false,'{"seq":15,"concept":"SO3-1-u2-C12","difficulty":2,"kind":"mc","stem":"단원 정리: 지역 축제에 옛 모습을 기리는 행사가 많은 까닭은 무엇일까요?","options":[{"t":"옛 생활을 잊지 않고 다음 세대에 전하려고","correct":true},{"t":"옛것이 쓸모없어서","mis":"SO3-1-u2-X29"},{"t":"아무 까닭 없이","mis":"SO3-1-u2-X29"},{"t":"옛날로 돌아가려고","mis":"SO3-1-u2-X02"}],"explanation":["잊지 않고","전하려고","기려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
