INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_d#17','soc',3,1,'u2','','g3_1_soc_u2_review_d','unit_review','SO3-1-u2-C4',3,'ox','auto','마을에 있었던 일도 때와 함께 시간 순서대로 적으면 연표가 돼요.',ARRAY['SO3-1-u2-X12']::text[],false,'{"seq":17,"concept":"SO3-1-u2-C4","difficulty":3,"kind":"ox","stem":"마을에 있었던 일도 때와 함께 시간 순서대로 적으면 연표가 돼요.","answer":"O","reason_options":[{"t":"연표는 나 · 가족 · 학교 · 마을의 일을 모두 시간 순서로 정리할 수 있기 때문에","correct":true},{"t":"연표는 사람 한 명의 일만 적는 표이기 때문에","mis":"SO3-1-u2-X12"}],"mis":"SO3-1-u2-X12","explanation":["마을 일도","때와 함께","O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_d#18','soc',3,1,'u2','','g3_1_soc_u2_review_d','unit_review','SO3-1-u2-C9',3,'error','auto','옛 장날 이야기를 알아본 친구들의 말이에요. 잘못 말한 친구는 누구일까요?',ARRAY['SO3-1-u2-X22','SO3-1-u2-X17']::text[],false,'{"seq":18,"concept":"SO3-1-u2-C9","difficulty":3,"kind":"error","stem":"옛 장날 이야기를 알아본 친구들의 말이에요. 잘못 말한 친구는 누구일까요?","options":[{"t":"예린 — 「장날 이야기는 장에 가 본 적 없는 동생에게 들었어.」","correct":true,"mis_target":"SO3-1-u2-X22"},{"t":"서준 — 「장에 다니신 할아버지께 여쭤 들었어.」","mis":"SO3-1-u2-X22"},{"t":"지호 — 「옛 신문의 장날 소식도 찾아봤어.」","mis":"SO3-1-u2-X17"}],"explanation":["증언은","겪은 분께","예린이가 잘못"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_d#19','soc',3,1,'u2','','g3_1_soc_u2_review_d','unit_review','SO3-1-u2-C15',3,'mc','auto','단원 정리: 옛 장터를 조사할 때 자료를 가장 잘 모은 것은 무엇일까요?',ARRAY['SO3-1-u2-X17','SO3-1-u2-X06','SO3-1-u2-X16']::text[],false,'{"seq":19,"concept":"SO3-1-u2-C15","difficulty":3,"kind":"mc","stem":"단원 정리: 옛 장터를 조사할 때 자료를 가장 잘 모은 것은 무엇일까요?","options":[{"t":"장터 옛 사진 · 장날 소식 옛 신문 · 장에 다니신 어른의 증언","correct":true},{"t":"장터 옛 사진 한 장","mis":"SO3-1-u2-X17"},{"t":"내일 장보기 목록","mis":"SO3-1-u2-X06"},{"t":"상상해 그린 장터 그림","mis":"SO3-1-u2-X16"}],"explanation":["사진","신문","증언"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_d#20','soc',3,1,'u2','','g3_1_soc_u2_review_d','unit_review','SO3-1-u2-C16',3,'ox','auto','문화 해설사의 설명을 들으면 옛 건축물에 얽힌 생활을 더 쉽게 알 수 있어요.',ARRAY['SO3-1-u2-X36']::text[],false,'{"seq":20,"concept":"SO3-1-u2-C16","difficulty":3,"kind":"ox","stem":"문화 해설사의 설명을 들으면 옛 건축물에 얽힌 생활을 더 쉽게 알 수 있어요.","answer":"O","reason_options":[{"t":"문화 해설사는 지역의 옛 모습을 찾아 알기 쉽게 설명해 주는 사람이기 때문에","correct":true},{"t":"문화 해설사는 옛 건축물을 새로 짓는 사람이기 때문에","mis":"SO3-1-u2-X36"}],"mis":"SO3-1-u2-X36","explanation":["해설사","설명","O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_d#21','soc',3,1,'u2','','g3_1_soc_u2_review_d','unit_review','SO3-1-u2-C11',3,'ox','auto','전시관을 꾸밀 때 물건을 많이 모으기만 하면 주제는 없어도 돼요.',ARRAY['SO3-1-u2-X27']::text[],false,'{"seq":21,"concept":"SO3-1-u2-C11","difficulty":3,"kind":"ox","stem":"전시관을 꾸밀 때 물건을 많이 모으기만 하면 주제는 없어도 돼요.","answer":"X","reason_options":[{"t":"주제가 있어야 무엇을 보여 주려는지 잘 전해지기 때문에","correct":true},{"t":"물건이 많으면 뜻이 저절로 전해지기 때문에","mis":"SO3-1-u2-X27"}],"mis":"SO3-1-u2-X27","explanation":["주제가","먼저","X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_d#22','soc',3,1,'u2','','g3_1_soc_u2_review_d','unit_review','SO3-1-u2-C12',3,'ox','auto','우리 지역 축제에서 옛 모습을 기리는 것은 옛 생활을 잊지 않고 전하려는 마음 때문이에요.',ARRAY['SO3-1-u2-X29']::text[],false,'{"seq":22,"concept":"SO3-1-u2-C12","difficulty":3,"kind":"ox","stem":"우리 지역 축제에서 옛 모습을 기리는 것은 옛 생활을 잊지 않고 전하려는 마음 때문이에요.","answer":"O","reason_options":[{"t":"옛 생활을 기억하고 다음 세대에 이어 주려는 것이기 때문에","correct":true},{"t":"옛것은 쓸모없어 한 번 보고 버리려는 것이기 때문에","mis":"SO3-1-u2-X29"}],"mis":"SO3-1-u2-X29","explanation":["기리기","전하기","O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_d#23','soc',3,1,'u2','','g3_1_soc_u2_review_d','unit_review','SO3-1-u2-C3',4,'essay','teacher','가족이나 학교의 옛일을 알아보기 위해 할 수 있는 조사 방법 세 가지를 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO3-1-u2-C3","difficulty":4,"kind":"essay","stem":"가족이나 학교의 옛일을 알아보기 위해 할 수 있는 조사 방법 세 가지를 쓰세요.","answer_guide":{"answer":"예: 가족 앨범과 옛 사진을 본다. 할머니 · 할아버지와 면담한다. 학교 누리집의 기록을 살펴본다.","scoring_points":["방법 세 가지를 썼는가","방법이 알맞은가","지난 일을 알아보는 방법인가"]},"explanation":["사진","면담","누리집"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_d#24','soc',3,1,'u2','','g3_1_soc_u2_review_d','unit_review','SO3-1-u2-C14',4,'essay','teacher','우리 동네에 새로 이름을 붙인다면 어떤 이름을 짓고 싶은지, 그 이름에 동네의 어떤 모습을 담았는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO3-1-u2-C14","difficulty":4,"kind":"essay","stem":"우리 동네에 새로 이름을 붙인다면 어떤 이름을 짓고 싶은지, 그 이름에 동네의 어떤 모습을 담았는지 쓰세요.","answer_guide":{"answer":"예: 「은행나무골」 — 우리 동네 길가에 은행나무가 많아 가을이면 노랗게 물드는 모습을 담았다. 먼 훗날 사람들이 이 이름으로 지금 우리 동네 모습을 알 수 있을 것이다.","scoring_points":["이름을 지었는가","이름에 담은 모습을 썼는가","땅 이름에 옛 모습이 담긴다는 생각이 드러나는가"]},"explanation":["동네의","모습","이름에 담기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_soc_u2_review_d#25','soc',3,1,'u2','','g3_1_soc_u2_review_d','unit_review','SO3-1-u2-C12',4,'essay','teacher','2단원 「일상에서 만나는 과거」에서 배운 것 가운데 가장 기억에 남는 것 두 가지를 쓰고, 앞으로 생활에서 어떻게 쓸지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO3-1-u2-C12","difficulty":4,"kind":"essay","stem":"2단원 「일상에서 만나는 과거」에서 배운 것 가운데 가장 기억에 남는 것 두 가지를 쓰고, 앞으로 생활에서 어떻게 쓸지 쓰세요.","answer_guide":{"answer":"예: 연표로 일의 순서를 정리하는 법과 여러 자료로 옛 모습을 알아보는 법이 기억에 남는다. 앞으로 가족의 옛일을 연표로 정리하고, 동네의 옛 모습이 궁금하면 사진과 어른의 증언을 함께 찾아보겠다.","scoring_points":["배운 것 두 가지를 썼는가","내용이 바른가","생활에서의 쓰임을 썼는가"]},"explanation":["기억에 남는 것","두 가지","생활 속으로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
